window.TONGUE_KB = {"meta":{"title":"图解舌诊：伸伸舌头百病消","author":"罗大伦","publisher":"江西科学技术出版社","isbn":"978-7-5390-5294-6","total_pages":205,"medical_disclaimer":{"page":191,"statement":"本书所讲舌诊知识仅作为日常健康筛查手段（只给怀疑的权利，不给诊断的权利）；若怀疑身体有问题，务必请当地执业医师确诊，且任何药方均为暂时补救措施，健康根本在于良好情绪、合理饮食与积极锻炼（见后记 p.191-192）。"}},"pre_checks":[{"id":"pc_dynamic_baseline","title":"树立动态观舌理念：重在对比自身既往基线","category":"核心观舌理念","description":"舌诊没有一刀切的绝对标准，‘淡红舌、薄白苔’（p.35）仅作基本健康参考；个体胖瘦、体质及四季气候冷暖（如冬季舌质可微偏白、夏季6月气血充盈可略偏红润，p.50）均有差异，必须通过长期观察自身舌象的动态变化趋势来识别异常（如原本薄苔突然变厚，与动态监测个人检验指标趋势同理，p.34-36）。","false_positive_risk":"若用单一死标准套用所有人，易将胖人正常偏胖舌或瘦人正常偏瘦舌误判为病态，或漏掉自身舌象虽未越界但正在持续偏离基线的早期隐患（p.35-36）。","page":34},{"id":"pc_colored_food_drink","title":"食用有色食物或饮用橘子汁、浓茶、咖啡、酒后勿看舌象","category":"饮食染苔排除","description":"正常舌苔为淡白色薄白苔，观察舌象或看中医前不要喝橘子汁、浓茶、咖啡、酒类，也不要吃其他有颜色的食物，避免人为改变舌苔颜色与脉搏速率（p.36-37）。","false_positive_risk":"有色食物与饮品会造成染苔假象；尤其刚喝完酒不仅会把舌苔染黄，还会加速血液循环导致脉搏跳动变快，极易被误判为体内实热证（p.37）。","page":36},{"id":"pc_no_morning_check","title":"晨起不要看舌象，须在白天正常状态下观察","category":"观察时段排除","description":"睡了一夜刚起床时血液循环缓慢、血液尚未充盈，平卧使体内湿气浮现于舌，且夜间打鼾张嘴呼吸会让空气直接接触舌面微生物从而改变微环境，故切勿一大早起床就看舌象或拍舌照，应在白天观察（p.37-38）。","false_positive_risk":"晨起舌象往往呈现舌质颜色偏浅、舌苔变厚且舌面干燥，均属夜间生理假象，不能代表白天的真实身体状态，据此调理往往无效（p.37-38）。","page":37},{"id":"pc_after_meal_30min","title":"尽量不要在饭后半小时内看舌象","category":"进食干扰排除","description":"吃饭时舌头充分参与食物搅拌和咀嚼，血液循环加快使舌体充血，同时食物纤维摩擦与淀粉、乳豆制品附着会直接改变舌苔厚薄与腻度，故饭后半小时内不宜看舌象或看中医（p.28、p.38）。","false_positive_risk":"饭后充血会使舌质变红误判为有热；吃芹菜等富含植物纤维的食物会磨薄甚至磨掉舌苔；吃富含淀粉的食物会使舌苔变厚腻；喝牛奶或豆浆会使舌苔变白腻（p.28、p.38）。","page":38},{"id":"pc_lighting_environment","title":"避开有色灯光、冷光灯、有色玻璃与直射强光（首选白天背阳间接日光）","category":"光源环境标准","description":"看舌象与拍舌照最标准的环境是白天背着阳光处的‘间接日光’（正午间接日光最标准，日常白天背阳处即可）；避免在色灯、冷光灯、日光灯（初学者尤不建议）、有色玻璃下，以及朝阳、夕阳或阳光直射下看舌象（p.39）。","false_positive_risk":"冷光灯照射会使正常脸色与舌色显得惨白铁青；绿色等有色玻璃过滤光线会使舌头带淡绿色；阳光直射下伸舌会显得全都又白又亮，均属偏色假象（p.39）。","page":39},{"id":"pc_antibiotics_additives","title":"服用某些抗生素或食用含化学添加剂食品后勿看舌象","category":"药物与添加剂排除","description":"部分人群因个体体质差异，在服用某些抗生素，或吃到商家加入某些化学添加剂的食物（如问题酸菜）后，舌苔会出现短期变黑现象，观舌前需核查近期服药与特殊饮食史（p.39）。","false_positive_risk":"抗生素或化学添加剂所致的黑苔假象，易被误判为外感热极焦黑苔或寒湿极重黑苔（p.39、p.56-57）。","page":39},{"id":"pc_menstruation_red_tip","title":"女性月经期及月经前后1～2天看舌象须说明情况","category":"特殊生理期说明","description":"舌尖除对应心与小肠外，还对应下焦生殖系统；女性在月经期或月经前后一两天内，舌尖常会出现生理性变红，看中医或自查时必须主动说明并排除该阶段（p.40、p.75）。","false_positive_risk":"若未排除月经期或经期前后1～2天的特殊生理因素，极易把生理性舌尖变红误判为心火亢盛（p.40、p.75）。","page":40},{"id":"pc_vallate_papillae_normal","title":"舌根尽头大突起‘轮廓乳头’属正常生理构造","category":"正常解剖识别","description":"每个人的舌根最后部都有几个较大的突起，医学上称为‘轮廓乳头’，嘴张得够大、舌头伸得够长即可看见；舌体表面散布的细小红点为含丰富毛细血管、与味觉相关的‘蕈状乳头’（p.53、p.76）。","false_positive_risk":"初学者深伸舌头看到舌根部的轮廓乳头时，常惊慌误以为舌根长了肿物或异物（p.53）。","page":53},{"id":"pc_no_makeup_lipstick","title":"看诊与观舌前尽量别化妆、勿涂口红","category":"望诊修饰排除","description":"中医望诊需同步观察面色明暗与嘴唇本色，看中医或观察气血状态前应保持素颜，切勿化妆，尤其不要涂口红（p.21、p.79）。","false_positive_risk":"化妆与涂口红会把嘴唇涂成鲜红色，掩盖嘴唇边缘真实的瘀象，导致无法察觉气血运行受阻与体内血瘀（p.79）。","page":79},{"id":"pc_short_lingual_frenulum","title":"天生舌系带过短致舌头伸不长并非心气不足","category":"先天生理差异","description":"部分人天生舌下系带特别短，伸舌时舌尖即被牵拉回去而伸不长，且舌头无法向上翘起舔上唇，因而无法常规观察舌下静脉（p.82）。","false_positive_risk":"易将天生舌系带过短导致的伸舌受限，误判为‘心气不足’或中风病危‘舌萎’正气大伤（p.41、p.46、p.82）。","page":82},{"id":"pc_congenital_deviated_tip","title":"排除天生舌尖偏斜等生理性常态（兼排牙齿畸形压痕）","category":"先天生理差异","description":"正常舌头伸出时舌尖朝前，但少数人天生舌尖就是偏的，属生理性情况（同理，牙齿生长畸形日夜压迫舌边也会形成机械性齿痕，p.69）；唯有以往舌尖正常而近期变偏才需警惕瘀血（p.114-115）。","false_positive_risk":"若不排除先天生理性舌尖偏斜，易误判为体内瘀血或同侧脑血管堵塞隐患；若不排除牙齿畸形，易将物理压痕误判为脾虚水湿齿痕（p.69、p.114-115）。","page":114},{"id":"pc_pregnancy_normal_stasis","title":"孕妇舌现瘀血指征属气血凝聚正常现象，严禁化瘀","category":"妊娠安全门禁","description":"不要按常规病态给孕妇看舌象判瘀血：胎儿形成的过程就是气血凝聚的过程，因此孕妇舌象显示有瘀血指征属于正常生理现象（p.119）。","false_positive_risk":"若将孕妇正常的育胎气血凝聚舌象当成病理瘀血，擅自使用活血化瘀药物调理，极易导致伤胎动胎等严重后果（p.119）。","page":119}],"tongue_zones":[{"id":"zone_tip","name":"舌尖","organ":"心、小肠（兼映下焦生殖系统：妇科、前列腺）","location_desc":"舌体最前端尖部区域（p.28-29 脏腑分区图最前缘，p.75 补充下焦映射）","svg_zone_id":"tip","indicators":["非经期舌尖变红提示有心火（常因发愁担忧思虑引起）；女性月经期或前后1～2天舌尖红属生理假象（p.40、p.75、p.179）","兼映下焦生殖系统：女性下焦有热或有妇科疾病、男性有前列腺疾病时，舌尖也会发红（p.75）","舌尖出现明显瘀点提示瘀血正在形成；排除天生偏斜后，舌尖往哪侧偏提示哪侧头部血管有堵塞隐患（p.112、p.114-115）"],"page":29},{"id":"zone_front","name":"舌尖到中部之间","organ":"肺","location_desc":"舌尖后方至舌中部之间的前中段区域（p.28-29 脏腑分区图舌尖与舌中之间）","svg_zone_id":"front","indicators":["对应上焦肺系功能与外感表里气机状态（p.28-29）","若蕈状乳头偏大、红点集中在舌尖到舌中部，提示体内有湿热、上焦热盛（儿童见此红点须以清热为主而非滋阴，p.76-77）"],"page":29},{"id":"zone_center","name":"舌中","organ":"脾、胃","location_desc":"舌体正中间区域（p.28-29 脏腑分区图中央区域）","svg_zone_id":"center","indicators":["舌苔为胃气所生，身体功能正常时舌体正中间铺薄白苔（p.25-26、p.40、p.53）","舌苔变厚腻提示脾胃运化失常、水湿或痰湿内停；舌苔过薄或消失提示胃气虚弱或阴虚有热（p.40-42、p.55）","舌中间出现特别明显的深裂纹甚至分叉（非正常隐约浅沟），提示脾胃功能差、脾胃气不足无力生苔弥补舌中沟（p.80）"],"page":29},{"id":"zone_left","name":"舌左侧","organ":"肝","location_desc":"伸舌者自身的舌体左侧边缘区域（面对他人或正面照片如p.29图时位于画面右侧，照镜子自观时仍在镜面左侧，p.28-29）","svg_zone_id":"left","indicators":["对应肝经气血疏泄；肝胆位置集中发红提示肝胆有火或肝胆热瘀（p.28-29、p.75）","舌两侧出现明显牙齿印（齿痕），排除牙齿畸形后提示气虚、水湿内停致舌体肿胀（p.68-69）","舌边发红伴舌形尖尖提示肝气郁结；舌两侧见青色或黑色瘀点、瘀斑提示体内瘀血很严重（p.112-113、p.176）"],"page":28},{"id":"zone_right","name":"舌右侧","organ":"胆","location_desc":"伸舌者自身的舌体右侧边缘区域（面对他人或正面照片如p.29图时位于画面左侧，照镜子自观时仍在镜面右侧，p.28-29）","svg_zone_id":"right","indicators":["对应胆腑气机；与舌左侧合参判断肝胆火旺、气机郁滞或湿热内蕴（p.28-29、p.75）","舌两侧齿痕明显反映正气不足、脾虚湿重（p.68-69）","舌两侧出现黑色或青色瘀点、瘀斑提示瘀血严重（p.112-113）"],"page":28},{"id":"zone_root","name":"舌中到根部","organ":"肾、膀胱","location_desc":"舌中间向后至舌根部区域（舌根尽头有正常生理突起‘轮廓乳头’，p.28-29、p.53）","svg_zone_id":"root","indicators":["对应下焦肾与膀胱的温煦气化及水液排泄功能（p.28-29）","舌后半部苔厚腻伴裂纹提示体内痰湿积聚（p.200）；舌根部大突起为轮廓乳头，人人皆有，切勿误认为长肿物（p.53）"],"page":28},{"id":"zone_sublingual","name":"舌下两条静脉","organ":"全身血脉（全身血瘀窗口）","location_desc":"张口将舌尖翘起舔上嘴唇时露出的舌下两条静脉（舌系带天生过短者无法翘舌查看，p.58、p.82、p.113）","svg_zone_id":"sublingual","indicators":["正常情况下两条舌下静脉呈淡蓝色，直径不超过2毫米（p.113）","无论身体何处有瘀血舌下都会反映：若舌下两条静脉又黑又粗、直径超2毫米并向四周分叉怒张，说明体内瘀血很严重（p.58、p.113-114）","当舌面舌苔较满掩盖瘀斑时，可抬起舌头看舌下静脉核实是否存在瘀血（p.117）"],"page":113},{"id":"zone_whole","name":"全舌舌体与整体舌苔","organ":"全身正气气血阴阳与脾胃水湿全局","location_desc":"整个椭圆形舌体肌肉脉络组织（舌质，重点看舌边未被舌苔覆盖的一圈半透明黏膜）与铺于舌面的整体舌苔微生态（p.25、p.32、p.46-47、p.53）","svg_zone_id":"whole","indicators":["舌质颜色相对稳定，反映正气、气血充盈与寒热：淡红为正常；偏淡白主血虚、外寒或阳虚；变红、绛至青紫主外感温热、实热、阴虚内热或血瘀（p.47-52、p.58）","整体舌苔变化灵敏，反映正邪消长：薄白露边为正常；苔满布厚腻主水湿痰饮邪气盛；苔过薄或退去主胃气虚弱或阴虚正气不足（p.53、p.55-57）","全舌神态形体反映虚损程度：舌体胖大多脾虚湿盛；干枯瘦小、颤抖或伸缩困难（舌萎）提示正气大伤、阴津亏乏或中风危重（p.41、p.46、p.81）"],"page":46}],"chapters":[{"id":"ch01","chapter_num":1,"title":"最好的体检专家是自己","subtitle":"中医望诊源流、舌诊解剖直观性与日常自我健康筛查","page_start":20,"page_end":32,"core_thesis":"诊断是维护健康的第一道‘火车道岔’，而舌诊因舌体包裹半透明黏膜、毛细血管丰富且舌苔微环境灵敏，是中医四诊‘望而知之谓之神’中最直观易学的手段；普通人学会日观动态舌象并掌握舌面脏腑分区，就能把疾病消灭在萌芽状态并避免过度体检与误治。","chain_of_thought":["由中医四诊‘神、圣、工、巧’之首的望诊切入：名医（如朱丹溪记形色性情）进门先望面色形态，但色诊（如王鸿谟所言）难于文字传授，唯舌诊最直观可学（p.21-22）。","梳理舌诊发展脉络：金元时期敖氏著首部专著《敖氏伤寒金镜录》（彩图配注文字色标对应伤寒六经），明代太医院院长薛立斋于南京翻印推广，明末吴又可《温疫论》借黄苔红舌确证瘟疫热邪，至清代随温病学派拓展到内伤病而体系大成，现代更从丝状乳头、食物残渣与微生物揭示其灵敏机制（p.22-24、p.32）。","阐明舌诊解剖优势并与闻问切对比：皮肤多层遮挡肌肉，而舌黏膜半透明可直接观测血液充盈与寒热（舌质）及脾胃湿浊功能（舌苔）；相比‘心中了了，指下难明’的切脉、失传较多的听音律闻诊（张景岳闻歌声、听尾音辨中气）及《十问歌》问病史，老百姓自观动态舌象能补足医生仅见就诊片刻（如空腹或喝牛奶后）的局限（p.25-28）。","建立舌面脏腑空间映射（舌尖心小肠、舌尖至中肺、舌中脾胃、左肝右胆、中至根肾膀胱，p.28-29），并以作者早年精读叶天士《临证指南医案》却开方无效、后考取北中医梁嵘教授博士盲测对照3000多张舌图与证候资料的亲历，印证‘先看舌定大方向、脉问作验证’的实用价值（p.29-32）。"],"key_takeaways":["诊断如铺火车道岔，方向一旦走反（如从上海去北京却往南飞广州），药力越猛患者受害越深（p.30）。","舌头外包半透明黏膜：舌质（舌边未覆苔处）反映正气、血液充盈与体温寒热；舌苔反映身体功能状态与水湿、痰湿轻重（p.25-26、p.32）。","舌部脏腑对应基线：左肝右胆，舌尖心与小肠，舌尖至中部之间肺，舌中脾胃，舌中至根部肾与膀胱（p.28-29）。","医生只能看到就诊一瞬间的片段舌象，唯有自己日常动态观察舌象，才能未雨绸缪筛查亚健康、避免慢病大病及过度医疗（p.26、p.28）。"]},{"id":"ch02","chapter_num":2,"title":"如何在最短时间内学会舌诊","subtitle":"动态观舌原则、六大假象排除条件与正邪转归四大判断","page_start":33,"page_end":44,"core_thesis":"学会舌诊的捷径在于先立规矩后辨病机：摒弃一刀切标准、以‘淡红舌、薄白苔’为参考基线做个体动态对比，严格排除染色饮食、晨起、饭后半小时、偏色光源、抗生素/添加剂与经期六类假象后，即可从舌象准确判断正气虚实、病邪轻重、六淫内伤病性与调理方法对错。","chain_of_thought":["确立动态观舌第一理念：胖瘦体质各异故无绝对标准舌象，如同西医反思一刀切指标（何健博士动态观测理念及鲍威尔将军肿瘤指标上升早期发现案例），必须与自己平日正常舌象比变化（p.34-36）。","逐一排除六种观舌假象门禁：①有色饮食与饮酒（染黄苔且酒精加速脉搏酷似热证）；②晨起勿看（血循慢舌浅、打鼾张嘴干、卧睡湿聚苔厚）；③饭后30分钟内勿看（咀嚼充血变红、芹菜磨苔、淀粉厚腻、牛奶豆浆白腻）；④偏色光源勿看（避开色灯、冷光灯、有色玻璃与直射日光，取白天背阳间接日光）；⑤某些抗生素或化学添加剂（如酸菜）致黑苔；⑥女性经期或前后1～2天舌尖红需说明（p.36-40）。","建立从舌象审正气虚损的五项指征：舌苔消失（胃气虚或阴虚热）、舌苔变厚（正虚痰湿重）、舌色非淡红（淡白主血虚或阳虚）、舌体颤抖或伸舌费劲（正气大伤、阴津亏乏肝风内动）、舌体瘦小干枯（正气大虚）（p.40-41）。","延伸至辨邪气盛衰、病邪性质与调理转归：凭舌苔厚腻与舌体胖大直观锁定闻问切最难判的湿邪，区分外感六淫与内伤痰湿瘀血；并以干预后舌象是否真正改变（而非仅症状暂缓，如肝气不舒需兼养心、祛湿苔退后衔接补脾）检验调理方案是否对路（p.41-44）。"],"key_takeaways":["观舌最标准条件：白天背阳处间接日光下，避开晨起、饭后半小时内及有色饮食饮酒干扰，女性经期或前后1～2天舌尖红须排除（p.36-40）。","正气不足的五大舌象警报：舌苔消失、舌苔变厚、舌色偏离淡红、舌体颤抖或伸舌费劲、舌体干枯瘦小（p.40-41）。","湿邪最直观的标尺是舌苔：舌苔又厚又腻甚至舌体胖大，直接说明湿气重乃至化痰，无需被模棱两可的问诊绕晕（p.41-43）。","症状减轻但舌象未变说明病根仍在（尤其情绪所致的肝气不舒舌象），唯有舌象随之改善才代表调理真正见效（p.43）。"]},{"id":"ch03","chapter_num":3,"title":"看舌象主要看舌质和舌苔","subtitle":"舌质寒热虚实两向演变、舌苔微生态禁刮原则与七大体质总纲","page_start":45,"page_end":58,"core_thesis":"日常家庭舌诊无需深究危重病人的‘舌神/舌萎’，只需抓牢稳定反映正气寒热的‘舌质’与灵敏反映正邪消长的‘舌苔’两大核心：从舌质向淡白或红绛青紫两极演变分辨血虚阳虚与实热虚热，从舌苔厚薄润燥及黄灰黑演变洞察胃气存亡与湿热外感轻重，切忌刮舌苔破坏消化微生态，并由此导入七种体质辨调体系。","chain_of_thought":["界定观察重心：舌失神、伸缩困难（舌萎）多见于中风病危者，普通人日常筛查聚焦‘舌质’（舌边未覆苔的肌肉脉络黏膜）与‘舌苔’两部分即可（p.46-47）。","剖析舌质两向演变病机：①朝淡白发展（甚则危重枯白舌）——排除血虚后，由外界寒邪有余或体内阳气不足（如夏季三亚畏风、冰啤冷饮吹空调、冬穿单薄短裙致宫寒、熬夜房劳伤肾阳）互为因果所致（p.47-50）；②朝红→绛→青紫发展——扣除夏季微红背景后，源于外感温病热邪或内热，内热须严辨肉食积滞之‘实热’（宜清热）与津血润滑油亏少之‘阴虚内热’（宜生地沙参麦冬滋阴，忌误服牛黄解毒丸；虚实夹杂则清热与滋阴双向动态配比）（p.48、p.50-52）。","解析舌面解剖微生态与厚薄正邪律：辨识舌根轮廓乳头、味觉蕈状乳头与丝状乳头构成的舌苔微环境；借肠道400多种共生菌、阑尾菌种‘诺亚方舟’及滥用抗生素灭益生菌致脾虚与真菌毒素诱发自闭症之理，阐明严禁刮舌苔；确立‘苔多反映邪气盛（湿重痰湿），苔少反映正气不足（舌白苔薄胃气虚、舌红无苔阴虚）’法则（p.52-55）。","总结苔色演变、灵敏度差异及全书体质框架：外感化热苔由白转黄、灰至焦黑（高热重症），水湿加重苔由薄变粘腻转黄（湿热）至满布唾液的滋润黑苔（湿极重）；指出舌质稳定而舌苔极灵敏（可一夜退苔或遇雾雨突发满口白苔），结合舌下静脉察全身血瘀，顺势引出后文气虚、血虚、瘀血、阴虚、阳虚、痰湿、气郁七大体质（p.56-58）。"],"key_takeaways":["舌质偏淡白主血虚、外寒有余或脾肾阳虚；舌质变红、绛、青紫主外感温病、积食实热、阴虚内热或血瘀（p.47-52）。","红舌必须分清实热与虚热：阴虚内热如发动机缺润滑油干转，治当滋阴润燥，切忌自作主张吃牛黄解毒丸清火（p.51-52）。","严禁刮舌苔：舌苔微环境含益生菌并参与消化第一阶段，刮苔伤消化；苔厚腻主湿邪痰湿盛，苔过薄或剥落主胃气虚或阴虚（p.53-55）。","同为黑苔须辨燥润：干枯焦黑苔属外感入里化热极重；满布唾液的滋润黑苔属水湿极重；舌质稳定看正气，舌苔灵敏看急变（p.56-57）。"]},{"id":"ch04","chapter_num":4,"title":"人活一口气","subtitle":"气虚体质的人如何保养","page_start":59,"page_end":88,"core_thesis":"“人活一口气”，养气就是养命。气虚本质上是肾气、脾气、肺气亏虚，其中脾土居于枢纽：肾命门之火生脾土以腐熟水谷，“脾主统水”防内湿停聚，“土生金”充养肺卫防外邪感冒。调理气虚必遵“先祛湿、祛湿后马上补脾”之铁律，配合生发胃气与养护晨起阳气，方能断绝水湿复来与向痰湿体质演变。","chain_of_thought":["气决定生机与姿态（pp.61-63）：气既是物质也是功能表现；气足者“站如松，坐如钟”（fig_p062），经常熬夜或缺乏锻炼致气虚者无法支撑身体成直角，坐姿塌陷歪歪扭扭（fig_p063），总需靠挂借力分解体重。","先后天化源与火生土（p.63）：父母遗传的先天之气（先天之精）与后天吸收的食物精华结合成肾精储于肾并生发肾气；肾为命门之火，五行“火生土”，命门之火熏蒸形成脾气，脾气足方能腐熟运化水谷精微。","脾主统水与脾血互累（p.64）：脾属土，土克水，“脾主统水”；脾气、肾气虚则水液代谢废物无法正常经尿液、汗液排出，停滞成湿邪阻碍气血运行。同时脾气不足无力化生营养致血虚；女性血虚伴水湿占领气血管道时，须一边祛湿一边养脾养血，否则单清湿邪管道空虚，水湿还会复回。","土生金与小儿积食感冒（p.65）：五行“土（脾胃）生金（肺）”，脾胃气弱或孩子猛吃大闸蟹、生日蛋糕等伤及脾胃产生积食，无力生发肺气，呼吸系统抵抗力下降，外邪乘虚而入而反复发烧感冒。","补脾以补肾及祛湿必补脾（p.65）：肾虚不明显时不宜单补肾，先补足脾气使水谷精微吸收增多，即可双向带动肾气与肺气充足；体内有湿者，祛湿之后必须马上补脾，否则三五天水湿复来，久积则演变为痰湿体质。","气虚全身征象与九类舌象辨识（pp.66-82）：面色白无光泽、爬三楼即喘心慌、少言懒语神疲、怕冷怕风易感冒、食后腹胀、大便不成形；舌见齿痕（排除牙齿畸形）、舌苔满布（注意与舌质淡白按舌边颗粒覆盖度鉴别）、湿掩热象（舌尖红兼映心火及女妇科/男前列腺下焦热）、蕈状乳头偏大红点（湿热上焦热）、圆胖齿痕伴唾液线（肝郁困脾生湿）、浮泛无根苔（暂发积食）、舌中分叉裂纹、舌体胖大、大病或饮大酒后无苔舌白。","分步调养与护阳戒忌（pp.82-88）：胃气伤无苔先喝生麦芽茶升发胃气（严禁误用降气的炒麦芽）；湿重用三仁汤泡脚、春夏湿热用薏苡仁赤小豆饮、秋冬用辛香调料与川椒泡脚温阳燥湿；祛湿后即服山药薏苡仁芡实小米粥，或以补中益气丸、陈实功/乾隆八珍糕常养脾气；严戒早起喝凉白开、饮茶过量与冰镇饮料。"],"key_takeaways":["看坐姿知气足不足：气足者“站如松，坐如钟”，气虚者站没站样、坐没坐样，总想找东西靠着（pp.61-63, 67）。","区分“舌苔满布”与“舌质淡白”关键看舌苔颗粒是否把舌边铺满；身体有问题多被湿气蒙蔽，调理往往以祛湿为第一步，且祛湿后必须马上补脾防复发（pp.65, 71-75）。","舌尖不仅对应心与小肠（心火），还对应下焦生殖系统：女性经期或下焦热妇科病、男性前列腺疾病均可见舌尖发红（p.75）。","无苔伤胃气用生麦芽30～60克泡茶升发胃气，严禁误用降气的炒麦芽；小儿舌尖至舌中见偏大红点属上焦热重，应清热（灯心竹叶汤）而非滋阴（pp.76-77, 82-83）。","日常护脾阳三戒与起居：不早起喝凉白开（改喝温水护阳气小火苗）、不过量喝茶困脾、严禁喝冰镇饮料伤脾胃，且卧室不宜过大或睡阴面房间（“先王不居大室”，pp.72-73, 85-86）。"]},{"id":"ch05","chapter_num":5,"title":"贫血的人老得快","subtitle":"血虚体质的人如何保养","page_start":89,"page_end":102,"core_thesis":"血液由脾胃吸收食物营养物质所化生，“会养血的人不会老”。现代人血虚（尤以女性与过食积食小儿多见）源于脾胃化源受损（“饮食自倍，脾胃乃伤”）与过度耗损（思虑伤心脾、生理失血未补、熬夜伤阴耗血）双重夹击。识别舌边浅淡半透明至全舌浅淡透明之微兆，善用汤液食疗（当归养血鸡汤）与王孟英玉灵膏养心血安心神，即可扭转血虚早衰。","chain_of_thought":["化源受损——“吃饱了撑的”致血虚（pp.90-91）：血液靠脾胃吸收水谷营养化生；现代人饮食过精、过量，《黄帝内经》谓“饮食自倍，脾胃乃伤”，脾胃超负荷受损则供血不足。许多幼儿园孩子脸色惨白、贫血，正是家长喂得太好太多、长期积食伤脾所致。","去路过耗——思虑、失血与熬夜（pp.91-93）：“思虑伤脾”致脾血供应不足，反复操心杂事又耗心血，犹如水池进水口堵塞而出水口过度排泄；女性一生失血机会多（“血对女性更重要，气对男性更重要”），未及时补养易面色晦暗苍白，而产后正是女人一生补血最佳黄金期（王孟英“龙眼肉产后尤益”）；加之现代人熬夜上网加班最伤阴耗血，使血虚愈重。","四大身体表现与精准鉴别（pp.93-95）：①蹲下1分钟站起即眼前发黑头晕（区别于蹲半小时站起的体位性低血压）；②神智功能全面退化（记忆力差、血不养心致失眠多梦、心力交瘁不愿思考）；③浑身如无筋般乏力、逛一条街如骨头架子要散、劳后头晕心悸、眼睑嘴唇指甲黏膜色浅，且属“神智疲劳”（区别于气虚的“身体疲劳”）；④四肢失养致“外边热身体就热，外边凉身体就凉”，冬冷空调冷而夏天又热得受不了（区别于阳虚者夏天舒服不觉特别热）。","两级血虚舌象察微（pp.96-97）：轻微血虚见舌边颜色很浅、舌质偏淡偏白略呈半透明感（fig_p096）；典型血虚见舌苔未铺满处舌质颜色非常浅甚至有透明感（fig_p097），反映舌黏膜毛细血管与舌体肌肉气血充盈俱差。","古法汤液与玉灵膏养血安神（pp.97-102）：沿袭《黄帝内经》“五菜为充、五果为助、五谷为养、五畜为益”及商代伊尹《汤液本草》传统，日常用当归养血鸡汤煲汤调养；重证血虚及失眠神疲用王孟英玉灵膏（龙眼肉300克、西洋参粉30克），古法蒸100次约40小时使龙眼肉由甜转苦，服之不上火而养心血安心神立竿见影，并严守儿童忌参、孕妇忌/慎龙眼肉之戒。"],"key_takeaways":["小儿贫血未必缺营养，多因吃得太好太多、长期积食伤及脾胃化源（p.91）。","蹲下仅1分钟站起即眼前发黑头晕是典型血虚信号，不可拿“蹲半小时体位性低血压”掩盖（p.94）。","血虚与气虚、阳虚鉴别：气虚重在身体体力易疲劳，血虚重在神智疲劳（健忘、失眠多梦、怕动脑）；阳虚夏天舒服不觉特别热，血虚则冬冷夏亦热得受不了（pp.94-95）。","女性产后是一生补血最佳时机，“龙眼肉产后尤益”（p.93）。","玉灵膏蒸4小时简化法部分人易上火，按古法蒸满40小时（逾10小时甜减变苦）则不上火且药效更强；切记孩子尽量别吃任何参类，孕妇慎/忌食龙眼肉防热性动胎（pp.99-102）。"]},{"id":"ch06","chapter_num":6,"title":"血瘀生百病","subtitle":"瘀血体质的人如何保养","page_start":103,"page_end":128,"core_thesis":"衰老就是身体瘀血不断增加的过程（p.104, p.120）。外伤、手术、生气肝郁、气虚（“气为血之帅，血为气之母”，p.108）、受寒（得热则行、得寒则凝，p.108）与内热煎熬粘稠（p.109）六大因素皆可致瘀；通过舌面青黑瘀点、舌下粗黑分叉静脉、非生理性舌尖偏斜（脑梗早期预警，p.115-116）及白苔罩紫黑舌识别瘀血，按病因与部位辨证化瘀，且现代人多脾虚夹痰湿，中药泡脚透皮入络效果常优于口服（p.121）；严记孕妇舌现瘀血属正常生理凝聚，绝对禁止活血化瘀（p.119）。","chain_of_thought":["溯源六大致瘀成因：外伤震荡致固定内脏的筋膜突然拉扯或小儿跌倒未察觉留瘀（p.105）；剖腹产等手术创面产后两三年瘀血仍存（p.105）；生气致肝气不舒在体内结成顽固痛点，延伸引入斯坦福工程师盖理·克雷格（Garry Craig）按揉穴位配合心理疏导术语的EFT情绪释放技术（已被世卫组织收录用于治疗抑郁症，p.106-107）；脾肾肺气虚推动无力（“气为血之帅，血为气之母”，p.108）；夏天吹冷空调或穿着暴露受寒凝血（p.108-109）；内热蒸发血液水分致粘稠成瘀（p.109）。","对照全身五大躯体表现与腹诊筛查：血不养心致记忆力差“善忘”（p.109）；唇黑面斑及由无数小黑点、暗斑构成的点状黑眼圈（异于失眠或肾虚的整体乌青暗黑，p.110）；喉咙干但“但欲漱，不欲饮”及体表失养致“肌肤甲错”（腿部皮肤干裂如鱼鳞，须从体内滋养而非外喷补水，p.110-111）；鼻翼两侧“钞票纹”与腿部浮起红青毛细血管（p.111）；固定部位“昼轻夜重”疼痛及平躺按肚子的中医腹诊痛点（仅作健康监测筛查，确诊须找当地中医，p.111）。","分层辨识七类瘀血舌象与高危/生理红线：舌尖明显瘀点示瘀血将成、舌面青黑点（蕈状乳头毛细血管瘀堵）示已有瘀血（p.112），舌尖与舌两侧大量黑青瘀斑瘀点及舌下静脉直径超2毫米、又黑又粗向四周分叉示瘀血严重（p.112-114）；动态排除天生舌偏后，舌尖偏斜提示同侧头部血管堵塞，可比腔隙性脑梗塞等症状提前三年以上出现，老人舌向改变须立即就医（p.114-116）；识别脾虚满苔隐现瘀斑（抬舌查舌下静脉，p.117）、女性舌瘀伴上唇汗毛重预警子宫肌瘤/卵巢囊肿（p.117-118）、白苔笼罩紫黑舌的“湿气罩瘀”（须一边祛湿一边清热化瘀，p.118-119），并严守“孕妇舌现瘀血属正常现象，严禁活血化瘀”铁律（p.119）。","因人因位施治且泡脚优先：按成因分施湿热肾病凉血化瘀、受寒风湿温阳化瘀、血虚桃红四物汤养血化瘀、气郁先疏肝再化瘀（甲状腺/乳腺结节等，p.120, p.128），按部位分用王清任通窍活血汤（头面）、血府逐瘀汤（胸中）、少腹逐瘀汤（少腹）（p.120-121）；针对现代人脾虚痰湿阻碍口服吸收，优先用药汁泡脚透皮走经络疏通瘀阻（p.121-122），并给出腰腿寒湿泡脚、心脏瘀血三七配西洋参、骨折鸡腿骨汤、痔疮地龙/椿根皮（便血必先排查直肠癌）及女性益母丸/八珍益母丸周期调治方案（p.122-128）。"],"key_takeaways":["“气为血之帅，血为气之母”（p.108）：气虚推动无力、肝郁生气（可借EFT情绪释放技术按穴疏导，p.107）、空调受寒、内热煎熬、外伤与剖腹产等手术均会留瘀，衰老过程即体内瘀血增加的过程（p.105-109, p.120）。","白苔笼罩紫黑舌属“湿气掩盖瘀血”，单纯祛湿效差，须一边祛湿一边清热化瘀（p.118）；现代人多脾胃弱夹痰湿难吸收汤药，泡脚化瘀经皮肤经络直达病所，效果常比喝药更好（p.121）。","排除天生舌偏后，舌尖偏斜是同侧脑血管堵塞的早期预警（可提前三年以上，老人舌向改变须立即赴医院检查，p.115-116）；女性舌瘀伴唇上汗毛重须查子宫肌瘤与卵巢囊肿（p.117-118）。","安全红线：孕妇舌象现瘀血属胎儿气血凝聚正常现象，严禁看舌妄投活血化瘀药（p.119）；便血必须先去医院检查排除直肠癌，确认痔疮后方可用方（p.126）；分清补气血的“八珍益母丸”与活血的“益母丸”，经量大忌服益母丸，气郁致瘀须先疏肝（p.127-128）。"]},{"id":"ch07","chapter_num":7,"title":"不焦虑，不上火","subtitle":"阴虚体质的人如何保养","page_start":129,"page_end":144,"core_thesis":"阴是体内主濡润、主安静的血液与津液等物质基础，“阴虚则生内热”犹如发动机缺润滑油干转生热（p.131）。半夜12点后熬夜、嗜食麻辣辛辣、小儿过食肉类及焦虑郁闷（贪嗔痴致肝郁化火伤阴、木克脾土）是致阴虚主因；多种体质交缠的复合体质调理核心中轴在脾胃（后天之本），根本源头在稳定情绪（p.132-133）。临床结合舌红苔薄/无苔、地图舌、老人深裂纹舌与五心烦热、盗汗、脉快及小儿脾阴不足诸症，分儿童、成人与肾阴虚精准濡养，严禁把虚热误当实热吃牛黄解毒丸（p.52）或在湿热、阳虚时误服六味地黄丸（p.144）。","chain_of_thought":["阐明“阴虚生内热”机理与生活诱因：津液血液如同汽车发动机润滑油，亏耗则干转生出大量虚热（p.131）；常吃麻辣烫、酸辣粉等辛辣食物伤阴，天天半夜12点以后睡觉耗尽津液，是现代人阴虚的直接推手（p.131）。","建立复合体质“核心调脾胃、根源调情绪”总纲：贪嗔痴与攀比郁闷致肝气不舒，既化肝火耗伤肝阴津血，又以木克土削弱脾胃——脾胃一伤则水湿重、化血少致血虚、气虚致血瘀、湿聚成痰湿，层层交缠（p.131-133）；古今50万首方剂最常用茯苓正因中轴在健脾祛湿，但若情绪失常着急上火，补脾药亦迅速化火，故调理关键在脾胃、根源在情绪稳定（p.132-133）。","辨析成人阴虚症状与钱乙辨小儿三睡汗：成人见眼干鼻冒火喜冷饮、手足心及心中“五心烦热”脾气大（p.133-134）、失眠盗汗（引宋代儿科大家钱乙辨同户三子入睡出汗典故：半头汗为诸阳经汇集体内有热当清热，胸以上汗为脾胃积食当补脾消食，唯遍体出汗属阴虚当滋阴，p.134）、便干尿黄腰膝酸软（p.134）及静息脉搏超90次/分或较自身往常动态加快（p.135）。","识别明代缪希雍“脾阴不足”小儿过食肉类证候群：半数以上孩子因家庭与幼儿园伙食肉食过多（鸡鸭鱼虾猪肉营养过剩）吃出脾阴不足，呈现嘴唇鲜红伴下眼袋肿红、胃强脾弱（胃口极好但一吃就肚胀，伴便干或不成形、盗汗翻滚难眠）、内热上返致好动且风吹即感冒、一感冒嗓子就肿，以及心烦耐性差坐不住等特征（p.135-137）。","审察阴虚舌象动态转化与分人群用药禁慎：典型见无外感而舌红苔薄或无苔萎缩（津亏破坏舌面微生物环境，p.137-138），兼湿者舌红而苔不薄（水湿掩盖阴虚，p.138），老人多红舌深裂纹且吃辣舌痛（p.139），地图舌多属阴虚（p.139），舌质由红转淡白示阴虚久耗转为血虚（反之由淡白转红示血虚转阴虚，p.140）；分设小儿滋阴七味方配少肉多菜半年以上（p.136, p.140-141）、成人滋阴猪龙骨汤（p.141）及钱乙六味地黄丸三补三泻治肾阴虚，严守湿热禁服、阳虚禁直补阴、脾弱配砂仁冲服三大准则（p.141-144）。"],"key_takeaways":["复合体质调理法则：多体质重叠出现时须一环环解开，调理身体的核心中轴是养好脾胃，但调整的根本源头是平复情绪、疏解肝气（p.132-133）。","宋代钱乙辨小儿睡汗三法：半头汗属内热当清热，胸以上汗属脾胃积食当补脾消食，入睡后遍体出汗方属阴虚当滋阴（p.134）；成人脉搏>90次/分或较自身基线明显加快需警惕阴虚（p.135）。","小儿嘴唇很红伴下眼袋肿红、胃强脾弱吃胀、好动易感冒且“一感冒嗓子就肿”、耐性差，多为吃肉过多致脾阴不足，除短期服儿童滋阴方外，必须少吃肉、多吃青菜坚持半年以上（p.135-137, p.140-141）。","用药禁慎：阴虚舌红属虚热，勿误服牛黄解毒丸清实热（p.52）；六味地黄丸三补三泻治肾阴虚（熬夜、用脑、房劳、虚火粉刺可配野菊花枇杷叶各10克），湿热苔厚黄腻胃胀便溏禁服、阳虚舌淡脉缓下肢冷禁直补阴（应服金匮肾气丸）、脾胃弱者用1个砂仁捣碎泡开水冲服防熟地滞腻（p.141-144）。"]},{"id":"ch08","chapter_num":8,"title":"做人就要阳气十足","subtitle":"阳虚体质的人如何保养","page_start":145,"page_end":153,"core_thesis":"阳虚即人体内主温煦、主生发、主生殖的功能不足，以脾肾阳气最关键（肾阳足则脾阳足）；受寒、作息颠倒、久病或滥用抗生素等寒凉药均会耗伤脾肾之阳，调理当分清肾阳虚与脾阳虚而温补阳气。","chain_of_thought":["肾兼具肾阴与肾阳，肾阳如人体内的太阳，主温煦、生发与生殖；肾阳虚者面色发白、畏寒怕冷、精力差而总想睡觉（“但欲寐”）（p.146, 149）。","熬夜、房劳过度、患大病消耗及滥用抗生素等寒凉药会耗损肾精肾阳；贪饮冰啤酒伤脾阳并累及肾阳，涉凉溪水、冬季穿单薄丝袜或薄皮鞋则从足下肝脾肾三经受寒伤及肾阳，血虚等他脏久虚亦会转为阳虚（p.147-148）。","阳虚与血虚虽均见舌淡怕冷，但可从夏热反应（阳虚夏天仍怕冷怕风 vs 血虚夏天手变暖）、功能层面（整体生命机能下降 vs 神志功能不强）及症状侧重（遇低温不适与生发衰退 vs 神智及辨色力衰退）三点鉴别（p.147）。","阳虚舌质很淡不红、白苔而质地“苍老”；轻度阳虚湿重见舌面唾液偏多（水滑），重度阳虚火力衰微不能蒸腾津液（如蒸饭火微锅盖无水汽）反致口干口渴（p.150-151）。","肾阳不足致夜尿频繁（老人一晚五六次）、水肿或涉冷水脚跟痛者用金匮肾气丸（受凉配合热水泡脚）；脾阳不足致沾凉即胃痛、遇冷腹泻或上吐下泻者用附子理中丸/理中丸（p.151-153）。"],"key_takeaways":["“阳虚则外寒”，怕风怕冷尤以腹部和下肢（肝脾肾三经所过）最为明显，常伴面色苍白或生黑斑、尿频清长、遇冷腹痛晨泻（p.148-152）。","阳虚舌象淡白苍老（异于血虚之淡嫩），重度阳虚口干属津液不升而非实热，温阳后津生渴止（p.150-151）。","肾阳虚首选张仲景《金匮要略》金匮肾气丸（熟地补肾精生阳，附子、肉桂生发阳气），脾阳虚首选附子理中丸/理中丸（p.151-153）。"]},{"id":"ch09","chapter_num":9,"title":"终生远离“三高”","subtitle":"痰湿体质的人如何保养","page_start":154,"page_end":162,"core_thesis":"痰是体内湿气蒸发凝炼而成的黏稠“结晶”，源于脾虚正气不足、肥甘应酬过量及情志失控（肝木克脾土）；舌现黏腻水液或白霜厚腻苔是“三高”高危预警，舌红苔厚腻者属营养过剩严禁进补，当用去生姜温胆汤泡脚并以清淡饮食和运动“以清为补”。","chain_of_thought":["脾一虚则肺气与五脏六腑正气皆虚（固摄无力可致小儿或老人脱肛），水湿留滞体内凝炼成有形与无形之痰；吃得过多过好、频繁应酬、半夜吃夜宵及液体摄入过多使湿聚成痰（p.155-156）。","70%现代人湿重归根到底是神志与情志问题：压力郁闷致肝气不舒（木克脾土），美食夜宵面前管不住嘴亦属不够冷静的神志失调（p.156）。","舌面水液黏腻伴舌中沟明显（p.157）或舌苔厚腻白如霜（p.158），体检基本已有高血压、高血脂、高血糖（“三高”）；舌苔厚腻渐黄且舌质发红（p.159）属营养过剩、热湿结成痰瘀，误当肾虚进补必越补越热。","现代人脾胃受损严重、痰湿堵在中焦导致口服中药难吸收，用罗氏去生姜“温胆汤”（因现代人痰多化热去生姜，热重竹茹配至9克）泡脚反而比吃药效果更好（p.160-162）。","药方只是推一把的辅助手段，痰湿者最适合吃萝卜白菜、粗茶淡饭（坚持素食或适当断食）并坚持合理运动，此即“以清为补”（p.162）。"],"key_takeaways":["舌面黏腻水液或白霜样厚腻苔是“三高”强预警信号，应及时体检筛查血压、血脂、血糖（p.157-158）。","痰湿舌苔厚腻舌质红者虽常感乏力犯困，实为“营养过剩”，严禁盲目进补或补肾（p.159, 162）。","温胆汤泡脚（茯苓30g、陈皮6g、法半夏6g、竹茹6g[热重9g]、枳实6g、炙甘草6g）须去掉温性生姜以防助热；根本康复靠粗茶淡饭与规律运动（p.160-162）。"]},{"id":"ch10","chapter_num":10,"title":"安神才能强大","subtitle":"气郁（肝气不舒）体质的人如何保养","page_start":163,"page_end":190,"core_thesis":"气郁（肝气不舒）是现代人最普遍的致病根源（约80%疾病、90%女性疾病与情绪相关），以尖舌为典型器质性标志；长期隐忍“郁怒”易诱发肿瘤与结节，横逆则伤心、克脾、刑肺，调理必须以调神安神为核心并按脏腑传变分证施治。","chain_of_thought":["复合体质以脾胃失调为中轴，而脾胃失调根源在情绪失常；《黄帝内经》重调神轻药方，祛湿、化瘀、滋阴、温阳皆为扫清障碍，必须同步疏肝调神求得心安（p.165-167）。","七情失常分暴怒与郁怒：追求完美、隐忍委屈的“单位老好人”把火憋在心里成郁怒，内伤不可逆且患肿瘤比例最高；家长的严苛焦虑气场更会传染给孩子（最小可见2岁幼儿肝郁、小学生现尖舌），且尖舌属数年塑造的器质性慢变（p.168-171）。","肝气不舒具少阳证8项典型指标（口苦咽干、眩晕、纳差、忽冷忽热、恶心反酸、胸闷心悸、肋内胀痛、失眠多梦）；木生火致女性多见胸闷心悸“心脏病假象”，木克土致胃痛胃溃疡与胃酸返流性慢性咽炎，“木火刑金”反侮肺金则引发严重肺病及凌晨3～5点肺经当令早醒（p.171-175）。","气郁典型舌象为伸舌尖尖、边尖发红（p.176）；若气滞水停则初伸尖、再伸变胖圆（p.177）或尖舌覆白苔（p.178），近期焦虑心火则尖舌前部无苔而舌尖红（p.179），新生儿尖舌亦提示气郁倾向（p.180）。","分证保养：肝郁胃痛胃溃疡遵循“见肝之病，知肝传脾，当先实脾”用舒肝和胃丸配黄芪建中汤（罗氏用生黄芪6克防上火）；顽固失眠用柴胡加龙骨牡蛎汤加味15味泡脚；凌晨3～5点早醒敲打胳膊内侧肺经痛点；情绪性高血压用20味平肝潜阳泡脚方；甲状腺结节用10味疏肝散结泡脚方，乳腺增生服加味逍遥丸/丹栀逍遥丸；暂时心火喝灯心竹叶汤（p.180-190）。"],"key_takeaways":["苛求完美、隐忍不发的“老好人”郁怒最易诱发肿瘤，家长焦虑会直接塑造儿童尖舌；尖舌形成与消退均慢，症状缓解而尖舌未变时不可停调心神（p.43, 168-171）。","警惕肝郁三大跨系统传变：扰心致胸闷心悸假象、克脾致反流性食管炎/胃溃疡与慢性咽炎、木火刑金致凌晨3～5点早醒与重症肺病（p.172-175）。","柴胡加龙骨牡蛎汤加味治失眠泡脚方（15味，1周1疗程共3周）原书明文标注孕妇忌用（p.182, 202）；情绪性高血压泡脚方（20味）及甲状腺结节疏肝泡脚方（10味）均含丹皮、牛膝、川芎等行气活血药，依 p.119 妊娠禁化瘀原则孕妇亦须避忌，且口服汤剂前均须请当地中医师辨证加减（p.182-189）。"]}],"constitutions":[{"id":"qi_deficiency","name":"气虚体质","alias":"脾肾肺气不足 / 脾虚湿困体质","chapter_id":"ch04","page_start":59,"page_end":88,"root_causes":["先天肾精禀赋不足，或熬夜消耗正气，致肾命门之火不足以熏蒸生发脾土（pp.61, 63, 67）。","贪吃寒凉之物、冰镇饮料、反季节水果或受外寒侵袭（含久处空调房），直接损伤脾阳、压制阳气（pp.69, 73, 86）。","久坐办公室不运动、怕晒太阳导致排汗减少，水湿困阻体内；或睡阴面房间、卧室过大敞开消耗阳气（《吕氏春秋》“先王不居大室”，pp.69, 72-73）。","平时饮食不当、天天喝大酒，或患一场大病之后损伤脾胃之气（pp.81-82）。","早起喝凉白开扼杀初生阳气，或饮茶成瘾过量困住脾胃加重水湿（pp.85-86）。","肝气不舒导致气瘀困脾，叠加脾气不足，使水液代谢失常而内停痰湿（pp.78-79）。"],"body_symptoms":["脸色白白的、没有光泽，体力差，动辄自汗、气喘，爬三层楼就气喘且心跳厉害（p.66）。","少言懒语、不爱吭声，多说两句都觉得累，处事倾向多一事不如少一事（pp.66-67）。","容易神疲乏力、总觉疲倦，上街走一圈别人不累自己先累；站没站样、坐没坐样，坐姿歪歪扭扭塌陷（fig_p063），站或坐总想找东西靠着分解体重（pp.61-63, 67）。","怕冷、怕被风吹，一受凉就猛打喷嚏，极易反复感冒（脾气不足致肺卫抵抗力下降，p.67）。","吃东西容易腹胀，因脾虚无力运化食物而滞留体内（p.67）。","大便不成形，因气虚无力固摄大便而容易滑脱（p.68）。","若兼肝郁困脾致中焦脾胃气堵、痰湿内盛，则整天浑身没劲、爱发困、出黏汗、一吃饭就一身汗，常上半身出汗而下半身无汗（p.79）。"],"child_symptoms":["因脾胃功能差、猛吃大闸蟹或生日蛋糕等伤脾积食，无力“土生金”充养肺气，导致特别爱感冒、发烧，甚至刚去趟幼儿园回来又打喷嚏感冒（pp.65, 67）。","正气不足的孩子短时间吃多、暂有积食时，舌体胖大有齿痕，表面出现浮泛无根、似能刮掉的腻苔（pp.79-80）。","若孩子舌尖到舌中部出现偏大的蕈状乳头红点，提示上焦热很严重，须以清热为主而非滋阴（pp.76-77）。"],"core_tongue_features":["舌两侧齿痕（牙齿印）明显：水湿停聚致舌体肿胀，昼夜受牙齿挤压而成（pp.68-69，fig_p068）。","舌苔满布、水湿铺满舌面：舌苔过度生长连舌边颗粒也铺满，不露舌质；苔愈厚湿愈重，厚极则凝湿成痰而白厚腻（pp.65-66, 70-74，fig_p066、fig_p071）。","舌体胖大（或部分瘦舌仍伴齿痕），属正气不足、脾气虚的典型表现（p.81，fig_p081）。","舌中间裂纹特别明显甚至分叉众多：脾胃气不足，无力生发舌苔弥补舌中沟（p.80，fig_p080）。","无舌苔或舌苔极薄、全舌白白的：大病后伤脾胃或长期饮大酒伤损胃气（pp.81-82）。","兼夹征象：湿苔掩盖舌尖或肝胆区微红热象（pp.74-75，fig_p074）；舌有齿痕、苔满微黄伴舌尖至舌中蕈状乳头偏大红点属脾虚湿热（p.76，fig_p076）；圆胖微齿痕、薄苔伴两条唾液线属肝郁气瘀困脾湿重（p.78，fig_p078）；胖大齿痕配浮泛不均腻苔属暂发积食湿轻（pp.79-80）。"],"differentiation_notes":["坐姿望诊对比（pp.61-63）：气足之人脊背挺直“站如松，坐如钟”（见 p.62 插图 fig_p062“气足的人‘坐如松’”）；气虚之人（含常熬夜的年轻人）体内之气无力支撑坐直，一坐即塌陷、歪歪扭扭靠挂借力（见 p.63 插图 fig_p063“气虚的人坐姿歪歪扭扭”）。","齿痕舌排除生理假象（p.69）：须先排除牙齿畸形（几颗牙齿生长异常天天压迫舌边）造成的物理压痕，非牙齿畸形者方属脾虚水湿。","舌苔满布（fig_p071）vs 舌质淡白（fig_p072）（pp.70-72）：舌质过白与白苔同色时极易误作苔满布；区分关键看舌苔颗粒是否把舌边都铺上——铺满舌边为舌苔满布（湿重），未完全覆盖舌边而底色淡白者为舌质淡白。","湿气蒙蔽真象与舌尖红双义（pp.74-75）：满布白苔常掩盖内热、气郁或瘀血，须先祛湿方显真实舌色；舌尖红除提示心火焦虑外，亦对应下焦生殖系统（女性经期或下焦热妇科病、男性前列腺疾病）。","浮泛无根苔 vs 真性重度痰湿（pp.79-80）：苔腻不均但浮起如能刮掉者属无根虚浮苔，多因刚喝牛奶或暂时积食，湿气不重，清淡粗粮萝卜汤一日即消；真性厚腻有根苔则除湿难度大。","其他望诊防误判提醒（pp.79, 82）：看中医前勿化妆涂口红以免掩盖唇周瘀像（p.79）；舌头伸不长未必是心气不足，可能是天生舌系带过短（且无法翘舌观察舌下静脉，p.82）。"],"lifestyle_taboos":["早起切勿喝凉白开：早晨体内阳气如小火苗初生发，一杯凉水会严重扼杀阳气生发，早起喝水必须喝温水（pp.85-86）。","切勿喝茶过多：饮茶过量成瘾容易把脾胃困住，加重体内湿气，喝茶务必适量（p.86）。","严禁喝冰镇饮料：冰饮最伤脾胃，会导致消化系统功能失调或痉挛性收缩，诱发胃炎或肠炎，并造成严重水湿（p.86）。","忌贪吃寒凉与反季节水果、忌天天喝大酒伤胃气，以及忌小儿暴食大闸蟹、生日蛋糕等伤脾积食（pp.65, 69, 73, 82）。","忌久坐空调房不运动、完全拒晒太阳（但锻炼不可突然超负荷暴走以免伤关节），并避免长期睡阴面房间或过大敞开式卧室耗损阳气（pp.69-70, 72-73）。"],"conditioning_principles":["先祛湿、祛湿后马上补脾：湿重蒙蔽时以祛湿为第一步（兼热者稍佐清热），湿退立即补脾固土，否则三五天水湿必复回，久则成痰湿体质（pp.65, 74-75, 83）。","补脾以带动肺肾，兼顾养血：肾虚不重时先补脾气，借水谷精微双向充养肾气与肺气；若兼女性血虚，须一边祛湿一边养脾养血防气血管道空虚（pp.64-65）。","无苔伤胃先升发胃气：大病后或饮大酒致无苔/极薄苔者，少猛喝水，先用生麦芽茶升发胃气至舌苔复生（pp.81-83）。","因时制宜选祛湿法，外治优先：一般湿重首选三仁汤泡脚；春夏湿热用薏苡仁赤小豆饮，秋冬寒凉改用白蔻仁/砂仁/花椒做菜与川椒水泡脚温阳燥湿；湿清气畅后再配合适度日晒与运动（pp.83-85）。"],"primary_remedy_ids":["rem_shengmaiya_tea","rem_sanren_footbath","rem_yiyiren_chixiaodou","rem_autumn_winter_spice_footbath","rem_shanyao_yiyiren_qianshi","rem_buzhong_bazhen","rem_dengxin_zhuye"]},{"id":"blood_deficiency","name":"血虚体质","alias":"心脾血亏 / 营血不足体质","chapter_id":"ch05","page_start":89,"page_end":102,"root_causes":["饮食过精、过量损伤脾胃（“吃饱了撑的”）：《黄帝内经》云“饮食自倍，脾胃乃伤”，超出脾胃运化能力导致脾胃受损，无法吸收食物营养物质化生血液；小儿喂食太好太多常致积食性贫血（pp.90-91；另见 p.64 脾虚致血源不足）。","过度思虑耗伤心脾之血：“思虑伤脾”使脾血供应不足，终日操心过去或未发生的杂事、彻夜难眠又耗伤心血，形成进水口堵塞而出水口过度排泄（pp.91-92）。","女性生理失血机会多且失于补养：女性一生经、孕、产、乳失血机会多，血对女性尤为关键，失血后未及时调补则致血虚（pp.92-93）。","长期熬夜伤阴耗血：熬夜上网、看球赛、加班写计划书违背“日出而作，日落而息”，持续耗损体内阴血物质基础（p.93）。"],"body_symptoms":["短时间蹲下（蹲1分钟）再站起来时，眼前瞬间发黑、头晕，片刻后方能恢复（pp.93-94）。","所有与神智相关的功能退化：①记忆力不好；②血不养心导致失眠、多梦；③心力交瘁，总是不愿意思考事情，一想就觉得很累（p.94）。","容易疲劳、浑身没劲：上班走路觉得身体里像没有筋一样，女性逛一条街就感觉骨头架子像要散了，且疲劳过后易头晕、心悸（pp.94-95）。","黏膜色浅与面色无华：眼睑、嘴唇、指甲等黏膜相关部位颜色很浅，面色发黄、苍白或晦暗苍白（pp.92, 95）。","体温随外界环境剧烈波动（“外边热身体就热，外边凉身体就凉”）：血液不能供养四肢，天热时手脚正常、一到夏天甚至热得受不了；一旦降温、入冬或进空调房手脚立刻冰凉，极怕风怕冷，比常人多穿衣服鞋袜（pp.95, 100）。"],"child_symptoms":["营养过剩积食型小儿贫血：平时吃得太好、太多导致常常积食，脾胃受伤后血液化生不足，孩子脸色不是红扑扑而是惨白惨白的（p.91）。","儿童调补特别禁忌：孩子可以吃龙眼肉，但尽量别给孩子吃西洋参等任何参类中药（p.102）。"],"core_tongue_features":["轻微血虚舌象：舌边颜色很浅（正常舌边应红润），全舌颜色偏淡甚至略偏白，舌质带有半透明感（p.96，fig_p096）。","典型血虚舌象：舌苔未把整个舌头铺满，可见舌质颜色非常浅，甚至有一点透明的感觉，提示舌黏膜毛细血管与舌体内部肌肉的气血充盈状态均差（pp.96-97，fig_p097；舌体外观偏淡嫩，见附录 pp.198-199）。"],"differentiation_notes":["蹲下1分钟头晕 vs 半小时体位性低血压（p.94）：蹲地半小时突然站起头晕多数人都会出现，属体位性低血压；但仅蹲1分钟站起即眼前瞬间发黑头晕（对比小学做蛙跳不会眼前一黑一亮），则是明确的血虚信号。","神智疲劳（血虚）vs 身体疲劳（气虚）（pp.94-95）：两者均神疲乏力，但气虚主要是身体体力容易疲劳（动辄气喘自汗），而血虚突出表现为“神智疲劳”，即记忆减退、失眠多梦、心力交瘁不愿思考、无力做事。","冬冷夏亦怕热（血虚）vs 喜夏不恶热（阳虚）（p.95，附录 pp.198-199）：两者冬天与吹空调时均手脚冰凉、怕风怕冷，但阳虚者到了夏天炎热时觉得舒服、不觉特别热，且舌淡苔白偏“苍老”；血虚者“外边热身体就热，外边凉身体就凉”，一到夏天可能热得受不了，且舌质淡白偏“淡嫩”半透明。","产后补血黄金期（p.93）：女人一生中最适合补血的时机就是生完孩子以后，王孟英载“龙眼肉产后尤益”（如福建产后炖龙眼肉、义乌黄酒或红曲酒炖红糖配龙眼肉），须与孕期忌食龙眼肉严格区分（p.102）。","血虚舌质淡白 vs 湿重舌苔满布（pp.71-72, 96-97）：确认舌边未被舌苔颗粒完全覆盖而底色浅淡透明者方为血虚；若女性血虚兼水湿困阻气血管道，须祛湿与养脾养血同步进行（p.64）。"],"lifestyle_taboos":["忌暴饮暴食与饮食过精过量（“饮食自倍，脾胃乃伤”），尤其忌给孩子过度喂养造成积食伤脾贫血（pp.90-91）。","忌过度思虑、反复操心过去或未发生的琐事耗伤心脾之血（pp.91-92）。","忌熬夜上网、看球赛、加班熬夜伤阴耗血（p.93）。","女性经期、产后等失血后忌忽视及时补养（pp.92-93）。","用药食疗红线：尽量别给孩子吃西洋参等任何参类中药；孕妇尽量不要食用龙眼肉（含玉灵膏），以防热性动胎（p.102）。"],"conditioning_principles":["节饮食护脾胃以裕血源：减轻脾胃运化负担，杜绝过食积食，使脾胃正常吸收水谷营养化生血液（pp.90-91）。","安心神、戒熬夜以防耗血：减少无谓思虑操心，恢复规律睡眠，切断心脾之血过度消耗（pp.91-93, 101）。","抓住产后黄金期及时养血：产后气血亏虚最宜炖服龙眼肉或黄酒/红曲酒炖红糖加龙眼肉调补（p.93）。","轻证汤液常养，重证玉灵膏心脾同调：日常用当归养血鸡汤煲汤滋养；严重血虚伴失眠、健忘、神疲乏力者用王孟英玉灵膏（优选古法蒸40小时至味苦不上火）养心血、安心神（pp.97-102）。"],"primary_remedy_ids":["rem_danggui_chicken_soup","rem_yulinggao"]},{"id":"blood_stasis","name":"瘀血体质","alias":"血瘀生百病 / 经络血脉瘀阻","chapter_id":"ch06","page_start":103,"page_end":128,"root_causes":["外伤致瘀：开车小擦碰猛震导致固定内脏的筋膜突然遭到拉扯，或小儿跌倒磕碰家长未察觉，均可在体内留下长期瘀血（p.105）","手术致瘀：分娩尤其剖腹产等手术造成伤口创面，很多人未及时化瘀，产后两三年体内瘀血依然存在（p.105）","生气（气郁）致瘀：压力大、肝气不舒或生气时吃饭，每次生气都会在身体留下顽固郁结与隐匿痛点（p.105-106）","气虚致瘀：“气为血之帅，血为气之母”，吃饭不规律伤脾胃且缺乏锻炼导致肾气、脾气、肺气不足，推动血液循环力量减弱，血流在弯曲受阻处滞留成瘀（p.108）","受寒致瘀：血液“得热则行，得寒则凝”，夏季毛孔开泄时吹强冷空调或女性贪图美丽穿着暴露受凉，气血遇寒凝滞于细微血管成瘀（p.108-109）","“热”邪致瘀：体内热邪把血液中的液体蒸发，使血液变得粘稠而形成瘀血（p.109）"],"body_symptoms":["记忆力差（善忘）：血液循环障碍导致血不养心，无法提供足够血液维持思虑机能运转（p.109）","唇黑面斑与点状黑眼圈：嘴唇发黑、面部生斑，眼睛四周黑眼圈由无数小黑点、暗斑构成一圈（区别于没睡好或肾虚的整体乌青暗黑）（p.110）","喉咙干而“但欲漱，不欲饮”：经常感觉喉咙干却不口渴，总想用水漱口润喉但不想咽下去（p.110）","肌肤甲错：毛细血管供养体表不足致皮肤干裂粗糙如铠甲、腿部皮肤不光洁如鱼鳞，外喷补水无效，须从体内滋养（p.110-111）","皮肤血丝与鼻翼“钞票纹”：鼻翼两侧毛细血管浮现如钞票细纹（王琦称“钞票纹”），腿部浮起红色或青色毛细血管（p.111）","固定部位“昼轻夜重”疼痛与腹诊痛点：身体固定位置常痛，白天轻或不疼、夜间疼痛加重；平躺按压腹部有明显痛点（中医腹诊）（p.111）","女性经行不畅量少、气血虚兼瘀早发闭经，或伴嘴唇汗毛重、子宫肌瘤、卵巢囊肿、乳腺及甲状腺结节（p.117-118, p.127-128）"],"child_symptoms":["小朋友日常跌倒摔伤未被家长知晓，体内潜藏外伤瘀血，可引发部分顽固的小儿疑难杂症（p.105）"],"core_tongue_features":["舌尖出现明显瘀点（提示体内瘀血即将形成），舌面见黑点或青点（蕈状乳头内毛细血管堵塞，提示体内已有瘀血，p.112）","舌尖和舌头两侧出现大量黑色或青色瘀斑、瘀点（说明瘀血很严重，p.112-113）","张嘴舔上嘴唇见舌下两条静脉直径超过2毫米、又黑又粗并向四周分叉（正常为淡蓝色且直径不超过2毫米，说明瘀血很严重，p.113-114）","排除天生舌偏后，舌尖向一侧偏斜（往哪侧偏说明同侧头部血液/经络有堵塞，可比腔隙性脑梗塞等症状提前三年以上出现，p.114-116）","舌质颜色发青或偏紫；脾虚水湿重者舌苔较满、隐约透出不明显瘀斑，需抬舌观察舌下静脉确认（p.116-117）","女性舌上红点慢慢变黑点等瘀血指征且嘴唇上汗毛很重（提示内分泌异常及子宫肌瘤、卵巢囊肿可能，p.117-118）","舌头发紫、发黑，外面被一层白苔笼罩（说明湿气把瘀血罩在里面了，p.118-119）"],"differentiation_notes":["【孕妇绝对禁区】千万不要给孕妇看舌象化瘀！胎儿形成的过程就是气血凝聚的过程，孕妇舌象显示有瘀血属正常生理现象，严禁给孕妇用活血化瘀药，否则极易出事（p.119）。","【黑眼圈鉴别】没睡好、肾虚导致的黑眼圈整体是暗的、乌青的；瘀血体质的黑眼圈像由无数小黑点、暗斑构成（p.110）。","【生理性舌偏与脑梗预警】必须动态观舌排除天生舌尖偏斜；若以前正常、近期舌向改变（尤其老人脑血管极敏感），须立即带去医院检查脑血管堵塞（p.114-116）。","【多指征叠加危重度】舌尖偏、瘀斑瘀点、舌下静脉怒张一般不会一起出现，出现任一种即证明有瘀血，若几种合在一起出现说明病情非常严重（p.116）。","【便血必查直肠癌与筛查边界】舌诊只给怀疑筛查的权利，勿自行确诊乱投药（p.111, p.191）；遇便血症状必须先去医院检查排除直肠癌，确认是单纯痔疮后方可按痔疮调理（p.126）。","【中成药防混】同仁堂“益母丸”专于活血化瘀（经量大忌用），“八珍益母丸”（四物汤加四君子汤）重在气血双补，切勿买混吃错（p.127-128）。"],"lifestyle_taboos":["忌夏季皮肤毛孔开泄时贪吹强冷空调，或女性穿着过于暴露受寒凝滞气血（p.108-109）","忌频繁生气郁闷或生气时进食（每次生的气都会在身体造成顽固郁结与瘀血，p.106）","忌三餐不规律伤脾胃及久坐不运动致气虚血滞（p.108）","忌在车祸小擦碰震荡、跌打骨折或剖腹产等手术后忽视化瘀调护（p.105）","严禁对孕妇使用任何活血化瘀药物、食疗或泡脚方（p.119, p.124-125）；月经量大的女性经期忌服益母丸（p.127）"],"conditioning_principles":["按成因与部位辨证化瘀：湿热入肾致瘀者一边凉血一边化瘀，受寒老风湿者温阳化瘀，血虚致瘀用桃红四物汤养血化瘀；头面血瘀用通窍活血汤，胸中用血府逐瘀汤，少腹用少腹逐瘀汤（p.120-121）。","泡脚透皮走经络优先：现代人多脾胃不好、体内有痰湿阻碍汤药吸收，用药汁泡脚通过皮肤与经络直接吸收疏通“路障”，效果常比喝药还好（p.121-122）。","湿罩瘀血须祛湿兼化瘀：白苔罩紫黑舌或心脏瘀血伴厚苔湿重时，须先祛湿或一边祛湿气一边清热化瘀（p.118, p.124）。","气郁致瘀必先疏肝理气：因生气肝郁引起的瘀血及甲状腺结节、乳腺结节、子宫肌瘤、卵巢囊肿，必须一边疏肝气一边化瘀（可配合EFT按穴情绪释放技术、艾灸、刮痧）（p.107, p.128）。","寒温配伍防伤阴：心脏瘀血服温燥的三七粉易耗阴致眼干痛，须等量配伍凉润补气阴的西洋参粉（各0.5克）制其热性（p.122-124）。"],"primary_remedy_ids":["rem_region_stasis_decoctions","rem_yaotui_hanshi_footbath","rem_sanqi_xiyangshen","rem_fracture_bone_soup","rem_hemorrhoid_dilong","rem_female_yimu_cycle"]},{"id":"yin_deficiency","name":"阴虚体质","alias":"津血亏虚 / 阴虚内热（含小儿脾阴不足）","chapter_id":"ch07","page_start":129,"page_end":144,"root_causes":["嗜食辛辣伤阴：长期吃川菜、麻辣烫、酸辣粉等过多辛辣刺激食物耗伤津液（p.131）","熬夜耗损阴精：天天半夜12点以后睡觉或长期上夜班，夜间属阴却持续消耗体内津液与物质基础（p.131, p.143）","情绪失常化火伤阴：贪、嗔、痴与焦虑郁闷导致肝气不舒，转化成肝火耗伤肝阴与津血，且木克脾土引发脾虚湿重、血虚、血瘀连锁失调（p.131-133）","儿童吃肉过多致脾阴不足：家庭及幼儿园伙食肉食（鸡腿、鸭肉、鱼虾、猪肉等）过多、营养过剩，食滞伤脾生内热，导致半数以上儿童出现明代缪希雍所论“脾阴不足”（p.135-137）","年老津亏、用脑过度与房劳过度：随年龄增长津液消耗殆尽（老人多阴虚，p.139），或短期赶论文/高强度思考/打电子游戏用脑过度、长期房事过度损耗肾阴物质基础（p.143）"],"body_symptoms":["五心烦热与脾气急躁：手心热、脚心热、心里面烦热，眼干涩迎风流泪、鼻子冒火、嘴干，喝热饮越喝越烦而喜冷饮，脾气大易心烦（p.133-134, p.142）","失眠与盗汗自汗：晚上睡不好，一入睡就一身汗或快睡醒时一身汗，甚则湿透被褥（排除夏季桑拿天正常出汗）（p.134, p.142-143）","大便干燥、尿黄与腰膝酸软：津液亏乏致便干尿黄，长期肾阴虚见腰膝酸软、头晕眼花、长时间细小声音耳鸣耳聋（p.134, p.142）","脉搏偏快或动态加快：成年人脉搏每分钟超过90下，或较自身往常基线动态加快（如原60下升至80下，或原90下升至100下）（p.135, p.142）","虚火粉刺：青春期或过后因肾阴不足、虚火上炎致脸上粉刺频生（尤多见于年轻女性）（p.143-144）"],"child_symptoms":["嘴唇很红、下眼袋肿红：吃肉过多致脾阴不足（脾开窍于口其华在唇，下眼睑对应脾），孩子舌红、嘴唇鲜红，下眼袋肿大发红（p.135）","胃强脾弱（能吃易肚胀）与盗汗难眠：胃口特别好但一吃东西肚子就胀，大便干燥或不成形，入睡后遍体盗汗（p.134）、夜卧翻来覆去睡不着（p.135）","好动、反复感冒且一感冒嗓子就肿：内热过多控制不住而好动；脾伤食滞兼阴虚生热上返，风一吹就感冒，且一感冒嗓子必肿痛（p.136）","心烦耐性差：性情急躁爱心烦，没有耐性坐下来看书或坚持做好一件事，难以养成良好习惯（p.136）"],"core_tongue_features":["舌红苔薄或无苔（萎缩）：未得外感而舌头鲜红，津液耗伤破坏舌面微生物环境致舌苔很薄或萎缩无苔（p.137-138）","舌红而苔不薄（水湿掩盖阴虚）：阴虚合并湿气重时，舌苔覆盖于红舌之上使苔不显薄，正处于复合或转化状态（p.138）","老人红舌深裂纹：老年人舌质很红，舌面有许多很深的裂纹，一吃辣食舌头即不适（p.139）","地图舌：舌苔分布不均，舌面上莫名掉几块苔、露出偏红舌质，绝大多数为阴虚所致（p.139）","舌质由红变淡白（或由淡白变红）：阴虚日久耗少血液，舌质由红慢慢变成淡白色，标志从阴虚转化为血虚体质；反之原本淡白舌渐转红为血虚向阴虚转化（p.140）"],"differentiation_notes":["【虚热与实热鉴别·切勿误服牛黄解毒丸】阴虚舌红属润滑津液不足的“虚热”，须用生地、沙参、麦冬滋阴（虚则补之），若误当外邪或积食“实热”自作主张吃牛黄解毒丸或黄连、连翘、双花清热解毒则无效伤身；实热与虚热交织时须清热兼滋阴双向调节（p.51-52, p.137）。","【钱乙辨小儿三睡汗】宋代儿科名医钱乙区分小儿入睡出汗：半头汗属体内有热（头为诸阳经之汇）当清热；胸以上出汗属脾胃积食当补脾消食；遍体出汗才属阴虚，当予滋阴（p.134）。","【脉搏动态观察】成人脉搏>90次/分提示阴虚可能，但须结合自身日常基线对比；若脉搏跳动缓慢则绝不需要服六味地黄丸（p.135, p.142）。","【六味地黄丸三大禁慎】①舌苔厚、黄腻（排除吸烟与饮橙汁染苔）、胃肠胀闷、大便不成形的湿热/痰湿者禁服，须先清痰湿；②舌淡、脉缓、下肢发凉怕冷、尿清长的阳虚者禁直接补阴，须先补阳或阴阳同补（用金匮肾气丸）；③脾胃功能弱者防熟地滞腻，须用1个砂仁捣碎泡开水冲服（p.142, p.144）。","【阴虚与血虚互转】舌红以血液充盈为前提，临床纯阴虚较少，多数阴虚者久耗血液后舌色由红转淡白变成血虚体质，此时应改用养血法待血足苔生（p.140）。"],"lifestyle_taboos":["忌熬夜（严戒天天半夜12点以后睡觉或长期夜班透支阴精）（p.131, p.143）","忌常吃麻辣烫、酸辣粉、重辣川菜等过度辛辣伤阴食物（p.131, p.139）","忌儿童吃肉过多、营养过剩（必须少吃肉、多吃青菜坚持半年以上才能扭转小儿脾阴不足）（p.135-137）","忌阴虚虚热舌红时盲目自服“牛黄解毒丸”（p.52），忌把六味地黄丸当作壮阳药或在湿热苔厚黄腻、阳虚畏寒时误服（p.142-144）","忌攀比焦虑、郁闷动怒（情绪失常肝气不舒会使调理脾胃和滋阴的药迅速化火失效）（p.132-133）"],"conditioning_principles":["复合体质核心调脾胃、根源调情绪：多体质交缠时以调养后天之本脾胃为中轴，同时必须保持情绪稳定、疏解肝气，防止药食化火（p.132-133）。","虚则补之、甘凉濡润：以生地、沙参、麦冬、石斛等滋补体内津液“润滑油”，使内生虚热自然消退（p.51-52, p.140-141）。","小儿脾阴虚药食同调、减肉增菜：短期用生地薏米石斛沙参麦冬山药莲子肉熬甜水喝5～6天（或莲藕、荸荠、梨水代饮），长期坚持少吃肉、多吃青菜半年以上（p.136, p.140-141）。","肾阴虚三补三泻、兼顾脾胃与阳气：确诊舌红苔薄脉细数之肾阴虚用钱乙六味地黄丸；痰湿厚苔先清痰湿，阳虚改投金匮肾气丸，脾弱配1个砂仁捣碎泡开水冲服化滞引经（p.141-144）。"],"primary_remedy_ids":["rem_child_nourish_yin","rem_adult_yin_bone_soup","rem_liuwei_dihuang"]},{"id":"yang_deficiency","name":"阳虚体质","alias":"脾肾阳气不足型","chapter_id":"ch08","page_start":145,"page_end":153,"root_causes":["熬夜、休息不足、生活作息颠倒导致肾精过度耗损（p.147-148）","房劳过度，或患大病过程中身体与疾病斗争损耗肾阳（p.147）","过多使用抗生素等寒凉性质药物克伐阳气（p.147）","贪饮冰啤酒、冷风久吹先伤脾阳再累及肾阳；或病后涉冰凉溪水/海水、女性冬季穿丝袜、穿薄皮鞋滑冰致下肢肝脾肾三经受寒（p.147-148, 152）","血虚等其他脏器虚损日久不愈，进一步发展为阳虚体质（p.148）"],"body_symptoms":["怕风、怕冷，尤其以腹部和下肢畏寒怕冷最为突出（“阳虚则外寒”，p.149）","阳气无力运行气血上荣面部，面色苍白无血色，或面色晦暗生出较多黑色斑点（p.146, 149, 151-152）","精力较差、萎靡不振、总想睡觉（中医称“但欲寐”，p.146, 148）","小便频数、尿液清长且尿量多，老年人常见每晚起夜五六次，甚则水液不化出现水肿或性欲减退（p.149, 152）","腹部、胃部一遇冷气或吃喝凉食即痛，易遇冷腹泻或中老年人晨起、上午阳气当旺时腹泻（p.148, 150, 153）","重度阳虚火力衰微，津液不能蒸腾上承，反而出现口中干燥、口渴（p.151-152）"],"child_symptoms":["感冒刚愈若下山溪趟冰凉地下水，寒邪直伤肾阳，回家即可突发重症并伴腰酸、腰疼（p.148）","若父母阳虚且母亲孕期未及时调理体质，孩子出生后先天体质易偏弱、偏阳虚（p.169）"],"core_tongue_features":["舌质很淡（不是红色），舌苔发白，整个舌体看上去比较“苍老”（p.150）","唾液量随阳虚轻重呈双向改变：轻度阳虚体内湿气重，舌体唾液偏多呈“舌苔水滑”；重度阳虚津液无法蒸腾而上，舌面与口腔反见干燥（p.150-151）"],"differentiation_notes":["阳虚 vs 血虚三点鉴别之一（夏热反应，p.147）：血虚之人到夏天天热时手就变热了（外热身热、外凉身凉 p.95）；阳虚之人到夏天天热时依然怕冷、怕风。","阳虚 vs 血虚三点鉴别之二（功能层面，p.147）：血虚之人主要是神志功能不强；阳虚之人则是生命整体功能都在下降，且特别容易受寒凉影响。","阳虚 vs 血虚三点鉴别之三（症状侧重，p.147）：血虚问题多体现在神智及对颜色辨别能力的衰退上；阳虚问题主要反映在温度降低时的不适以及生发功能程度的衰退上。","舌象老嫩鉴别（p.150）：阳虚舌淡苔白而形色“苍老”；血虚舌淡白而质地“淡嫩”、略带透明感（p.97）。","口干与补肾药鉴别（p.144, 151）：重度阳虚或部分糖尿病人口干如同蒸饭火弱锅盖无水汽，温阳后津液自生，切勿误当实热清火；肾阳虚舌淡脉缓下肢冷者亦不可误服六味地黄丸直补肾阴，应先用金匮肾气丸补阳。"],"lifestyle_taboos":["严禁喝冰啤酒、冰镇饮料及贪食寒凉生冷食物（p.147-148, 150）","忌冬季下肢保暖不足（如穿单薄丝袜、薄皮鞋）或天冷、病后涉冷水玩耍（p.148, 152）","忌熬夜、作息颠倒、房劳过度及滥用抗生素等寒凉药物（p.147-148）"],"conditioning_principles":["温补脾肾阳气为纲：人体阳气以脾肾最关键，肾阳足则脾阳才能足（p.151）","肾阳不足、老人夜尿五六次、畏寒水肿或涉冷水脚后跟痛者，用金匮肾气丸温肾助阳（受凉配合热水泡脚，p.151-152）","脾阳不足、一沾凉食即胃痛、遇冷腹泻或受寒上吐下泻者，用附子理中丸或理中丸温中散寒（p.152-153）"],"primary_remedy_ids":["rem_jinkui_shenqi","rem_fuzi_lizhong"]},{"id":"phlegm_dampness","name":"痰湿体质","alias":"湿聚成痰·三高预警型","chapter_id":"ch09","page_start":154,"page_end":162,"root_causes":["脾气虚弱累及肺气与五脏六腑正气不足，水湿留滞体内逐渐蒸发、凝炼成黏稠状“痰湿”（p.155）","吃得过多、过好（肥甘厚味）、频繁外出应酬、半夜12点吃夜宵，以及喝水或液体摄入过多（p.155-156）","饮食不均衡、贪食寒凉、饮食不顺应四时节律（p.156）","根本原因在于神志和情志失调：压力大、心情郁闷致肝气不舒（肝木克伐脾土），加之美食前不够冷静、管不住嘴（p.156）"],"body_symptoms":["整天感觉浑身没力气、容易犯困，暴饮暴食或吃肥甘厚味后夜间身体痛苦难受（p.156, 159）","高度伴发“三高”代谢问题（高血压、高血脂、高血糖，p.157-158）","痰湿郁久化热时可见两腮发红、体内燥热失调（p.158-159）","正气不足固摄无力时，老人或小朋友可出现脏器下垂、脱肛（p.155）"],"child_symptoms":["小朋友脾虚正气不足、固摄能力弱时容易发生脱肛（p.155）"],"core_tongue_features":["舌面上覆盖黏腻的水液、看上去不干爽，且舌中纵沟明显（提示基本已有“三高”，p.157）","舌苔厚腻、白得像霜一样（提示湿已成痰，毫无疑问多有“三高”，p.157-158）","舌苔微黄初腻（痰湿初起，伴两腮红为有热），或舌后半部集中厚腻苔伴裂纹（p.158）","舌苔白厚黏腻渐转黄，且舌质发红、有红点（营养过剩，热与湿结成痰瘀状态，p.158-160）"],"differentiation_notes":["痰湿乏力 vs 肾虚乏力（p.159）：痰湿者虽常诉整天没劲、犯困，但舌苔厚腻、舌质发红实属“营养过剩、痰热阻滞”，绝不能被不看舌象者误当肾虚补肾，否则越补越热、百病丛生。","普通水湿 vs 凝结成痰（p.155, 157-158）：一般湿重仅见薄白满布苔或齿痕，若出现黏腻水液或白霜样厚腻苔则已炼湿成痰，往往已伴随“三高”。","泡脚给药 vs 口服汤药（p.161-162）：现代痰湿者脾胃受损严重、痰湿堵在中焦无法吸收汤药，临床用温胆汤泡脚经皮肤经络吸收反而比吃药见效更好。"],"lifestyle_taboos":["严禁进补或乱服补肾保健品（体内营养已过剩，进补必致内热炽盛、加重失调，p.159, 162）","忌每天肥甘厚味、暴饮暴食、过度应酬及半夜吃夜宵（p.155-156, 162）","忌贪食寒凉、盲目过量饮水及久坐不动（p.155-156, 162）"],"conditioning_principles":["恪守“以清为补”：往下清泄排痰而非进补，日常吃萝卜白菜、粗茶淡饭，坚持素食甚至适当断食（p.159, 162）","用罗氏去生姜“温胆汤”泡脚祛湿化痰清热（现代人痰多化热故去生姜，热重竹茹配至9克；如需口服须请当地中医加减，p.160-161）","以坚持运动作为最好的药方，配合冷静自控的心态与合理饮食长期维护（p.156, 161-162）"],"primary_remedy_ids":["rem_wendan_footbath","rem_phlegm_diet_exercise"]},{"id":"qi_stagnation","name":"气郁体质","alias":"肝气不舒型","chapter_id":"ch10","page_start":163,"page_end":190,"root_causes":["现代社会攀比与压力空前，七情六欲求而不得，长期担忧、着急、焦虑不安（约80%疾病、90%女性疾病与情绪相关，p.165-168）","自我要求完美苛刻的“单位老好人”遇矛盾委屈隐忍不发，把火憋在心底形成长年“郁怒”（比发泄出来的暴怒伤害更深更不可逆，得肿瘤比例最高，p.168-169）","退休后失落、感情重创或生活工作遭遇重大变故诱发情绪失常（常成为糖尿病、肿瘤等大病诱因，p.167, 174）","家庭气氛压抑紧张，家长将工作焦虑或学业苛求传染给孩子（p.169-170）"],"body_symptoms":["张仲景《伤寒杂病论》少阳证8项典型指标：①口苦口干、咽喉干；②眩晕；③胃口不好、不想吃东西；④忽冷忽热；⑤恶心、反酸水、向上返气欲呕；⑥胸闷、心悸、心脏跳动异常；⑦肋骨里面胀痛；⑧失眠多梦（p.171-172）","女性常见“心脏病假象”：因女性情绪波动多且肝木生心火，常以胸闷、心烦、喜呕、心悸、肋胀痛去查心脏，实为肝气不舒（但长期失调亦会真正诱发心脏病，p.172-173）","肝木克脾土消化道症状：胃痛、胃溃疡（餐前或餐后上腹痛）、胃内灼热发烧、反流性食管炎/胃炎，以及夜间胃酸上逆浸泡咽喉导致的慢性咽炎（p.173-174, 180-181）","“木火刑金”呼吸系统症状：过旺肝火反侮肺金，引起咳嗽、走路气喘、出虚汗乃至严重肺病，典型信号是凌晨3～5点肺经当令时无故早醒（p.174-175, 184）","情绪波动型高血压（一生气或每逢春季血压升高，p.185），以及女性高发甲状腺结节、甲亢/甲减、乳腺增生（患乳腺癌比例比常人高4倍）、子宫肌瘤与卵巢囊肿（p.187-188）"],"child_symptoms":["受焦虑型父母压抑紧张气场影响（最小可见于2岁幼儿），孩子情绪变得紧张焦虑、反复咳嗽生病（p.169-170）","学龄儿童长期承受母亲考分高压，舌形已塑造成典型尖舌；或新生儿刚出生舌形即尖，提示气郁倾向需及早调护（p.170, 179-180）"],"core_tongue_features":["最鲜明标志是舌头伸出来呈尖尖的锥形（而非椭圆形），舌尖与舌两侧边缘发红（心肝有火，p.176）","舌头刚伸出来时尖尖的，再伸展开却变成胖胖圆圆的舌象（肝郁气滞无力推水，水湿积聚舌体，p.177）","舌形尖尖、舌边舌尖红，而舌面铺有白苔（对应少阳证“舌上白苔”，提示旧郁未消或现正肝郁水停，p.178-179）","尖舌前部无苔、舌尖变红（近期压力焦虑致心火偏旺，p.179）"],"differentiation_notes":["郁怒 vs 暴怒（p.168-169）：暴怒虽肝火旺但发泄后内伤较轻；老好人“郁怒”把火憋在心里不发（或只在家里发火），内伤更不可逆，是肿瘤患者中最常见的性格特征。","舌苔快变 vs 舌形器质慢变（p.43, 170-171）：吃西瓜等几天就能改变舌苔，但尖舌属于数年焦虑或半年以上重大压力塑造的器质性改变，消退亦极慢；若服中药后睡眠情绪好转但尖舌未变，说明郁根尚在，必须继续调神养心。","肝郁胖圆舌 vs 单纯脾虚胖大舌（p.177-178）：看到胖圆舌（或伴唾液线 p.78）不可只想到脾虚，若初伸尖再变胖说明根源在肝气不舒致水湿停聚，祛湿后尖舌常会显露。","女性胸闷心悸辨异（p.172-173）：女性心脏病发作前常无典型剧烈胸痛而表现为胸闷、心烦、喜呕，恰与肝气不舒一致，须结合尖红舌象并赴医院排查心脏器质病变。"],"lifestyle_taboos":["忌做苛求完美、凡事隐忍生闷气的“老好人”（p.168-169）","家长严禁将职场焦虑与严苛高压情绪发泄、传染给孩子（p.169-170）","老年人忌为儿孙未发生之事过度操心忧虑（p.186-187）","忌边生气边吃饭或高压下饥一顿饱一顿（极易引发胃痛、胃溃疡及顽固血瘀，p.106, 181）"],"conditioning_principles":["调神安神为最高原则：效法《黄帝内经》春季庭院散步调整情绪，“把好东西尽量给予大家，不要去夺取，尽量奖赏别人，不要去惩罚他”以养心安；复合体质须一边疏肝调神，一边同步祛湿、化瘀、滋阴或温阳（p.166-167）","见肝之病，知肝传脾，当先实脾：肝郁胃痛服舒肝和胃丸，脾胃虚寒胃溃疡配黄芪建中汤（罗氏用生黄芪6克防上火）柔肝建中（p.180-181）","失眠多梦用柴胡加龙骨牡蛎汤加味15味泡脚（1周1疗程共3周，原书明标孕妇忌用 p.182, 202），情绪性高血压用20味平肝潜阳泡脚方（含怀牛膝、丹皮等活血药，依 p.119 原则妊娠避忌）；暂时压力心火可喝灯心竹叶汤（灯心草、竹叶各6克，保健各3克煮水代茶，p.182-186, 189-190）","木火刑金凌晨3～5点早醒者每日沿胳膊内侧肺经敲揉痛点至不痛（p.183-185）；甲状腺结节用10味疏肝通络泡脚方，乳腺增生服加味逍遥丸/丹栀逍遥丸（p.188-189）"],"primary_remedy_ids":["rem_shugan_huangqi_jianzhong","rem_chaihu_longgu_muli_insomnia","rem_tap_lung_meridian","rem_liver_hypertension_footbath","rem_thyroid_breast_footbath","rem_dengxin_zhuye"]}],"tongue_signs":[{"id":"sign_normal_pale_red","title":"淡红舌、薄白苔（基本健康舌象）","constitution_ids":[],"zone_ids":["zone_whole","zone_center"],"fig_id":"fig_p035","risk_level":"normal","alert_tags":[],"visual_features":"舌体运动灵活有神，舌边未被舌苔覆盖的一圈舌质呈润泽淡红色（淡红舌），舌体正中间均匀铺一层薄薄的淡白色舌苔（薄白苔），蕈状乳头呈隐隐小红点而不偏大（p.25、p.35、p.47、p.53、p.76）。","clinical_meaning":"说明体内正气充足、血液充盈且流通顺畅，体温寒热适中，胃气生发与脾胃运化水湿功能正常（p.25-26、p.34-35、p.47、p.58）。","differential_tip":"舌诊没有一刀切的绝对标准，胖人舌略胖、瘦人舌略瘦，冬季舌质可微偏白、夏季6月可略偏红润，均需以个人日常健康基线作动态对比（p.34-36、p.50）。","action_principle":"无需药物调理，保持良好情绪、合理饮食与积极锻炼，日常于白天背阳间接日光下动态留意舌象变化即可（p.35、p.39、p.192）。","remedy_ids":[],"page":35},{"id":"sign_pale_white_base","title":"舌质淡白（血虚或寒盛阳虚基础象）","constitution_ids":["blood_deficiency","yang_deficiency"],"zone_ids":["zone_whole"],"fig_id":"fig_p047","risk_level":"warning","alert_tags":[],"visual_features":"舌边露出的舌质颜色缺乏红润感，朝淡白方向发展（淡白舌），血流缓慢供应不足；若严重到毫无血色的枯白舌则属罕见危重之象（p.47、p.58）。","clinical_meaning":"代表血虚，或体内温度不足——排除血虚后，一是外界寒邪有余（如严冬受寒、贪饮冰啤冷饮吹空调、天冷穿衣单薄受冻），二是体内阳气不足（如夏季仍畏风怕冷、长期熬夜房劳耗损肾阳），且舌色越白体寒越重（p.47-50）。","differential_tip":"先排除晨起血液未充盈及冷光灯偏色假象（p.37-39）；再与‘舌苔满布’鉴别：舌边一圈无舌苔颗粒覆盖而底色发白才是舌质淡白（p.71-72）；进一步区分血虚（淡嫩）与阳虚（苍老）需结合全身症状（p.150、p.198-199）。","action_principle":"注意防寒保暖、戒绝冰镇寒凉饮食与熬夜损耗；结合症状辨明血虚或脾肾阳虚后针对性养血或温阳散寒，若见枯白舌须立即就医（p.47-50、p.191-192）。","remedy_ids":[],"page":47},{"id":"sign_red_crimson_purple","title":"舌质发红及向绛色、青紫演变","constitution_ids":["yin_deficiency","blood_stasis"],"zone_ids":["zone_whole"],"fig_id":"fig_p048","risk_level":"warning","alert_tags":[],"visual_features":"舌质颜色由淡红逐渐变红，随热势加深继而变为绛色（深红），再向下发展则变为紫色带青的青紫色（p.48、p.50-51）。","clinical_meaning":"提示体内热在增加或热灼血稠致瘀：外因多为感染温病热邪（伴发烧、咽喉肿痛、便干）；内因一是肉食积食化湿生痰蕴积之‘实热’（伴黄腻苔）或实邪瘀滞生热，二是津液血液亏虚失润所致‘阴虚生内热’（虚热），热盛蒸干血中水分亦会致瘀（p.48、p.50-52、p.109）。","differential_tip":"先排除饭后半小时咀嚼充血、夏季炎热轻微偏红及经期舌尖红假象（p.38、p.40、p.50）；临床最忌混淆实热与虚热：阴虚红舌属虚热，盲目吃牛黄解毒丸或黄连、连翘、双花清热无效，须用生地、沙参、麦冬类滋阴，而实热耗津虚实夹杂时须清热与滋阴动态配比（p.51-52）。","action_principle":"外邪与积滞实热当清热消滞，阴虚内热当滋阴润燥，转青紫兼瘀血指征者需结合血瘀部位请当地中医辨证清热凉血或化瘀（p.51-52、p.116-117、p.191-192）。","remedy_ids":[],"page":48},{"id":"sign_charred_black_coating","title":"舌苔焦黑（外感入里化热极重象）","constitution_ids":[],"zone_ids":["zone_whole","zone_center"],"fig_id":"fig_p056","risk_level":"high_alert","alert_tags":["外感化热重症"],"visual_features":"舌苔由基础淡白色随热势加深依次变为淡黄色、黄色、灰色，最终干枯焦燥呈焦黑色，甚者结成黑壳（p.56-57）。","clinical_meaning":"提示感受外邪后入里化热不断加剧，发展至舌苔焦黑说明体内热邪已极度炽盛（如外感高烧久拖不治的重症阶段）（p.56-57）。","differential_tip":"必须先排除服用某些抗生素、食用含化学添加剂食物（如问题酸菜）或喝咖啡造成的染黑苔假象（p.37、p.39）；并严辨津液润燥：本象干焦燥裂属热极，若黑苔上满是唾液、湿润粘腻则属水湿极重（p.57），若白苔罩着紫黑舌体则属湿气掩盖瘀血（p.118-119）。","action_principle":"属外感化热危重警报，切勿在家硬挺或自行盲目用药，须立即前往医院由执业医师救治清热存津（热清后旧黑壳退去方生新苔，p.56-57、p.191-192）。","remedy_ids":[],"page":56},{"id":"sign_moist_greasy_black_coating","title":"滋润粘腻灰黑苔（水湿痰湿极重象）","constitution_ids":["phlegm_dampness","qi_deficiency"],"zone_ids":["zone_whole","zone_center"],"fig_id":null,"risk_level":"warning","alert_tags":[],"visual_features":"舌苔由薄苔变得粘腻，进而转为灰黑色乃至黑色，但苔面满是唾液、非常滋润，并非焦黄或干枯焦黑（p.57）。","clinical_meaning":"提示脾胃虚弱、阳气不足基础上，外感湿邪或内生湿气严重积聚，水湿与痰湿已重到极点（虽不多见但须识别）（p.57）。","differential_tip":"与外感热极‘舌苔焦黑’的核心区别在于润燥：本象满布唾液、十分滋润粘腻，属湿气极重而非实火焦灼；同时须排除抗生素或化学添加剂（如酸菜）染苔假象（p.39、p.56-57）。","action_principle":"严禁误作热证滥用苦寒清火药，应请当地中医辨证化湿祛痰、温助脾阳，湿退后及时补脾固本（p.57、p.65、p.191-192）。","remedy_ids":[],"page":57},{"id":"sign_peeled_or_thin_stomach","title":"舌苔过薄或剥落消失（胃气虚弱或阴虚伤正象）","constitution_ids":["qi_deficiency","yin_deficiency"],"zone_ids":["zone_center","zone_whole"],"fig_id":null,"risk_level":"warning","alert_tags":[],"visual_features":"舌面舌苔明显过薄、极薄，甚至完全退去光洁无苔（危重者可在一夜之间舌苔突然退尽），需合参舌质底色偏白或偏红定性（p.40、p.55、p.57）。","clinical_meaning":"舌苔为胃气所生，‘苔少反映体内正气不足’：舌质发白而苔过薄或无苔，说明胃气虚弱、脾胃受损（如大病后伤脾胃或天天喝大酒伤胃）；舌质发红而苔薄或无苔（萎缩），说明阴虚有热；若病中一夜之间舌苔骤退，提示身体状况急转直下（p.40、p.55、p.57、p.81-82）。","differential_tip":"先排除饭后吃芹菜等粗纤维食物磨掉舌苔或人为刮舌苔造成的假象（p.38、p.53-54）；若属舌红少苔的阴虚虚热，切忌误作实火自作主张服用‘牛黄解毒丸’（p.52）。","action_principle":"绝对不可人为刮舌苔，以保护舌面益生菌微生态与食物消化第一阶段功能（犹如保护肠道共生菌免受抗生素滥杀，p.53-55）；舌白少苔当生发胃气、调养脾胃，舌红少苔当滋阴润燥，一夜骤退苔者须即刻就医（p.52、p.55、p.57、p.81-83）。","remedy_ids":[],"page":55},{"id":"sign_qi_spleen_damp_full","title":"脾气虚水湿满布舌","constitution_ids":["qi_deficiency"],"zone_ids":["zone_whole","zone_center"],"fig_id":"fig_p066","risk_level":"warning","alert_tags":["脾虚湿滞","祛湿必补脾"],"visual_features":"舌面铺满了水湿，水湿滞留在整个舌体表面（见第65-66页插图 fig_p066）。","clinical_meaning":"“脾气虚，身体肯定湿重。”表明脾胃运化与“脾主统水”功能出问题，本该经尿液、汗液排出的代谢水湿停滞在体内阻碍气血运行；若长期累积不治，会进一步发展为痰湿体质（pp.64-66）。","differential_tip":"与单纯暂时积食的浮泛无根苔（pp.79-80）不同，此类水湿铺满舌面系脾肾肺气虚失于统水所致，若只祛湿而不补脾，过三五天水湿必再次返回（p.65）。","action_principle":"一边祛除水湿，一边补足脾气；湿气去掉之后必须马上补脾（如接服山药薏苡仁芡实小米粥），借脾气充足双向带动肾气与肺气恢复（pp.65, 83-85）。","remedy_ids":["rem_sanren_footbath","rem_shanyao_yiyiren_qianshi"],"page":66},{"id":"sign_qi_teeth_marks","title":"气虚湿重明显齿痕舌","constitution_ids":["qi_deficiency"],"zone_ids":["zone_left","zone_right","zone_whole"],"fig_id":"fig_p068","risk_level":"warning","alert_tags":["脾虚水肿","排查牙齿畸形"],"visual_features":"伸出舌头可见舌体略肿胀，舌两侧边缘有一排明显的牙齿压印（齿痕）（见第68页插图 fig_p068）。","clinical_meaning":"说明气虚（尤以脾气虚为主）、体内没有排出的湿气比较重，引起内脏与舌体水肿，肿胀的舌头一天24小时挤压在牙齿边上而形成齿痕；多由贪吃寒凉/受外寒伤脾阳，或运动少、不晒太阳、排汗少致湿气内困引起（pp.68-69）。","differential_tip":"首先必须排除“牙齿畸形”：若本身有几颗牙齿长得不正常、天天压迫舌头，也会留下物理性齿痕，不属于水湿气虚（p.69）。此外也有少数舌体偏瘦但仍有齿痕者，同样属脾气虚表现（p.81）。","action_principle":"戒除寒凉冰饮，先祛湿再马上补脾，并配合循序渐进的户外日晒与运动排汗以生发阳气（切忌突然高强度暴走损伤关节，pp.69-70, 83-86）。","remedy_ids":["rem_sanren_footbath","rem_shanyao_yiyiren_qianshi","rem_buzhong_bazhen"],"page":68},{"id":"sign_qi_full_coating","title":"水湿重舌苔满布","constitution_ids":["qi_deficiency"],"zone_ids":["zone_whole"],"fig_id":"fig_p071","risk_level":"warning","alert_tags":["水湿重","辨舌边苔粒"],"visual_features":"舌苔过度生长，把整个舌头连同舌边都铺满了，一点正常淡红舌质都没露出来（见第71页插图 fig_p071）。","clinical_meaning":"代表人体内水湿很重（如遇雾气重、连日阴雨天，或长期睡阴面房、北方卧室过大耗阳，以及白领久坐空调房喝冷饮吃反季节水果所致）；苔薄而满布者湿尚轻，苔愈厚湿愈重，厚极则凝结成体内黏稠之“痰”（pp.70-74）。","differential_tip":"极易与“舌质淡白”（fig_p072）混淆：区分要点在于仔细看“舌苔的颗粒是不是把舌边都铺上了”——若舌边也被舌苔颗粒铺满，即为舌苔满布；若舌边未被舌苔完全覆盖而底色发白，则为舌质淡白（pp.70-71）。","action_principle":"及时按季节除湿（三仁汤泡脚，春夏可用薏苡仁赤小豆饮，秋冬用辛香调料与川椒泡脚），改善阴冷大卧室与久坐冷饮习惯，湿退即补脾（pp.72-74, 83-85）。","remedy_ids":["rem_sanren_footbath","rem_yiyiren_chixiaodou","rem_autumn_winter_spice_footbath","rem_shanyao_yiyiren_qianshi"],"page":71},{"id":"sign_blood_pale_no_full_coat","title":"非满布苔之舌质淡白","constitution_ids":["blood_deficiency"],"zone_ids":["zone_whole"],"fig_id":"fig_p072","risk_level":"warning","alert_tags":["防误判为苔满布","血虚气血亏"],"visual_features":"舌头并未被舌苔颗粒完全覆盖（舌边仍露出舌质），但舌质颜色很淡白，白到几乎与薄白舌苔同一个颜色，乍看极像舌苔满布（见第72页插图 fig_p072）。","clinical_meaning":"说明并非水湿舌苔过度生长，而是舌质本身淡白无血色，提示血液不足（血虚）或兼体内有寒、阳气不足（pp.47, 70-72, 96-97）。","differential_tip":"与第71页“舌苔满布”（fig_p071）对照鉴别：区分要点在于看舌苔的颗粒是不是把舌边都铺上了；舌头未被舌苔完全覆盖且呈淡白者为舌质淡白，不可误作舌苔满布而只除湿不养脾养血（pp.64, 71-72）。","action_principle":"以健脾养血为主（如当归养血鸡汤、玉灵膏）；若兼有水湿停滞，也必须一边祛湿一边养脾养血，防止气血管道空虚（pp.64, 97-102）。","remedy_ids":["rem_danggui_chicken_soup","rem_yulinggao"],"page":72},{"id":"sign_qi_damp_masks_heat","title":"舌苔满布湿气掩盖热象（附舌尖红妇科/前列腺提示）","constitution_ids":["qi_deficiency"],"zone_ids":["zone_whole","zone_tip","zone_left","zone_right"],"fig_id":"fig_p074","risk_level":"warning","alert_tags":["湿掩热象","妇科/前列腺筛查提示"],"visual_features":"白苔满布整个舌面，乍看舌头不红似有寒，但仔细观察可见舌尖（或舌侧肝胆区）在白苔遮盖下隐隐透出微红色（见第74页插图 fig_p074）。","clinical_meaning":"体内湿气重并把真实内热（或气郁、瘀血）蒙蔽住了：舌尖微红被盖住提示有热或心火（发愁担忧），红集中在肝胆位置之间则提示肝胆有火（肝胆热瘀）。此外舌尖对应心、小肠，同时又对应下焦生殖系统——女性除月经期生理变红外，下焦有热患妇科疾病时舌尖会红；男性有前列腺疾病时舌尖也会红（pp.74-75）。","differential_tip":"不可因表面白苔不甚红而误判为纯寒证妄投温燥药；一旦把铺得过满的舌苔祛掉，原本被遮盖的舌尖红、肝胆火或瘀血真象就会显露出来（pp.74-75）。","action_principle":"身体有问题，祛湿气是第一步；此类患者在祛湿的同时应稍微加一点清热药（如三仁汤配竹叶，或配灯心竹叶汤），防止祛湿后内热太盛，待满苔退去再据真实舌象调治，并排查妇科或前列腺下焦热（pp.74-75, 83-84）。","remedy_ids":["rem_sanren_footbath","rem_dengxin_zhuye","rem_yiyiren_chixiaodou"],"page":74},{"id":"sign_qi_fungiform_red_dots","title":"蕈状乳头偏大、舌尖至舌中红点（脾虚湿热 / 饮酒食肉芒刺）","constitution_ids":["qi_deficiency"],"zone_ids":["zone_tip","zone_front","zone_center","zone_whole"],"fig_id":"fig_p076","risk_level":"warning","alert_tags":["脾虚湿热","小儿上焦热莫误滋阴"],"visual_features":"舌边有齿痕，舌苔铺得较满且微带发黄，舌面上蘑菇状的蕈状乳头偏大，红点集中在舌尖到舌中部（上焦），穿透舌苔显露出来（见第76页插图 fig_p076）。","clinical_meaning":"舌有齿痕提示脾虚，苔满微黄伴红点透出说明体内湿气很重且内热已掩盖不住，属脾虚湿热、热聚上焦。若孩子出现此种红点，说明孩子上焦热很严重；若成年人满舌都有非常明显的红点（芒刺）且面色发红，则多因过量饮用白酒、吃肉及各种营养物过多致体内积热（pp.76-77）。","differential_tip":"小儿见此舌象必须与阴虚红舌严格区分：此系上焦实热/湿热，调理应以清热为主，绝非滋阴问题（p.77）；满舌芒刺伴面红者则属酒肉营养过剩积热（p.77）。","action_principle":"上焦红点用清宫“灯心竹叶汤”（淡竹叶3克、灯心草3克）泻心火，湿重配莲子心除湿；满舌芒刺面红者须立刻停止过度应酬饮白酒，改吃五谷杂粮、清淡蔬菜或采用轻断食、喝点酵素清减体内淤积（pp.76-77）。","remedy_ids":["rem_dengxin_zhuye","rem_yiyiren_chixiaodou","rem_sanren_footbath"],"page":76},{"id":"sign_qi_saliva_lines","title":"舌圆胖微齿痕伴两条唾液线","constitution_ids":["qi_deficiency","qi_stagnation"],"zone_ids":["zone_left","zone_right","zone_center","zone_whole"],"fig_id":"fig_p078","risk_level":"warning","alert_tags":["肝郁困脾","中焦气堵黏汗"],"visual_features":"舌头呈圆圆的形状，稍微有点胖大、有点齿痕，舌苔往往薄薄的并不很厚，一伸出来舌面上就有两条唾液线（见第78页插图 fig_p078）。","clinical_meaning":"系肝气不舒导致气瘀，气不流通把脾困住，加之本身脾气不足，使水液代谢失常而致体内水湿、痰湿很重。多处于亚健康状态（严重则致病），常见浑身没劲、爱发困、出汗发黏、一吃饭就一身汗，且因中焦脾胃之气堵住而呈“上半身出汗、下半身无汗”（pp.78-79）。","differential_tip":"虽体内水湿很重，但舌苔往往薄而不厚，依靠圆胖微齿痕舌面上的“两条唾液线”及情绪不畅、上半身黏汗特征即可识别肝气不舒困脾之湿；就诊望诊前切勿化妆涂口红，以免掩盖唇边伴随的气血瘀像（pp.78-79）。","action_principle":"疏达肝气以解脾困，配合祛湿健脾（如三仁汤泡脚后接山药薏苡仁芡实粥）畅通中焦气机（pp.78-79, 83-85）。","remedy_ids":["rem_sanren_footbath","rem_shanyao_yiyiren_qianshi"],"page":78},{"id":"sign_qi_floating_coating","title":"舌胖大齿痕配浮泛无根腻苔","constitution_ids":["qi_deficiency"],"zone_ids":["zone_whole","zone_center"],"fig_id":null,"risk_level":"warning","alert_tags":["暂发积食/食物染腻","无根浮苔湿轻"],"visual_features":"舌头看上去又胖又大、齿痕明显（提示有些水肿），舌面上的苔虽显得很腻但分布不均匀，整个舌苔浮起飘在表面，好像一刮就能刮掉，中医称为“虚浮”或“浮泛”无根苔（pp.79-80）。","clinical_meaning":"说明体内湿气并不严重，而是本来正气不足之人短时间内吃多了、喝了牛奶或吃了特定食物后暂时出现的舌象；在孩子身上则多为暂时的积食表现（pp.79-80）。","differential_tip":"与去除难度较大的真性厚苔（p.74）区分：虚浮（浮泛）苔没有根，是暂时出现的，体内湿气不严重，稍微用点药或调整清淡饮食一天就能消失；切勿自行刮舌苔以免破坏益生菌与舌体消化微环境（pp.53-55, 79-80）。","action_principle":"改为清淡饮食，吃几天粗粮、蔬菜，喝点萝卜汤消食化滞，一天左右虚浮舌苔即可退去，随后温和调补脾胃正气（p.80）。","remedy_ids":["rem_shanyao_yiyiren_qianshi"],"page":79},{"id":"sign_qi_center_crack","title":"舌中间明显分叉裂纹","constitution_ids":["qi_deficiency"],"zone_ids":["zone_center"],"fig_id":"fig_p080","risk_level":"warning","alert_tags":["脾胃气虚","舌中沟失养"],"visual_features":"舌头两边齿痕不明显，但舌中间的裂纹特别明显，甚至向旁分出好多叉、变成各种各样的裂纹（见第80页插图 fig_p080）。","clinical_meaning":"舌中对应脾胃，说明脾胃功能差、脾胃气不足，无力生发足够的舌苔去弥补舌中间固有的沟纹，从而显露出深而分叉的裂纹（p.80，附录 p.194）。","differential_tip":"正常人舌中间原本也都有淡淡的一点舌中沟，通常被正常薄白苔弥补而看不明显，即便隐约看到淡沟也不算病；唯有裂纹特别明显甚至分出多叉，或老年舌红伴深裂纹、吃辣不适（属阴虚，见附录 p.197）时方属病态（p.80）。","action_principle":"专注补益脾胃之气、升发胃气生苔（如生麦芽养胃茶、山药薏苡仁芡实小米粥、八珍糕），严戒冰饮伤胃（pp.80, 82-88）。","remedy_ids":["rem_shengmaiya_tea","rem_shanyao_yiyiren_qianshi","rem_buzhong_bazhen"],"page":80},{"id":"sign_qi_swollen_tongue","title":"正气不足胖大舌","constitution_ids":["qi_deficiency"],"zone_ids":["zone_whole"],"fig_id":"fig_p081","risk_level":"warning","alert_tags":["正气不足","脾气亏虚"],"visual_features":"舌体整体显得宽大肥厚、充满口腔，舌色偏淡（见第81页插图 fig_p081）。","clinical_meaning":"舌体胖大是体内正气不足、脾气虚的典型表现，因脾虚失于运化统水、肌肉松弛水湿内停所致（p.81）。","differential_tip":"气虚者多见舌体胖大，但需知也有部分脾气虚者舌体偏瘦而舌边仍带齿痕，不可因舌瘦无胖大而漏判脾气虚（p.81）。","action_principle":"健脾益气、温阳除湿并重，祛除内停水湿后坚持用山药薏苡仁芡实粥或补中益气丸、八珍糕补足脾气（pp.81, 83-88）。","remedy_ids":["rem_shanyao_yiyiren_qianshi","rem_buzhong_bazhen","rem_sanren_footbath"],"page":81},{"id":"sign_qi_no_coating_pale","title":"无舌苔或极薄苔且全舌发白","constitution_ids":["qi_deficiency"],"zone_ids":["zone_whole","zone_center"],"fig_id":null,"risk_level":"warning","alert_tags":["胃气匮乏","大病/饮大酒伤胃"],"visual_features":"舌头上光光的没有舌苔，或者舌苔极薄，同时整个舌头看上去白白的、毫无红润血色（pp.81-82，附录 p.194）。","clinical_meaning":"说明体质差、正气虚，尤其是脾胃之气（胃气）严重不足。常见于两类人：一是患了一场大病之后脾胃受创导致舌苔退去；二是平时饮食严重不当（如天天喝酒、喝大酒）直接把胃气伤了（pp.81-82）。","differential_tip":"与阴虚无苔/少苔鉴别：舌质又红又没有苔属阴虚（见 p.55、附录 p.197），而脾胃气虚伤胃无苔者整个舌头看上去白白的（见 p.55, 81）；另需注意若舌头伸不出来或伸不长，未必是心气不足，可能是天生舌下系带过短（且无法翘起看舌下，p.82）。","action_principle":"当务之急是调补脾胃、生发胃气——大病后“脾胃足了身体才有救”；少猛喝白水、戒除大酒，用生麦芽30～60克泡茶（或配生黄芪3克、怀山药6克、生麦芽9克煮水）一直喝到舌苔重新生出来（pp.81-83）。","remedy_ids":["rem_shengmaiya_tea","rem_shanyao_yiyiren_qianshi"],"page":81},{"id":"sign_blood_mild_pale_edge","title":"舌边颜色浅淡微透明（轻微血虚舌）","constitution_ids":["blood_deficiency"],"zone_ids":["zone_left","zone_right","zone_whole"],"fig_id":"fig_p096","risk_level":"warning","alert_tags":["轻微血虚","早期察微"],"visual_features":"初看近似正常舌，但仔细观察可见舌边颜色很浅（不如正常舌边红润），全舌颜色偏淡甚至略偏白，舌质已带有一点半透明的感觉（见第96页插图 fig_p096）。","clinical_meaning":"表明体内血液已经亏了一点，不仅舌黏膜内毛细血管的血液充盈状态欠佳，舌体内部肌肉的气血充盈状态也开始变差，属轻微血虚的早期信号（p.96，附录 p.195）。","differential_tip":"部分人易将此种轻度浅淡舌误划为正常舌象；与正常淡红舌（fig_p035）相比，正常舌边应当红润饱满，凡舌边变浅淡且略呈半透明感者即应察觉轻微血虚（p.96）。","action_principle":"及早调整饮食（忌过饱伤脾）、减少思虑与熬夜，日常可用当归养血鸡汤煲汤温和养血，防微杜渐（pp.90-93, 96-98）。","remedy_ids":["rem_danggui_chicken_soup","rem_yulinggao"],"page":96},{"id":"sign_blood_typical_transparent","title":"舌质极浅近透明（典型血虚舌）","constitution_ids":["blood_deficiency"],"zone_ids":["zone_whole"],"fig_id":"fig_p097","risk_level":"warning","alert_tags":["典型血虚","舌质淡嫩透明"],"visual_features":"舌苔并未把整个舌头铺满，露出的舌质颜色非常浅淡，甚至呈现一种半透明、透明的质感，整体偏淡嫩（见第97页插图 fig_p097，并见附录 pp.195, 198-199）。","clinical_meaning":"典型的血虚舌象，说明舌黏膜毛细血管与舌体内部肌肉的气血充盈状态均严重不足；常伴蹲下1分钟站起眼前发黑头晕、失眠多梦健忘、神智疲劳、浑身无筋般乏力及冬冷夏热不耐受（pp.94-97）。","differential_tip":"与阳虚淡白舌（fig_p150）鉴别：阳虚舌质很淡、白苔且看上去比较“苍老”，夏天炎热时觉得舒服；典型血虚舌质浅淡透明而偏“淡嫩”，且夏天亦可能热得受不了（pp.95-97，附录 pp.198-199）。","action_principle":"大力养心脾之血、安心神：首选王孟英玉灵膏（龙眼肉300克、西洋参粉30克，优选蒸40小时古法防上火）配合当归养血鸡汤，同时严戒熬夜与过度思虑（pp.91-93, 97-102）。","remedy_ids":["rem_yulinggao","rem_danggui_chicken_soup"],"page":97},{"id":"sign_stasis_tip_spots","title":"舌尖及舌面明显瘀点（瘀血初起或已形成）","constitution_ids":["blood_stasis"],"zone_ids":["zone_tip","zone_whole"],"fig_id":"fig_p112","risk_level":"warning","alert_tags":["血瘀信号"],"visual_features":"舌尖及舌面上出现明显的黑色点或青色点（舌体蕈状乳头内毛细血管血液循环不通畅、堵在里面，由正常鲜红点变成黑点或青点）。","clinical_meaning":"舌尖出现很明显的瘀点表明体内瘀血即将形成；若舌面已出现黑点或青点，说明毛细血管堵塞、体内已有瘀血（p.112）。","differential_tip":"区分湿热充血的鲜红点（p.76）与血液瘀堵变暗的青黑点（p.112）；孕妇舌现瘀血指征属胎儿气血凝聚正常现象，切勿当病态化瘀（p.119）。","action_principle":"排查外伤、手术、生气、受寒或久坐气虚等诱因，请当地中医辨明部位与寒热虚实后活血通络，可配合中药泡脚促进吸收（孕妇严禁化瘀）。","remedy_ids":["rem_region_stasis_decoctions","rem_sanqi_xiyangshen"],"page":112},{"id":"sign_stasis_severe_spots","title":"舌尖和舌两侧大量黑色或青色瘀点瘀斑","constitution_ids":["blood_stasis"],"zone_ids":["zone_tip","zone_left","zone_right"],"fig_id":"fig_p113","risk_level":"warning","alert_tags":["重度血瘀"],"visual_features":"舌尖和舌头左右两侧密集分布许多黑色或青色的瘀点、瘀斑，舌色晦暗。","clinical_meaning":"说明体内血液瘀阻已相当严重；若再与舌尖偏或舌下静脉怒张合并出现，则提示病情极重（p.112-113, p.116）。","differential_tip":"先排除抗生素或含化学添加剂酸菜引起的假性黑苔（p.39）及妊娠期生理性血瘀舌象（p.119）；若伴胸闷心痛需高度警惕心脏瘀血（p.123-124）。","action_principle":"尽快请中医定性并排查心脑血管瘀阻隐患，按部位辨证化瘀或采用药汁泡脚通络，单纯心脏瘀血无湿苔者可用三七粉配西洋参粉调护（孕妇忌用）。","remedy_ids":["rem_sanqi_xiyangshen","rem_region_stasis_decoctions","rem_yaotui_hanshi_footbath"],"page":113},{"id":"sign_stasis_sublingual_veins","title":"舌下两条静脉又黑又粗且向四周分叉","constitution_ids":["blood_stasis"],"zone_ids":["zone_sublingual"],"fig_id":"fig_p114","risk_level":"warning","alert_tags":["重度血瘀","舌下络脉怒张"],"visual_features":"张嘴以舌尖舔上嘴唇时，看到舌下两条静脉直径超过2毫米，颜色又黑又粗，并向四周怒张分叉（正常应为淡蓝色、直径不超过2毫米）。","clinical_meaning":"直接反映全身静脉回流与气血运行受阻，说明体内瘀血非常严重；当舌面苔满看不清瘀斑时，抬舌查舌下静脉可锁定隐匿血瘀（p.113-114, p.117）。","differential_tip":"以淡蓝色、直径≤2毫米、无粗乱分叉为正常基线（p.113）；孕妇出现舌瘀指征属气血凝聚育胎正常现象，严禁活血化瘀（p.119）。","action_principle":"结合定处夜痛、腹诊痛点等全身指征请中医辨证，通过泡脚或分部位汤方疏通经络血脉（孕妇忌用）。","remedy_ids":["rem_region_stasis_decoctions","rem_sanqi_xiyangshen","rem_yaotui_hanshi_footbath"],"page":114},{"id":"sign_stasis_deviated_tip","title":"非生理性舌尖偏斜（同侧脑血管堵塞早期预警）","constitution_ids":["blood_stasis"],"zone_ids":["zone_tip","zone_whole"],"fig_id":"fig_p115","risk_level":"high_alert","alert_tags":["脑梗前兆","高危预警"],"visual_features":"自然伸舌时舌尖不朝正前方，而是明显偏向左侧或右侧（须对比往常舌象，确认以前正常、近期新发偏斜）。","clinical_meaning":"排除天生舌偏后，舌尖往哪侧偏即说明哪侧头部血液或经络有堵塞（左偏多伴左头疼，右偏多伴右头疼），常比腔隙性脑梗塞等脑血管病症状提前三年甚至更久出现，许多患者当下毫无症状；偶见天天打高尔夫等长期单侧用力运动致两侧经络气血压力不均（p.114-116）。","differential_tip":"首要通过动态观舌排除“舌尖天生偏斜”的生理情况（p.114）；老人脑血管敏感易堵，一旦舌头方向改变，或舌尖偏与瘀斑、瘀点、舌下静脉怒张合见，提示病情极重（p.116）。","action_principle":"一旦发现原本正常的舌尖变偏（尤其老年人），立即前往医院检查脑血管排查脑梗隐患，并在中医指导下及早活血通络预防发作（孕妇忌用化瘀药）。","remedy_ids":["rem_region_stasis_decoctions","rem_sanqi_xiyangshen"],"page":115},{"id":"sign_stasis_with_damp","title":"舌质发青偏紫或满苔隐现瘀斑（湿气与瘀血并见）","constitution_ids":["blood_stasis","qi_deficiency"],"zone_ids":["zone_whole","zone_sublingual"],"fig_id":"fig_p117","risk_level":"warning","alert_tags":["湿瘀互结"],"visual_features":"舌质颜色发青或偏紫，或因脾虚水湿重而舌苔铺得较满，白苔下面隐约透露出一点点不明显的瘀斑。","clinical_meaning":"提示脾气虚水湿内停与体内瘀血同时交织存在（气虚无力推血致瘀，脾虚湿困阻碍气血运行，p.108, p.116-117）。","differential_tip":"因满布舌苔易遮掩舌面瘀点，怀疑有瘀血时务必把舌头抬起舔上唇，检查舌下两条静脉是否粗黑分叉以防漏诊（p.117）。","action_principle":"健脾祛湿与活血通络兼顾；因体内痰湿阻碍胃肠吸收口服药，优先采用温经祛湿化瘀方泡脚透皮吸收（心脏瘀血伴厚苔湿重者须先祛湿再化瘀，p.121, p.124）。","remedy_ids":["rem_yaotui_hanshi_footbath","rem_region_stasis_decoctions"],"page":117},{"id":"sign_stasis_female_lip_hair","title":"女性舌现瘀血指征且上唇汗毛浓重","constitution_ids":["blood_stasis"],"zone_ids":["zone_tip","zone_whole"],"fig_id":"fig_p118","risk_level":"warning","alert_tags":["妇科预警"],"visual_features":"女性舌面原本充盈的红点因血液堵在里面慢慢变成黑点等瘀血指征，同时嘴唇上方汗毛明显浓重。","clinical_meaning":"红点转黑点是瘀血正在形成的过程，伴随上唇汗毛浓重说明女性内分泌可能失常，高度提示存在子宫肌瘤、卵巢囊肿等妇科问题，且多与情绪肝气不舒密切相关（p.117-118, p.128）。","differential_tip":"观舌看诊切勿涂口红化妆以免遮盖唇周体征（p.79）；区分经期前后生理性舌尖红点（p.40）与血液瘀堵变暗的黑点（p.118），育龄女性调治前须先排除妊娠（p.119）。","action_principle":"及时赴医院妇科检查子宫与卵巢（排查子宫肌瘤、卵巢囊肿）；调理须结合月经量与情绪状态，气郁致瘀者必须一边疏肝气一边化瘀，配合艾灸、刮痧等外治法（p.117-118, p.127-128）。","remedy_ids":["rem_female_yimu_cycle","rem_region_stasis_decoctions"],"page":118},{"id":"sign_stasis_damp_masked","title":"白苔笼罩紫黑舌质（湿气掩盖瘀血）","constitution_ids":["blood_stasis","qi_deficiency"],"zone_ids":["zone_whole"],"fig_id":"fig_p119","risk_level":"warning","alert_tags":["湿罩血瘀","孕妇禁化瘀"],"visual_features":"舌体底色明显发紫、发黑，外面却被一层白苔笼罩遮盖，表面似普通白苔而极具迷惑性。","clinical_meaning":"说明体内湿气很重并把深层瘀血罩在里面了；但若为孕妇出现瘀血舌象，则属胎儿形成时气血凝聚的正常生理现象（p.118-119）。","differential_tip":"切莫只见外层白苔而单用祛湿药（单纯祛湿效果差，p.118），亦须排除药物或食物染黑假象（p.39）；【特别铁律】千万不要给孕妇看舌象妄断瘀血或用活血化瘀药，否则极易出事（p.119）。","action_principle":"非孕人群必须一边祛湿气、一边清热化瘀同步调治，并善用中药泡脚绕开脾湿吸收障碍（p.118, p.121）；孕妇绝对禁止任何活血化瘀药物与食疗（p.119）。","remedy_ids":["rem_region_stasis_decoctions","rem_yaotui_hanshi_footbath"],"page":119},{"id":"sign_yin_red_thin_coat","title":"舌红苔薄或无苔萎缩（典型阴虚内热）","constitution_ids":["yin_deficiency"],"zone_ids":["zone_whole"],"fig_id":"fig_p137","risk_level":"warning","alert_tags":["阴虚内热","勿误服牛黄解毒丸"],"visual_features":"未患外感的情况下，舌质颜色鲜红，舌苔很薄甚至完全萎缩无苔。","clinical_meaning":"基本可断定为阴虚体质：体内津液被内热耗伤，舌面微生物赖以生存的微环境遭到破坏，导致舌苔萎缩变薄乃至消失（p.137-138）。","differential_tip":"先排除饭后半小时咀嚼充血与芹菜磨苔（p.38）及人为刮舌苔（切忌刮舌苔，p.53-55）；严防将阴虚“虚热”舌红误当外邪“实热”而乱吃牛黄解毒丸（虚热吃苦寒清热药无效，必须滋阴，p.51-52, p.137）。","action_principle":"按“虚则补之”甘寒滋阴降虚火（小儿用七味滋阴水并少吃肉多吃青菜，成人用滋阴猪龙骨汤，肾阴虚伴腰酸盗汗脉快用六味地黄丸），严戒半夜12点后熬夜与辛辣饮食。","remedy_ids":["rem_child_nourish_yin","rem_adult_yin_bone_soup","rem_liuwei_dihuang"],"page":137},{"id":"sign_yin_masked_by_damp","title":"舌质偏红而舌苔不薄（水湿掩盖阴虚）","constitution_ids":["yin_deficiency","qi_deficiency"],"zone_ids":["zone_whole","zone_center"],"fig_id":"fig_p138","risk_level":"warning","alert_tags":["复合体质","厚苔禁直服六味地黄丸"],"visual_features":"舌头底色是红的，但上面覆盖一层并不算薄的舌苔，将底下的红舌质部分盖住。","clinical_meaning":"属于阴虚与脾虚湿气重交织的复合体质（或正处于体质转化过程中），体内水湿掩盖了阴虚本象（p.138）。","differential_tip":"区别于纯阴虚的“舌红苔薄”；切记只要舌苔厚或黄腻、伴胃肠胀闷或大便不成形，说明体内有痰湿/湿热，严禁直接服用六味地黄丸，必须先清掉痰湿（p.138, p.142, p.144）。","action_principle":"遵循“核心调脾胃、根源调情绪”原则先化湿健脾清痰湿，待厚苔退去后再予清润滋阴，日常调畅肝气并戒熬夜辛辣（p.132-133, p.142）。","remedy_ids":["rem_sanren_footbath","rem_wendan_footbath","rem_child_nourish_yin","rem_adult_yin_bone_soup"],"page":138},{"id":"sign_yin_elderly_deep_cracks","title":"老年人舌红伴深裂纹（老年津亏阴虚）","constitution_ids":["yin_deficiency"],"zone_ids":["zone_whole","zone_center"],"fig_id":null,"risk_level":"warning","alert_tags":["老年阴虚"],"visual_features":"舌质颜色很红，舌面上布满许多很深的裂纹，且一吃辛辣食物舌头就有明显不适感。","clinical_meaning":"随年龄增长体内津液消耗过多、所剩无几，形成典型的老年人阴虚体质表现（p.139）。","differential_tip":"与脾胃气虚裂纹舌（p.80，舌中间纵裂明显而舌质不鲜红、无辣食舌痛）区分；老年阴虚者若同时有血瘀，切忌长期单吃温燥的三七粉，以免伤阴致眼睛干痛（p.123, p.139）。","action_principle":"忌食辛辣燥热之品，以成人滋阴猪龙骨汤或六味地黄丸（脾胃弱者配1个砂仁捣碎泡开水冲服防熟地滞腻）缓补津液（p.139, p.141-144）。","remedy_ids":["rem_adult_yin_bone_soup","rem_liuwei_dihuang"],"page":139},{"id":"sign_yin_geographic_tongue","title":"地图舌（舌苔分布不均、成片剥落露红舌质）","constitution_ids":["yin_deficiency"],"zone_ids":["zone_whole","zone_center"],"fig_id":"fig_p139","risk_level":"warning","alert_tags":["地图舌","脾胃阴虚"],"visual_features":"舌苔分布不均，舌面上莫名其妙掉了几块苔，露出底下偏红的舌质，边缘弯弯曲曲形如地图。","clinical_meaning":"绝大多数由阴虚引起（胃阴或脾阴亏虚致局部舌面微生态失养脱苔，尤多见于吃肉过多致脾阴不足的儿童及阴虚成人，p.135-136, p.139）。","differential_tip":"排除芹菜等粗纤维食物局部磨苔（p.38）或人为刷刮舌苔所致剥落（p.54）；若脱苔处舌质惨白无华而非偏红，则属大病后脾胃正气大亏（p.55, p.81）。","action_principle":"禁止刮刷舌苔；儿童用生地薏米石斛沙参麦冬山药莲子肉方调养5～6天并坚持少吃肉多吃青菜半年以上，成人用滋阴猪龙骨汤濡养胃肾之阴（p.136, p.139-141）。","remedy_ids":["rem_child_nourish_yin","rem_adult_yin_bone_soup"],"page":139},{"id":"sign_yin_red_to_pale_shift","title":"舌质由红渐渐转淡白（阴虚转化为血虚）","constitution_ids":["yin_deficiency","blood_deficiency"],"zone_ids":["zone_whole"],"fig_id":null,"risk_level":"warning","alert_tags":["体质转化","阴损及血"],"visual_features":"动态观舌见原本发红的舌头，随时间推移慢慢变成淡白色、少苔（反之若原本淡白舌渐渐变红，则为血虚体质向阴虚体质转化）。","clinical_meaning":"阴虚与血虚互相累及：舌头红以血液充盈为前提，绝大多数阴虚者因阴虚严重进一步耗少血液，最终转化为血虚体质（曾有眼干、手干、手心热，后见舌色转淡白，p.140）。","differential_tip":"结合动态病史区分：既有过往五心烦热、眼干手干史而今舌转淡白少苔者为阴虚转血虚；阳虚舌淡则带白苔、舌体苍老且伴下肢冷、尿清长（p.140, p.144, p.150）。","action_principle":"已由阴虚转化为血虚者，应重点好好养血（血液养足后舌头自会慢慢变红，舌苔也会重新长出来；若反之由淡白渐转红为血虚向阴虚转化，则按阴虚调养，p.140）。","remedy_ids":["rem_danggui_chicken_soup","rem_yulinggao","rem_adult_yin_bone_soup"],"page":140},{"id":"sign_yang_pale_aged","title":"舌质很淡、白苔苍老（轻度水滑 vs 重度口干）","constitution_ids":["yang_deficiency"],"zone_ids":["zone_whole"],"fig_id":"fig_p150","risk_level":"warning","alert_tags":["阳气亏虚"],"visual_features":"舌质颜色很淡（完全不是红色），舌苔发白，整个舌体纹理看上去比较“苍老”；阳虚轻微时舌面唾液偏多呈水滑状，阳虚严重时舌面与口中反见干燥。","clinical_meaning":"反映体内脾肾阳气不足、温煦生发机能减退。轻度阳虚伴体内湿重故舌苔水滑；重度阳虚命门火衰，津液不能蒸腾上承（如同蒸饭火微则锅盖干燥），反致口干口渴（常见于老年夜尿多或部分糖尿病患者）。","differential_tip":"与血虚淡白舌鉴别：阳虚舌淡苔白而偏“苍老”，盛夏仍怕冷怕风；血虚舌淡白而偏“淡嫩”半透明（p.97），夏天天热手即变暖（p.147, 150）。重度阳虚口干切忌误判为实热而用寒凉清火药。","action_principle":"温补脾肾阳气：肾阳虚畏寒、老人起夜五六次或涉冷水脚跟痛者服金匮肾气丸（受凉配热水泡脚）；脾阳虚沾凉食即胃疼腹泻者服附子理中丸/理中丸。","remedy_ids":["rem_jinkui_shenqi","rem_fuzi_lizhong"],"page":150},{"id":"sign_phlegm_sticky_fluid","title":"舌面水液黏腻伴舌中沟明显","constitution_ids":["phlegm_dampness"],"zone_ids":["zone_whole","zone_center"],"fig_id":"fig_p157","risk_level":"high_alert","alert_tags":["三高预警"],"visual_features":"舌头表面覆盖一层黏腻的水液，看上去湿黏不干爽，同时舌头正中间的纵沟非常明显。","clinical_meaning":"提示脾虚水湿久留已凝炼成黏稠“痰湿”，体内水液与脂糖代谢严重受阻；书中指出有此舌象者去医院检查基本都已有“三高”（高血压、高血脂、高血糖）。","differential_tip":"不同于轻度阳虚舌淡苍老的清稀水滑苔（p.150-151），此象水液黏稠不爽，属肥甘应酬或肝郁困脾导致的痰湿高危指征。","action_principle":"尽快赴医院检查血压、血脂、血糖；严禁盲目进补，用罗氏去生姜温胆汤泡脚祛痰，并改吃萝卜白菜粗茶淡饭、坚持运动“以清为补”。","remedy_ids":["rem_wendan_footbath","rem_phlegm_diet_exercise"],"page":157},{"id":"sign_phlegm_frost_thick","title":"舌苔厚腻白如霜（或初黄腻、后半部厚腻裂纹）","constitution_ids":["phlegm_dampness"],"zone_ids":["zone_whole","zone_root"],"fig_id":"fig_p158","risk_level":"high_alert","alert_tags":["三高预警"],"visual_features":"舌苔极其厚腻，而且白得像铺了一层霜；或微黄初腻（伴两腮发红），或舌后半部集中厚腻苔并伴裂纹。","clinical_meaning":"表明体内不仅有湿气，更有重度凝结之痰湿，只要去医院检查，毫无疑问往往“三高”俱全；若微黄伴两腮红则已开始化热。","differential_tip":"区别于喝牛奶或暂时积食后浮在表面、似能刮掉的虚浮无根苔（p.79-80）；白霜厚腻苔扎实顽固，代表长期痰浊内阻。","action_principle":"立即排查“三高”指标；先用去生姜温胆汤泡脚十副八副宣通化痰，严格戒除肥甘夜宵，坚持素食清淡饮食与规律运动。","remedy_ids":["rem_wendan_footbath","rem_phlegm_diet_exercise"],"page":158},{"id":"sign_phlegm_red_heat_excess","title":"舌苔厚腻渐黄、舌质发红（营养过剩痰湿化热）","constitution_ids":["phlegm_dampness"],"zone_ids":["zone_whole"],"fig_id":"fig_p159","risk_level":"warning","alert_tags":["禁补警示"],"visual_features":"舌苔白厚且十分黏腻，甚至已开始发黄，同时舌苔底下的舌质明显发红（常伴红点）。","clinical_meaning":"舌苔与舌质合看，说明体内营养严重过剩、无法化热，内热与重湿交结使水液炼成痰浊并形成瘀滞状态，易引发严重失调。","differential_tip":"此类人常诉整天没力气、犯困，极易被不看舌象的医生误当“肾虚”进补，结果越补越热、症状丛生（p.159）；亦绝非舌红无苔的阴虚证（p.137）。","action_principle":"严禁吃任何补品或补肾药！必须往下清泄排痰，吃萝卜白菜粗茶淡饭（以清为补），并用去生姜温胆汤（热重竹茹配至9克）泡脚清热化痰；口服须请当地中医加减。","remedy_ids":["rem_wendan_footbath","rem_phlegm_diet_exercise"],"page":159},{"id":"sign_stagnation_pointed_red","title":"舌头伸出尖尖、舌尖与舌边发红","constitution_ids":["qi_stagnation"],"zone_ids":["zone_tip","zone_left","zone_right"],"fig_id":"fig_p176","risk_level":"warning","alert_tags":["肝郁化火"],"visual_features":"舌头伸出来不呈正常椭圆形，而是明显尖尖的锥形，且舌尖与舌两侧部分颜色发红。","clinical_meaning":"典型肝气郁结、心肝有火之象（舌尖对应心，舌两边对应肝胆），多见于长期压力焦虑、爱生气或隐忍郁怒的“老好人”；还需提防木火刑金伤肺及女性甲状腺结节、乳腺增生。","differential_tip":"尖舌属于数年焦虑或半年以上重大压力塑造的器质性改变（儿童可由家长焦虑传染所致，新生儿尖舌亦需警惕，p.170-171, 180）；服药后症状虽减但尖舌未消者说明郁根未除（p.43）。","action_principle":"以疏肝调神、清泻心肝郁火为核心：伴失眠用柴胡加龙骨牡蛎汤加味泡脚，伴血压波动用平肝降压泡脚方，伴结节/乳腺增生予疏肝散结调理，并彻底放宽心态。","remedy_ids":["rem_chaihu_longgu_muli_insomnia","rem_liver_hypertension_footbath","rem_thyroid_breast_footbath","rem_tap_lung_meridian"],"page":176},{"id":"sign_stagnation_pointed_to_fat","title":"舌头初伸尖、再伸变胖圆","constitution_ids":["qi_stagnation","qi_deficiency"],"zone_ids":["zone_whole","zone_left","zone_right"],"fig_id":"fig_p177","risk_level":"warning","alert_tags":["肝郁夹湿"],"visual_features":"舌头刚伸出来的一刻呈尖尖的形状，继续伸展出来后却变成胖胖、圆圆的舌体。","clinical_meaning":"典型肝气不舒合并体内水湿很重：内心紧张焦虑本使舌尖，但气郁体内无力推动水湿运行，水湿停聚在舌体上使其肿大变胖。","differential_tip":"见到胖圆舌切勿一律只当单纯脾虚湿重而忽略情绪问题；此类人经祛湿调理后，水肿消退，原本隐藏的尖舌形状往往会重新显露（p.177-178）。","action_principle":"调理时要理气、祛湿、养血并进（祛除水湿后原本隐藏的尖舌形状可能会显露出来），同时兼顾疏肝调神与实脾（p.177-178, 180）。","remedy_ids":["rem_sanren_footbath","rem_danggui_chicken_soup","rem_shugan_huangqi_jianzhong","rem_chaihu_longgu_muli_insomnia"],"page":177},{"id":"sign_stagnation_pointed_white_coat","title":"舌头尖尖、舌边舌尖红而上覆白苔","constitution_ids":["qi_stagnation","qi_deficiency"],"zone_ids":["zone_tip","zone_left","zone_right","zone_center"],"fig_id":"fig_p178","risk_level":"warning","alert_tags":["少阳郁湿"],"visual_features":"舌形保持尖尖的状态，舌边与舌尖发红，舌面上铺有一层明显甚至铺满的白苔（里红表白）。","clinical_meaning":"对应张仲景《伤寒论》少阳证“舌上白苔”，提示两种可能：一是过去曾肝气不舒，遗留的脾弱水湿状态至今未调整过来；二是当下正处于肝气郁结、气滞水停状态。","differential_tip":"不同于阳虚或外寒的淡白舌白苔（舌肉不红且不尖，p.150）；本象白苔下舌质红、边尖红且舌体依然是尖的，本质仍是典型肝气郁结夹湿。","action_principle":"疏肝理气与祛除水湿并行：先清解停聚的水湿并调畅肝脾气机，伴胃痛反酸用舒肝和胃丸配黄芪建中汤，伴失眠烦闷用柴胡加龙骨牡蛎汤加味泡脚。","remedy_ids":["rem_sanren_footbath","rem_shugan_huangqi_jianzhong","rem_chaihu_longgu_muli_insomnia"],"page":178},{"id":"sign_stagnation_heart_fire_tip","title":"尖舌前部无苔、舌尖变红（心火偏旺）","constitution_ids":["qi_stagnation"],"zone_ids":["zone_tip","zone_front"],"fig_id":"fig_p179","risk_level":"warning","alert_tags":["焦虑心火"],"visual_features":"舌体呈尖形，舌头前部没有舌苔覆盖，舌尖部位明显发红。","clinical_meaning":"说明近期精神压力较大、工作焦虑或家中遇到烦心麻烦事，肝郁木生火引起心火偏旺；若伴清晨三四点早醒则需提防木火刑金伤及肺经。","differential_tip":"必须先排除女性月经期或月经前后1～2天的生理性舌尖红假象（p.40），并结合症状鉴别下焦妇科或男性前列腺湿热引起的舌尖红（p.75）。","action_principle":"暂时压力心火可喝灯心竹叶汤（灯心草、竹叶各6克，保健各3克煮水代茶，p.189-190）清心泻火；若已失眠则用柴胡加龙骨牡蛎汤加味泡脚，伴早醒者敲打胳膊内侧肺经痛点。","remedy_ids":["rem_dengxin_zhuye","rem_chaihu_longgu_muli_insomnia","rem_tap_lung_meridian"],"page":179}],"compare_pairs":[{"id":"cmp_full_coat_vs_pale_body","title":"舌苔满布 vs 舌质淡白","item_a":{"label":"舌苔满布（水湿困脾）","fig_id":"fig_p071","key_feature":"白色舌苔颗粒过度生长，一直铺满到整个舌头边缘，一点舌肉底色都不露出来。","meaning":"体内脾虚水湿很重（如遇阴雨大雾天可骤然铺满），需先祛水湿并紧接着补脾。","page":71},"item_b":{"label":"舌质淡白（血虚或寒证阳虚）","fig_id":"fig_p072","key_feature":"舌头边缘并没有被舌苔颗粒完全覆盖，露出的舌体肌肉本身呈淡白色，因与薄白苔同色而易看混。","meaning":"代表体内血虚，或受外界寒邪侵袭、自身阳气不足（体寒）。","page":72},"distinguishing_rule":"紧盯舌头边上一圈有无“舌苔颗粒”覆盖：颗粒把舌边全铺上的叫舌苔满布（主湿重）；舌边未被舌苔覆盖、是舌肉本身发白的叫舌质淡白（主血虚或外寒/阳虚）（p.71-72）。"},{"id":"cmp_blood_tender_vs_yang_aged","title":"血虚淡嫩舌 vs 阳虚苍老舌","item_a":{"label":"血虚淡嫩舌","fig_id":"fig_p097","key_feature":"舌苔未铺满，露出的舌质颜色极浅甚至带一点半透明感，质地显得娇嫩（淡嫩）。","meaning":"舌黏膜毛细血管与舌肌气血充盈差，属典型血虚体质，伴蹲下1分钟站起头晕、神智疲劳、夏热冬凉。","page":97},"item_b":{"label":"阳虚苍老舌","fig_id":"fig_p150","key_feature":"舌质很淡（不是红色），舌苔发白，整个舌体看上去比较“苍老”，轻者水滑多津、重者反干。","meaning":"脾肾阳气不足、温煦生发机能衰退，伴腹部下肢畏寒、夜尿频多清长、沾凉胃痛腹泻。","page":150},"distinguishing_rule":"一看舌体老嫩：血虚舌淡白而偏“淡嫩”半透明，阳虚舌苔白而偏“苍老”（p.97, 150）；二看夏热反应与功能：血虚者夏天手就变热且偏神智及辨色力衰退，阳虚者大夏天仍怕冷怕风且整体生命生发功能下降（p.95, 147）。"},{"id":"cmp_qi_swollen_vs_stagnation_fat","title":"气虚胖大齿痕舌 vs 肝郁初尖变胖圆舌","item_a":{"label":"气虚胖大齿痕舌","fig_id":"fig_p068","key_feature":"舌体始终胖大肿胀，受两侧牙齿挤压形成明显齿痕，伸舌瞬间无锥形尖舌变化。","meaning":"脾肾肺正气不足、贪凉少动致水湿停聚，伴神疲乏力、少言懒语、食后腹胀、大便不成形。","page":68},"item_b":{"label":"肝郁初尖变胖圆舌","fig_id":"fig_p177","key_feature":"刚伸出舌头时呈尖尖的形状，再继续伸展放松却变成胖胖、圆圆的舌体（或伴两条唾液线 p.78）。","meaning":"根源是肝气郁结、焦虑气滞，无力推动水湿运行致水湿积聚舌体；祛湿后常会重新显出尖舌原形。","page":177},"distinguishing_rule":"看伸舌瞬间的动态塑形并合参情绪：始终胖大有齿痕、懒言乏力者为单纯气虚湿重（祛湿后马上补脾，p.68, 83）；初伸尖而再伸变胖圆、伴焦虑叹气失眠者实为肝郁致湿，须理气疏肝、祛湿、养血并进（p.177-178）。"},{"id":"cmp_stagnation_pure_vs_white_coat","title":"肝郁纯尖红舌 vs 尖舌夹湿白苔","item_a":{"label":"肝郁纯尖红舌","fig_id":"fig_p176","key_feature":"舌头伸出呈明显锥状尖形，舌尖与舌两边发红，舌面无厚白苔遮盖。","meaning":"典型肝气郁结化火、心肝火旺（舌尖应心、两边应肝胆），常见于易怒、长期焦虑或隐忍郁怒之人。","page":176},"item_b":{"label":"尖舌边尖红覆白苔","fig_id":"fig_p178","key_feature":"舌形依然尖尖，舌边与舌尖发红，但舌面上铺有一层明显白苔（少阳证“舌上白苔”，里红表白）。","meaning":"提示过去肝气不舒遗留脾弱湿停未复，或当前正处肝气郁结、气滞不能运水而夹湿。","page":178},"distinguishing_rule":"同属长期情绪压力塑造的器质性尖舌，看舌面有无白苔铺覆：纯尖红者重在疏肝清泻心肝之火（p.176）；尖舌覆白苔者属肝郁气滞合并水湿停聚，须疏肝和解少阳兼健脾祛湿（p.178-179）。"},{"id":"cmp_yin_thin_vs_damp_masked","title":"阴虚舌红苔薄 vs 阴虚被水湿掩盖","item_a":{"label":"典型阴虚舌红苔薄","fig_id":"fig_p137","key_feature":"无外感发热，舌质明显发红，舌苔很薄甚至萎缩无苔（或成块剥落呈地图舌 p.139）。","meaning":"津液亏虚、“阴虚生内热”，伴五心烦热、盗汗、眼干便干、脉搏偏快，可直接滋阴调养。","page":137},"item_b":{"label":"阴虚被水湿掩盖","fig_id":"fig_p138","key_feature":"舌质底色发红，但上面覆盖一层并不薄的舌苔，把底下的红掩盖了一部分。","meaning":"阴虚内热合并水湿重的复合体质（或正在转化中），湿苔遮蔽了部分阴虚真相。","page":138},"distinguishing_rule":"舌质红伴阴虚症状时务必先看苔厚薄：舌红苔薄无湿者可直接滋阴（如煲滋阴汤或服六味地黄丸，p.137, 141-142）；若舌苔偏厚有水湿遮盖，禁直接单服熟地等滞腻滋阴药，必须先清祛痰湿再滋阴（p.138, 142, 144）。"},{"id":"cmp_excess_heat_vs_yin_deficiency_heat","title":"实热外邪红舌 vs 阴虚虚热红舌","item_a":{"label":"外邪或积滞实热红舌","fig_id":"fig_p048","key_feature":"舌质发红乃至深红（绛色），常伴舌苔变黄、黄腻或焦黑（p.51, 56），多伴急性外感或肉食积滞。","meaning":"温热外邪入侵（发烧、咽喉肿痛、便秘）或肉食化湿生痰蕴热，属邪气“有余”之实热。","page":48},"item_b":{"label":"阴虚内生虚热红舌","fig_id":"fig_p137","key_feature":"无外感温病，舌质发红而舌苔很薄或萎缩消失。","meaning":"体内津液血液濡润不足（如发动机缺润滑油干转生热），属阴液“不足”之虚热。","page":137},"distinguishing_rule":"实热属外邪或积滞“有余”（伴黄腻苔或急性感染咽痛高热），当清热解毒；虚热属津液“不足”（舌红少苔伴盗汗五心烦热），当用生地、沙参、麦冬等滋阴（“虚则补之”）。阴虚虚热若误吃牛黄解毒丸、黄连等苦寒清热药不仅无效且更伤正气（p.51-52, 137）。"},{"id":"cmp_phlegm_sticky_vs_heat_excess","title":"痰湿黏腻三高预警 vs 痰湿营养过剩化热","item_a":{"label":"痰湿水液黏腻舌（三高预警）","fig_id":"fig_p157","key_feature":"舌面覆盖黏腻不干爽的水液，舌中纵沟明显，舌质尚未显著变红。","meaning":"脾虚水湿凝结成痰湿，代谢严重受阻，去医院体检基本都已有高血压、高血脂、高血糖。","page":157},"item_b":{"label":"痰湿厚腻舌红化热（禁补警示）","fig_id":"fig_p159","key_feature":"舌苔白厚黏腻甚至开始发黄，且底下舌质明显发红（常伴红点）。","meaning":"体内营养严重过剩、湿热交结成痰瘀状态，虽常觉乏力犯困但严禁进补，误补肾药必越补越热。","page":159},"distinguishing_rule":"二者皆属湿聚成痰、严禁进补且须排查三高，区别在于化热程度：水液黏腻不红者重在化痰祛湿（p.157）；舌质变红、苔厚转黄有红点者说明痰已化热，用温胆汤泡脚必须去掉温性生姜，热重时竹茹加至9克，配合萝卜白菜运动“以清为补”（p.159-162）。"},{"id":"cmp_stasis_surface_vs_damp_masked","title":"外露瘀点形成舌 vs 白苔湿罩瘀血舌","item_a":{"label":"外露瘀点瘀斑舌","fig_id":"fig_p112","key_feature":"舌面无厚腻白苔遮盖，舌尖或舌两侧直接可见青黑色瘀点、瘀斑（毛细血管瘀堵）。","meaning":"体内瘀血正在形成或已存在（须先排除孕妇生理性血瘀假象 p.119），单纯血瘀可直接活血化瘀。","page":112},"item_b":{"label":"白苔笼罩紫黑舌（湿罩瘀血）","fig_id":"fig_p119","key_feature":"舌体发紫、发黑，但外面被一层白苔笼罩掩盖，极具迷惑性。","meaning":"深重水湿把内部严重血瘀罩在里面（苔满隐透瘀斑时还应翘舌查舌下粗黑静脉 p.117）。","page":119},"distinguishing_rule":"看青紫瘀斑外有无白腻湿苔笼罩：单纯无湿的血瘀可直接对证化瘀（如心脏血瘀服三七粉配西洋参粉 p.124）；被白苔笼罩的“湿罩瘀血”若单祛湿或单化瘀效果均差，必须先祛湿或一边祛湿一边清热化瘀，且脾湿难吸药者泡脚优于喝药（p.118-119, 121, 124）。"}],"remedies":[{"id":"rem_dengxin_zhuye","name":"灯心竹叶汤","method_type":"tea","constitution_ids":["qi_deficiency","qi_stagnation"],"indications":["脾虚湿热、热聚上焦，舌有齿痕、舌苔铺满微黄，蕈状乳头偏大且红点集中在舌尖到舌中部（pp.76-77）。","儿童舌尖至舌中部出现明显红点，属上焦热盛者（p.77）。","近期压力很大、情绪不好（肝气不舒生心火），尖舌前部无苔、舌尖变红等暂时性心火偏旺者（pp.179, 189-190）。"],"ingredients":[{"name":"淡竹叶（竹叶）","amount":"3～6克（脾虚湿热上焦红点及日常保健用3克；压力大、情绪不好泻心火用6克）","note":"往下泻心火，心火泻掉则肝火亦随之减轻（第76-77、189-190页）"},{"name":"灯心草","amount":"3～6克（脾虚湿热上焦红点及日常保健用3克；压力大、情绪不好泻心火用6克）","note":"往下泻心火，心火泻掉则肝火亦随之减轻（第76-77、189-190页）"}],"preparation_and_usage":"①脾虚湿热上焦红点（第77页）：淡竹叶3克、灯心草3克泡水代茶饮，每天一副，服用三五天，舌尖的红点变淡即可。②压力大、情绪不好泻心火（第189-190页）：灯心草6克、竹叶6克（若用于日常保健各3克即可），入水稍微煮一煮代茶饮，煮水清香，对疏解情绪有益。","modifications":["若体内湿气重，也要配用莲子心，帮助在泻心火的同时把体内的湿气除去（见第76页）。","若满舌红点（芒刺）明显且面色发红，属过量饮白酒、吃肉及各种营养物过多所致体内有热，须立刻停止过度应酬与饮酒，改吃五谷杂粮、清淡蔬菜，或采用轻断食、喝点酵素清减体内淤积（见第77页）。","若情绪失调已由暂时心火发展为真正失眠，须改用“柴胡加龙骨牡蛎汤”加味泡脚方解决（见第190页）。"],"contraindications":["服用三五天待舌尖红点变淡即可停服（见第77页）；仍须辨证使用并遵后记筛查原则（见第191-192页）。","用法边界（见第189-190页）：本方仅用于在心火暂时出现以后泻一泻以疏解情绪；若真的有病、已经失眠了，则需要用“柴胡加龙骨牡蛎汤”加味来解决，勿单靠本方延误。","小儿防误治警示：若在孩子舌头上看到图中这种红点，说明孩子体内的上焦热很严重，调理时要以清热为主，而不是滋阴的问题（见第77页）。"],"mechanism":"源自清朝宫廷御医给后宫嫔妃开的泻火代茶饮方；竹叶、灯心草均主往下泻心火，既能消退脾虚湿热集中于上焦所致蕈状乳头偏大红点（pp.76-77），又可在近期压力大、情绪不好时借泻心火以减轻肝火、疏解烦闷（pp.189-190）。","fig_id":null,"page":77},{"id":"rem_shengmaiya_tea","name":"生麦芽养胃茶（附黄芪山药生麦芽代茶饮）","method_type":"tea","constitution_ids":["qi_deficiency"],"indications":["大病之后脾胃受损、舌苔退去，或平时饮食不当、天天喝大酒伤损胃气，致舌无苔或舌苔极薄、全舌发白者（pp.81-83）。","脾胃气虚无力生苔（如舌中间裂纹明显）需升发胃气者（pp.80, 82-83）。"],"ingredients":[{"name":"生麦芽","amount":"30～60克","note":"单味主方泡茶用（第82页）；必须用生麦芽升发胃气，严禁误用炒麦芽（第83页）"},{"name":"生黄芪（附方选配）","amount":"3克","note":"第83页复方代茶饮：与怀山药6克、生麦芽9克同煮水代茶饮，坚持喝几周"},{"name":"怀山药（附方选配）","amount":"6克","note":"第83页复方代茶饮：与生黄芪3克、生麦芽9克同煮水代茶饮"},{"name":"生麦芽（附方选配）","amount":"9克","note":"第83页复方代茶饮：与生黄芪3克、怀山药6克同煮水代茶饮"}],"preparation_and_usage":"取生麦芽30～60克直接泡茶喝（胃气不足者不要一次猛喝太多白水）；老中医治重病无苔者常嘱喝此茶赶快生发胃气，一直喝到舌苔重新生发出来为止（见第82-83页）。另可采用复方代茶饮：生黄芪3克、怀山药6克、生麦芽9克煮水代茶饮，坚持喝几周（见第83页）。","modifications":["复方升发胃气代茶饮（第83页）：用生黄芪3克、怀山药6克、生麦芽9克煮水代茶饮，坚持喝几周，对胃气升发甚有好处。"],"contraindications":["严禁误用炒麦芽：一定要用生麦芽！生麦芽是把气往上升、具有生发胃气功能的；炒麦芽则是把气往下降的，误用会进一步挫伤胃气（见第83页）。","伤胃致胃气虚者不宜大量猛饮白水，长期喝大酒者必须同步戒除过量饮酒（见第82页）。"],"mechanism":"顺应脾胃升发之性，以生麦芽（或配少量生黄芪、怀山药）轻灵升发受创之胃气，使脾胃生机复振、舌苔复生（pp.82-83）。","fig_id":null,"page":82},{"id":"rem_sanren_footbath","name":"祛湿“三仁汤”泡脚方","method_type":"foot_bath","constitution_ids":["qi_deficiency"],"indications":["脾虚湿气重，舌有明显齿痕、舌苔满布水湿、舌胖大或伴唾液线，周身困重乏力（pp.66, 68, 71, 78, 83-84）。","湿气蒙蔽内热（舌苔满布掩盖舌尖或肝胆微红）需先祛湿以显真象者（pp.74-75, 83-84）。"],"ingredients":[{"name":"杏仁","amount":"6克","note":"后下（关火前5～10分钟放入锅里，关火后闷一会儿）"},{"name":"白蔻仁","amount":"6克","note":"后下（关火前5～10分钟放入锅里，关火后闷一会儿）"},{"name":"薏苡仁","amount":"30克","note":"正常煮20～30分钟，祛除体内湿气"},{"name":"茯苓","amount":"20克","note":"正常煮20～30分钟，祛除体内湿气"},{"name":"白术","amount":"6～9克","note":"正常煮20～30分钟，祛除体内湿气"},{"name":"猪苓","amount":"6～9克","note":"正常煮20～30分钟，泻脾肾之湿（原书括注）"},{"name":"法半夏","amount":"3克","note":"正常煮20～30分钟，祛除体内湿气"},{"name":"甘草","amount":"6克","note":"正常煮20～30分钟，祛除体内湿气"}],"preparation_and_usage":"未标“后下”的药材先正常煮20～30分钟，标“后下”的杏仁6克、白蔻仁6克在关火前5～10分钟放进锅里，关火后闷一会儿滤出药汁。将药汁分成两份，早晚兑入温水泡脚，每次20分钟，水温不要太热，水淹过脚面即可；湿气明显者一般泡五六副即可微出黏汗而身轻。若经医生指导口服，大人喝一两天可出汗祛湿，小孩口服量为原方药量的1/3～1/4（见第83-84页）。","modifications":["体内有寒（凉）或阳气不足者，配桂枝3克；若有热则不加桂枝（见第83-84页）。","体内有热者，配点竹叶（桂枝和竹叶这两味药是备用的，视体内寒热情况添加）（见第83-84页）。","祛湿后必补脾：湿气去掉以后必须马上补脾（如接服怀山药薏苡仁芡实小米粥），并可在湿清气血运行加快后再锻炼身体（见第83-85页）。"],"contraindications":["主张外用泡脚为主：若舌苔非常厚腻之人确需口服，务必请当地医生帮助分析体质并随证具体加减（见第84页）。","有热者不加桂枝（见第83页）；泡脚水温不要太热，水淹过脚面即可（见第83页）。","痰湿未去时不宜单靠天天锻炼硬练，以免因气血凝滞不能正常流通而出问题（见第84页）。"],"mechanism":"方中猪苓泻脾肾之湿，其余诸药药性基本平和，皆用于祛除人体内湿气（寒热视证备配桂枝或竹叶）；泡脚后身体微出黏汗，湿气渐除、气血运行加快（pp.83-84）。","fig_id":null,"page":83},{"id":"rem_yiyiren_chixiaodou","name":"气虚春夏季除湿食疗方（薏苡仁赤小豆饮）","method_type":"tea","constitution_ids":["qi_deficiency"],"indications":["气虚体质者在春夏季节湿热困阻，或素属湿热体质见舌苔满布微黄、体内湿重者（pp.84-85）。"],"ingredients":[{"name":"薏苡仁","amount":"30克","note":"一天的量，有些凉性（第84页）"},{"name":"赤小豆","amount":"30克","note":"一天的量，有些凉性（第84页）"},{"name":"冰糖","amount":"适量","note":"熬水时放入（第84页）"}],"preparation_and_usage":"取薏苡仁30克、赤小豆30克熬水，放入冰糖（此为一天的量），代茶饮（见第84页）。","modifications":["素属湿热体质的人，在夏天以外的其他季节也可以使用；湿气去掉以后马上要补脾（见第83-84页）。"],"contraindications":["天气冷的时候最好不用：因薏苡仁和赤小豆都有些凉性，适合夏天湿热时或湿热体质者使用，天冷时应改用温热辛香方法祛湿（见第84-85页）。"],"mechanism":"薏苡仁与赤小豆均带凉性，熬水代茶饮适合夏季湿热气候或湿热体质之人清利体内水湿（pp.84-85）。","fig_id":null,"page":84},{"id":"rem_autumn_winter_spice_footbath","name":"气虚秋冬季除湿食疗与川椒泡脚方","method_type":"diet_therapy","constitution_ids":["qi_deficiency"],"indications":["气虚体质者在秋冬季天气寒冷时除湿暖胃、温阳燥湿（p.85）。"],"ingredients":[{"name":"白蔻仁","amount":"少许（做菜调料量）","note":"做菜稍放，辛香调料燥湿暖胃（第85页）"},{"name":"砂仁","amount":"少许（做菜调料量）","note":"做菜稍放，辛香调料燥湿暖胃（第85页）"},{"name":"花椒","amount":"少许（做菜调料量）","note":"做菜稍放，辛香调料燥湿暖胃（第85页）"},{"name":"川椒","amount":"十几粒","note":"每晚熬水泡脚外用，燥湿温阳（第85页）"}],"preparation_and_usage":"在秋冬季天气冷时，做菜稍放白蔻仁、砂仁、花椒等辛香调料燥湿暖胃；也可以每晚用十几粒川椒熬水泡脚，燥湿温阳（见第85页）。","modifications":["天气寒冷时替代凉性的薏苡仁赤小豆祛湿方；祛湿后马上配合山药薏苡仁芡实小米粥补脾（见第83、85页）。"],"contraindications":["未单列禁忌，专适天气冷时替代凉性祛湿方使用，仍须辨证使用并遵后记筛查原则（见第85、191-192页）。"],"mechanism":"天气寒冷时采用温热祛湿法，借白蔻仁、砂仁、花椒等辛香调料燥湿暖胃，配合川椒水泡脚燥湿温阳（p.85）。","fig_id":null,"page":85},{"id":"rem_shanyao_yiyiren_qianshi","name":"气虚经典补脾方（山药薏苡仁芡实小米粥）","method_type":"diet_therapy","constitution_ids":["qi_deficiency"],"indications":["气虚体质脾胃薄弱，脸色没光泽、体力差神疲乏力、怕冷易感冒、吃东西易腹胀、大便不成形，舌有齿痕、舌中裂纹或舌体胖大（pp.66-68, 80-81, 85, 193-194）。","体内有湿者祛湿之后马上补脾，防止过三五天水湿复来（pp.65, 83, 85）。"],"ingredients":[{"name":"怀山药","amount":"90克","note":"与余药共研成粉末，补脾（第85、87页）"},{"name":"薏苡仁","amount":"150克","note":"与余药共研成粉末，祛除湿气（第85、87页）"},{"name":"芡实","amount":"30克","note":"与余药共研成粉末，收敛，补脾又补肾（第85、87页）"},{"name":"小米","amount":"适量","note":"每天配一调羹药粉同熬粥（第85页）"}],"preparation_and_usage":"将怀山药90克、薏苡仁150克、芡实30克研成粉末（可以请药店代研），每天一调羹，与小米熬粥，坚持吃半个月到一个月（见第85页、第194页）。","modifications":["体内水湿重者先祛湿，湿气去掉以后马上接服本方补脾（见第65、83、85页）。"],"contraindications":["调养期间切忌早起喝凉白开伤阳气、喝茶过多困脾湿及喝冰镇饮料伤脾胃（见第85-86页）；原书未单列特殊人群禁忌，仍须辨证使用并遵后记筛查原则（见第191-192页）。"],"mechanism":"山药补脾，薏苡仁祛除困脾湿气，芡实收敛而补脾又补肾，合小米熬粥常服以补足脾土，落实“脾主统水”与“土生金”（pp.64-65, 85, 87）。","fig_id":null,"page":85},{"id":"rem_buzhong_bazhen","name":"补脾金方：补中益气丸与清宫“八珍糕”","method_type":"diet_therapy","constitution_ids":["qi_deficiency"],"indications":["气虚体质正气不足、脾胃虚弱、神疲乏力、创面久溃难敛或中老年人日常健脾益寿保养（pp.86-88）。"],"ingredients":[{"name":"人参（或党参）","amount":"二钱","note":"乾隆四十四年御旨八珍糕方用量；补脾阳，乾隆约50岁前原用党参，50岁后改用人参"},{"name":"茯苓","amount":"二两","note":"祛湿健脾，使湿去而脾气得生"},{"name":"山药","amount":"二两","note":"补脾益气"},{"name":"白扁豆（扁豆）","amount":"二两","note":"补脾兼能止泻；若无腹泻症状可将白扁豆去掉"},{"name":"炒薏米","amount":"二两","note":"御旨注明“薏米二两（炒）”，祛湿健脾"},{"name":"芡米（芡实）","amount":"二两","note":"收敛固摄，补脾又补肾"},{"name":"建莲肉（莲子肉）","amount":"二两","note":"御旨注明“建莲二两（肉）”，补脾养心"},{"name":"粳米面","amount":"四两","note":"乾隆四十四年御旨碾极细面蒸糕配料（第88页）"},{"name":"糯米面","amount":"四两","note":"乾隆四十四年御旨碾极细面蒸糕配料（第88页）"},{"name":"白糖","amount":"八两","note":"乾隆四十四年御旨合匀蒸糕配料（第88页）"},{"name":"补中益气丸（可选中成药）","amount":"按药品说明辨证服用","note":"专重补脾阳，兼有养心安神作用（见第87页）"}],"preparation_and_usage":"①补中益气丸：偏脾阳不足者按中成药说明服用以补脾阳、益中气（见第86-87页）。②八珍糕（源自明代外科医家陈实功创方，原方结构含参、白术、山药、莲子肉、白扁豆、薏米、茯苓、芡实；清宫乾隆四十四年御旨改进蒸糕方）：将人参二钱（50岁前可用党参）、茯苓二两、山药二两、扁豆二两、炒薏米二两、芡米二两、建莲肉二两与粳米面四两、糯米面四两共碾为极细面，加白糖八两合匀蒸糕，晾凉后每日随茶水食用（见第87-88页）。","modifications":["有无腹泻加减：白扁豆兼具补脾与止泻之效，有腹泻者加入白扁豆更佳；若平时没有腹泻，可以把白扁豆去掉（见第87页）。","年龄选参调整：参照《清宫档案秘闻》乾隆服法，约50岁以前用党参制作八珍糕，50岁以后再将党参换成人参（见第87-88页）。"],"contraindications":["儿童忌参：孩子尽量别吃任何参类中药（见第102页），乾隆皇帝约50岁前亦先用党参而非人参制作八珍糕（见第87-88页）。","没有腹泻者可将八珍糕中的白扁豆去掉；补脾需分清补脾阴与补脾阳（补中益气丸侧重补脾阳），仍须辨证使用并遵后记筛查原则（见第87、191-192页）。"],"mechanism":"补脾分补脾阴和补脾阳：补中益气丸补脾阳兼养心安神；八珍糕以参补脾阳，山药、莲子肉、白扁豆（及陈实功原方白术）补脾，茯苓、炒薏米祛除困脾湿气，芡实收敛补脾肾，使正气充足、气血有源（pp.87-88）。","fig_id":null,"page":87},{"id":"rem_danggui_chicken_soup","name":"当归养血鸡汤","method_type":"diet_therapy","constitution_ids":["blood_deficiency"],"indications":["血虚体质（尤其是女性），舌边颜色很浅或舌质非常浅带透明感，短时间蹲下站起头晕、神智功能退化失眠多梦、浑身疲乏、面色发黄或苍白、身体凉热随外界环境变化（pp.94-98, 195-196）。"],"ingredients":[{"name":"当归","amount":"6克","note":"煲汤养血药材（第97页）"},{"name":"川芎","amount":"3克","note":"煲汤养血药材（第97页）"},{"name":"枸杞子","amount":"6克","note":"煲汤养血药材（第97页）"},{"name":"鸡肉","amount":"一只","note":"先用热水汆一下，撇去血沫后再同入锅煲汤（第97-98页）"}],"preparation_and_usage":"先将鸡肉一只用热水汆一下，撇去血沫，然后将当归6克、川芎3克、枸杞子6克与鸡肉放在同一个锅里，放入清水再煲汤（见第97-98页、第195-196页）。","modifications":["女性产后补血黄金期（第93页）：生完孩子后最适合补血，除煲汤外也可参考福建习俗炖龙眼肉，或义乌习俗拿黄酒、红曲酒炖红糖（酒里放点龙眼肉养血效果更好）。","若女性血虚兼有体内水湿停滞，须一边祛湿一边养脾养血（见第64页）。"],"contraindications":["原书未单列本方特殊禁忌；但明确指出小儿贫血多因吃得太好太多积食伤脾所致（见第91页），且痰湿营养过剩舌红苔厚腻者千万不能再补身体（见附录第200页），仍须辨证使用并遵后记筛查原则（见第191-192页）。","含当归、川芎活血成分，孕妇宜遵医嘱慎用并主要于产后调补（参照 p.93, 119）。"],"mechanism":"源承《黄帝内经》“五菜为充，五果为助，五谷为养，五畜为益”与商朝伊尹《汤液本草》中药汤液传统，以鸡肉配当归、川芎、枸杞子煲汤滋养身体，改善血虚（pp.97-99）。","fig_id":null,"page":97},{"id":"rem_yulinggao","name":"玉灵膏（王孟英千古养血安神方）","method_type":"diet_therapy","constitution_ids":["blood_deficiency"],"indications":["典型及重度血虚体质，舌质极浅近透明，严重疲劳无力、脸色苍白、怕风怕冷（比常人多穿一个节气的衣服）、头晕（pp.94-97, 99-100）。","血虚不养心所致失眠、多梦、记忆力不好、心力交瘁等心神问题，以及妇女生完孩子后体质一落千丈之养血调补（pp.93-94, 99-101）。"],"ingredients":[{"name":"龙眼肉","amount":"300克","note":"干品色赤入心，养心血、安心神；可用鲜龙眼去掉皮、核取白色果肉自制，蒸完变成黑红色（第99、101页）"},{"name":"西洋参粉","amount":"30克","note":"与龙眼肉同蒸养血；孩子切勿食用（第99、102页）"}],"preparation_and_usage":"将龙眼肉300克、西洋参粉30克放在一起蒸：①现代简化法为小火蒸4个小时（蒸的时间越长龙眼肉热性越小，但仅蒸4小时仍有部分人会上火）；②王孟英原文古法为家里蒸饭时放在笼屉里蒸100次，折算约蒸40个小时——蒸过10个小时后龙眼肉甜味开始减少并变苦，蒸满40个小时不再甜而味苦，吃了不上火且药效极好。放凉以后，每天用一羹匙，开水冲泡服用（见第99、101-102页）。","modifications":["自制龙眼肉：若能买到鲜龙眼，把皮、核去掉剩下白色的肉同蒸，蒸完即变成黑红色（见第99页）。","防上火古法蒸制：若服简化蒸4小时版本上火，可按古法蒸满40个小时（超过10小时甜减变苦）消除上火之弊（见第101-102页）。"],"contraindications":["尽量别给孩子吃参类中药：孩子别吃西洋参，事实上孩子什么参都尽量别吃（单味龙眼肉孩子是可以吃的，但含西洋参粉的玉灵膏儿童忌服）（见第102页）。","孕妇慎用/不要食用龙眼肉：龙眼肉带点热性，若孕妇体内有热吃龙眼肉就会动胎，所以孕妇尽量不要食用龙眼肉及玉灵膏（见第102页）。","仅蒸4个小时的简化做法部分人服用会上火，蒸足40个小时则不再甜且不上火（见第101-102页）。"],"mechanism":"古代名医王孟英所创养血名方：龙眼肉干品色赤入心，养心血、安心神，使心神有依托而妄念减少、睡眠改善；配伍西洋参粉经久蒸40小时后甜退转苦、热性尽除，强力滋养气血而不上火（pp.99-102）。","fig_id":null,"page":99},{"id":"rem_region_stasis_decoctions","name":"部位与病因分治活血逐瘀名方指要（通窍/血府/少腹/桃红四物）","method_type":"tea","constitution_ids":["blood_stasis"],"indications":["头面部瘀血（如面部瘀斑、头部血管经络瘀阻）","胸中血瘀或小腹/少腹部位瘀血阻滞","血虚所致瘀血、受寒老风湿血瘀、湿热入肾致髓瘀等不同病因血瘀证"],"ingredients":[{"name":"通窍活血汤（清代王清任方）","amount":"请当地中医辨证定剂量","note":"药性上行，专治脸上、头面部瘀血"},{"name":"血府逐瘀汤（清代王清任方）","amount":"请当地中医辨证定剂量","note":"主治胸中血瘀"},{"name":"少腹逐瘀汤（清代王清任方）","amount":"请当地中医辨证定剂量","note":"药性下行，主治少腹/小腹部位血瘀"},{"name":"桃红四物汤","amount":"请当地中医辨证定剂量","note":"养血兼活血，主治血虚导致的瘀血"}],"preparation_and_usage":"须由当地执业中医根据瘀血所在部位（上行或下行）与病因开方抓药；熬药口服之外，建议多剩点药汁或直接开方用来泡脚（现代人多脾胃不好、体内有痰湿吸收不了汤药，泡脚经皮肤与经络直接吸收疏通往往比喝药见效更快，如先口服五副不效，改用五副泡脚即效，p.120-121）。","modifications":["湿热进到肾脏乃至骨髓的肾病血瘀患者：须一边凉血、一边化瘀直至解掉（p.120）","受寒、老风湿所致瘀血：须采用温阳化瘀法（p.120）","湿气罩住瘀血（白苔罩紫黑舌）：须一边祛湿气、一边清热化瘀（p.118）","情绪不好、肝气不舒所致气郁血瘀：须一边疏肝气、一边化瘀（p.128）"],"contraindications":["孕妇忌用（孕妇舌现瘀血属胎儿气血凝聚正常现象，严禁使用任何活血化瘀方药，p.119）","切勿凭舌象自行确诊猛投破血逐瘀汤剂，务必找当地中医定性并辨证加减（p.111, p.120-121）","脾胃虚弱夹痰湿者纯口服汤药难吸收且易伤胃，宜遵医嘱改用或配合药汁泡脚（p.121）"],"mechanism":"按病位升降选方（通窍上行头面、血府畅胸中、少腹达下焦）并随病因配伍凉血、温阳、养血或疏肝，配合泡脚透皮入络移走阻路“巨石”，恢复正气通行（p.120-122）。","fig_id":null,"page":120},{"id":"rem_yaotui_hanshi_footbath","name":"腰腿受寒后的驱除寒湿化瘀泡脚方","method_type":"foot_bath","constitution_ids":["blood_stasis","qi_deficiency"],"indications":["腰腿受寒湿侵袭后引起的膝盖疼痛、腰膝不力","下肢寒湿凝滞合并经络细微血液瘀阻"],"ingredients":[{"name":"熟地","amount":"6克","note":""},{"name":"当归","amount":"6克","note":""},{"name":"赤芍","amount":"6克","note":""},{"name":"川芎","amount":"6克","note":""},{"name":"伸筋草","amount":"9克","note":""},{"name":"透骨草","amount":"9克","note":""},{"name":"桃仁","amount":"6克","note":"化有形之血"},{"name":"红花","amount":"6克","note":"散无形之血，散开特别细微的血液瘀阻"},{"name":"桑枝","amount":"6克","note":""},{"name":"丝瓜络","amount":"6克","note":"通络化瘀"},{"name":"桂枝","amount":"6克","note":"温经通阳"},{"name":"薏苡仁","amount":"30克","note":"祛除寒湿"},{"name":"艾叶","amount":"3克","note":"温经散寒"}],"preparation_and_usage":"将上述13味药物放入水中熬开锅20分钟，将药汁兑入温水泡脚。每天泡两次（早晚），每次泡20分钟，水温不可太热，水覆盖脚面即可（p.122）。","modifications":["方中丝瓜络、桃仁、红花协同化瘀（桃仁化有形之血，红花散细微无形之血），配桂枝、艾叶温散寒邪，薏苡仁重用30克利湿，伸筋草、透骨草、桑枝舒筋通络（p.122）"],"contraindications":["孕妇忌用（方含桃仁、红花、川芎、赤芍、当归等活血通经药，孕妇严禁活血化瘀，p.119）","泡脚水温不可太热以防烫伤或大汗耗气，水淹过脚面即可；本方为外用泡脚方，切勿自行内服（p.122）"],"mechanism":"借温水与艾叶、桂枝温通阳气，薏苡仁除湿，四物配桃仁、红花、丝瓜络、伸筋透骨草经足部皮肤经络直达腰膝，散寒除湿并消解有形与无形血瘀（p.121-122）。","fig_id":null,"page":122},{"id":"rem_sanqi_xiyangshen","name":"三七粉配西洋参粉化瘀护心方","method_type":"patent_medicine","constitution_ids":["blood_stasis"],"indications":["心脏瘀血日常调护（舌象仅见单纯瘀血指征而无厚腻湿苔者）","老年人或兼阴虚内热体质需活血化瘀而又怕单服三七温燥伤阴眼干痛者（亦有助透出骨中陈旧瘀血）"],"ingredients":[{"name":"三七粉","amount":"0.5克","note":"又称三七参，含人参皂苷，性热，活血化瘀兼止血，能透出骨头里的瘀血"},{"name":"西洋参粉","amount":"0.5克","note":"性凉，补气补阴，制住三七的热性以防伤阴导致眼睛干疼"}],"preparation_and_usage":"三七粉0.5克、西洋参粉0.5克，每天口服，用白水送下（p.122-123, p.204）。","modifications":["若舌苔很厚、体内有湿气同时心脏又有血瘀，必须先把湿气去掉再行化瘀（p.124）","若伴有心脏憋闷症状，须视憋闷程度请当地中医诊察综合调理，不可单靠小方延误急症（p.124）"],"contraindications":["孕妇忌用（三七活血化瘀，孕妇舌现瘀血属正常凝聚现象，严禁活血化瘀，p.119）","儿童忌服/慎用（书中明确提醒孩子什么参都尽量别吃，不能吃西洋参，p.102）","阴虚或体内有热者（尤其老年人）切忌长期单用三七粉，否则三七药性温热伤阴会导致眼睛又干又疼，必须配西洋参粉制衡（p.123）","舌苔厚腻湿重者须先祛湿；心脏憋闷胸痛明显者必须立即找当地医生诊治（p.124）"],"mechanism":"三七活血化瘀定痛且止血不留瘀，西洋参甘凉补气养阴以制衡三七温燥之性，气阴双补而瘀血自化，专护心脉且不伤津液（p.123-124）。","fig_id":null,"page":122},{"id":"rem_fracture_bone_soup","name":"骨折后的三七鸡腿骨化瘀食方","method_type":"diet_therapy","constitution_ids":["blood_stasis"],"indications":["跌打损伤、骨骼受伤及老年人滑倒骨折后的化瘀止痛与加速骨愈合"],"ingredients":[{"name":"三七（或三七粉）","amount":"三七10克（或三七粉1～3克）","note":"核心化瘀促愈成分"},{"name":"鸡腿骨","amount":"五六根","note":"把肉剔掉光剩骨头（也可稍微带一点点肉），用刀背捣裂"},{"name":"盐和佐料","amount":"少许","note":"调味用"}],"preparation_and_usage":"把鸡腿上的肉剔掉，光剩骨头（也可以稍微带一点点肉），用刀背将鸡腿骨捣裂，然后与三七10克（或三七粉1～3克）一起煲汤，可放入一点盐和佐料。用纱布过滤出汤，每天吃饭时饮用，坚持到骨折恢复为止（p.124, p.204-205）。","modifications":["可用原药材三七10克同煲，或改用三七粉1～3克同煲，煲好后均用纱布滤汤佐餐（p.124）"],"contraindications":["此方孕妇忌用（原书明确叮嘱，p.124, p.205；孕妇严禁活血化瘀，p.119）","骨折须先经医院正规复位固定处理，本方作为骨折恢复期化瘀促愈食疗辅助（p.191）"],"mechanism":"罗氏家传食疗验方，借三七强力消散骨损局部瘀血并促使鸡腿骨有效营养成分溶出吸收，显著减轻骨折疼痛、加快骨骼愈合速度（p.124-125）。","fig_id":null,"page":124},{"id":"rem_hemorrhoid_dilong","name":"治疗痔疮化瘀小方（地龙粉/蒸饺及便血椿根皮方）","method_type":"diet_therapy","constitution_ids":["blood_stasis"],"indications":["局部血液循环不畅引起的单纯内痔、外痔、混合痔肿痛瘀阻","确诊为单纯痔疮所伴发的便血（配用椿根皮红糖水）"],"ingredients":[{"name":"地龙","amount":"50克（每日服5克）","note":"中药店购买，打成粉末后入锅翻炒至微微发黄闭火"},{"name":"瘦猪肉馅","amount":"地龙粉两倍体积（蒸饺法选配）","note":"用多少拌多少，馅内不放作料，包饺子蒸熟或做丸子"},{"name":"椿根皮","amount":"每次30克（可购200克备用，伴便血时用）","note":"熬水出两碗"},{"name":"红糖","amount":"一匙（伴便血熬椿根皮水时加）","note":"椿根皮水熬好后放入"}],"preparation_and_usage":"①冲服/胶囊法：将地龙50克打成粉末，入锅翻炒至微微发黄后闭火，每天温水冲服5克（装入胶囊服用更好），连用3天，如改善用到5天即可（p.125）。②最佳蒸饺法：地龙磨粉后同其两倍体积的瘦猪肉馅搅拌（用多少拌多少，不要放作料），包饺子蒸熟，每次吃7～10个，一日两次，可蘸作料吃，连吃4～5天可收缩痔疮（p.126）。③伴便血法：每次用中药椿根皮30克熬水出两碗，熬好后放入红糖一匙，早晚各喝一碗（p.125-126）。","modifications":["痔疮伴严重便血者：加用椿根皮每次30克熬两碗水兑红糖一匙早晚分服止血（p.125-126）","如能请当地中医针对个人体质加配口服中药同调，效果更佳；注意肛瘘属炎症后直肠与外界直通的瘘管，不同于普通痔疮（p.125-126）"],"contraindications":["此方孕妇忌用（原书明确叮嘱，p.125, p.205）","【铁律必查】便血症状与直肠癌高度相似，出现便血时必须先去医院检查排除直肠癌，切勿把直肠癌当痔疮自治延误生命，只有确诊是痔疮后方可对证调理（p.126）"],"mechanism":"地龙含消融局部血栓、通络散瘀的有效成分，配合瘦肉蒸食扶助吸收以促使瘀曲痔核枯萎收缩；椿根皮涩肠止血配红糖和血缓急（p.125-126）。","fig_id":null,"page":125},{"id":"rem_female_yimu_cycle","name":"女性瘀血调理方（益母丸经期化瘀与八珍益母丸人工周期法）","method_type":"patent_medicine","constitution_ids":["blood_stasis","blood_deficiency","qi_deficiency"],"indications":["女性体内瘀阻导致的月经不畅、经量不多（经期单服益母丸）","非生气引起、确属气血虚弱合并体内瘀血所致的女性早发闭经（如四十来岁停经，用八珍益母丸与益母丸人工周期法）"],"ingredients":[{"name":"同仁堂“益母丸”","amount":"按说明书于经期（或预计经前3天起）服用","note":"专主活血化瘀通经，经量大者忌用"},{"name":"同仁堂“八珍益母丸”","amount":"按说明书于平时非经期服用（闭经周期法用）","note":"由四物汤加四君子汤成八珍气血双补，切勿与益母丸买混"}],"preparation_and_usage":"①经行不畅且经量不多者：仅在月经来潮期间服用几天同仁堂“益母丸”，借经期溶血排血机制化掉瘀血（p.127）。②气血虚弱兼瘀闭经人工周期法（须经专业医生确认非生气所致）：平时服用同仁堂“八珍益母丸”补气养血，在月经前3天停止服用“八珍益母丸”，改服“益母丸”并持续整个月经期直至月经结束；月经过后平时再服“八珍益母丸”养血，按此周期往复循环（p.127, p.205）。","modifications":["因生气、肝气不舒（气郁）导致的瘀血、闭经或结节：单纯化瘀难见效，必须先疏肝理气再化瘀或一边疏肝一边化瘀（甲状腺结节专注疏肝尽量少化瘀，乳腺结节在疏肝基础上加化瘀药，可配艾灸、刮痧，p.127-128）"],"contraindications":["月经量特别大的女性严禁经期服用“益母丸”（p.127）","孕妇绝对忌用（妊娠期严禁服用任何活血通经药物，p.119）","严防把“益母丸”（活血化瘀）与“八珍益母丸”（四物汤+四君子汤，补气补血）搞混买错吃错（p.128）","闭经调理前须请专业医生确认并非生气肝郁或器质性疾病所致；气郁致瘀者忌单靠化瘀蛮治（p.127-128, p.205）"],"mechanism":"经期顺应人体自身溶血排血机制以益母丸轻推化瘀；气血虚闭经者平时以八珍益母丸培补气血生化之源，经前转用益母丸因势通导，重建盈满而泻的月经周期（p.127-128）。","fig_id":null,"page":127},{"id":"rem_child_nourish_yin","name":"调理孩子阴虚（脾阴不足）的七味滋阴妙方与食养法","method_type":"tea","constitution_ids":["yin_deficiency"],"indications":["儿童吃肉过多所致脾阴不足：舌红苔薄或地图舌、嘴唇很红、下眼袋肿红","小儿胃强脾弱（胃口极好但一吃就肚胀）、大便干或不成形、入睡后遍体盗汗、翻滚睡不着","小儿内热好动、耐性差、风吹即反复感冒且一感冒嗓子就肿"],"ingredients":[{"name":"生地","amount":"6克","note":"滋阴清热"},{"name":"薏苡仁","amount":"9克","note":"健脾渗湿护中州"},{"name":"石斛","amount":"6克","note":"养胃生津"},{"name":"沙参","amount":"6克","note":"养阴清肺胃"},{"name":"麦冬","amount":"6克","note":"润肺养胃生津"},{"name":"山药","amount":"6克","note":"补脾益肺肾之阴"},{"name":"莲子肉","amount":"6克","note":"健脾养心安神"}],"preparation_and_usage":"将上述7味药熬水40分钟（药味甘甜适口），每天给孩子喝两小杯；一般连喝5～6天即可，过一段时间若仍有阴虚症状可再喝一个星期。同时必须配合饮食调整：少吃肉、多吃青菜，坚持半年以上（p.136, p.140-141）。","modifications":["日常食疗代饮：可把莲藕、荸荠、白梨或雪梨熬成水，让孩子当饮料喝以柔和滋阴（p.141）","根本饮食干预：严格减少鸡腿、鸭肉、鱼虾、猪肉等过量肉食，多吃青菜坚持半年以上（p.136-137）"],"contraindications":["一般连服5～6天即停（日后复现症状再服一周），勿无限制长期连续服用（p.141）","须按钱乙辨汗法区分：半头汗属实热当清热、胸以上汗属脾胃积食当消食，仅入睡后遍体出汗及舌红唇红属阴虚；脾寒便溏舌淡白者忌用（p.134, p.142）"],"mechanism":"遵明代缪希雍脾阴学说，以生地、石斛、沙参、麦冬甘寒育阴清内热，山药、莲子肉、薏苡仁甘平培补脾阴兼化湿滞，味甜不伤胃，配合减肉增菜截断食滞化火之源（p.136, p.140-141）。","fig_id":null,"page":140},{"id":"rem_adult_yin_bone_soup","name":"调理成人阴虚的生地沙参石斛猪龙骨汤","method_type":"diet_therapy","constitution_ids":["yin_deficiency"],"indications":["成人阴虚体质：舌红苔薄或无苔、老年人红舌深裂纹、地图舌","五心烦热、口眼干燥、失眠盗汗、大便干尿黄、腰膝酸软"],"ingredients":[{"name":"生地","amount":"9克","note":""},{"name":"沙参","amount":"9克","note":""},{"name":"麦冬","amount":"9克","note":""},{"name":"枸杞子","amount":"9克","note":""},{"name":"石斛","amount":"6克","note":""},{"name":"当归","amount":"3克","note":"少量养血和血"},{"name":"猪龙骨（猪脊椎骨）","amount":"一节","note":""}],"preparation_and_usage":"将生地9克、沙参9克、麦冬9克、枸杞子9克、石斛6克、当归3克与猪龙骨（猪脊椎骨）一节同入锅煲汤服用，连服一周即可（p.141, p.197）。","modifications":[],"contraindications":["体内湿热或痰湿盛（舌苔厚腻或黄腻、胃肠胀闷、大便不成形）者忌服，须先清痰湿（p.142, p.144）","阳虚畏寒（舌淡苔白、脉缓、下肢发凉、尿清长）或外感发烧实邪未解者忌盲目煲汤滋补（p.51-52, p.144）","含当归3克，孕妇宜遵医嘱慎用（原书未单列，参照 p.119）"],"mechanism":"生地、枸杞子、猪脊椎骨填补肝肾精血，沙参、麦冬、石斛甘凉清润肺胃津液，佐当归3克养血行津，使干涸津血得润而虚热自平（p.141）。","fig_id":null,"page":141},{"id":"rem_liuwei_dihuang","name":"六味地黄丸（宋代钱乙三补三泻滋补肾阴方）","method_type":"patent_medicine","constitution_ids":["yin_deficiency"],"indications":["肾阴虚证：舌红苔薄、脉细数（较自身往常加快），伴腰膝酸软、头晕眼花（眼干涩迎风流泪）、长时间细小耳鸣耳聋、盗汗自汗（排除桑拿天出汗）","经常熬夜或上夜班（伴肾阴虚指征，如夜班代偿性脂肪肝倾向）、短期高强度用脑过度、长期房事过度耗损阴精者","青春期或过了青春期因肾阴不足、虚火上炎所致面部粉刺频生者（配野菊花、枇杷叶茶）"],"ingredients":[{"name":"熟地","amount":"中成药原方配比","note":"三补之一：入肾经，滋阴补血、益肾添精（性滞腻）"},{"name":"山萸肉","amount":"中成药原方配比","note":"三补之一：直接补益肝经，兼入心经、肾经"},{"name":"山药","amount":"中成药原方配比","note":"三补之一：补给脾经，兼入肺经"},{"name":"丹皮（牡丹皮）","amount":"中成药原方配比","note":"三泻之一：直入肝经血分，清除肝火"},{"name":"茯苓","amount":"中成药原方配比","note":"三泻之一：泄脾经水湿、健脾"},{"name":"泽泻","amount":"中成药原方配比","note":"三泻之一：泻肾经水湿"}],"preparation_and_usage":"确认符合舌质红、舌苔薄、脉细数等肾阴虚指征后按中成药说明服用；脾胃功能弱者可用砂仁1个捣碎泡开水冲服六味地黄丸；稳妥起见建议请当地中医诊脉确认后再服（p.142, p.144）。","modifications":["青春期或过后肾阴不足、虚火上炎满脸粉刺者：服用六味地黄丸的同时，加用野菊花10克、枇杷叶10克泡水代茶饮以加快消退粉刺（p.144）","脾胃功能弱者化滞引经法：用砂仁1个捣碎泡开水，以此水冲服六味地黄丸，既借芳香之气振奋脾胃化解熟地滞腻，又引药气归肾经（p.144）"],"contraindications":["【禁服1·体内有湿热/痰湿者】舌苔厚、舌苔黄腻（排除吸烟和饮橙汁染苔后）、胃肠胀闷、大便不成形者禁服，必须先清掉痰湿（p.142, p.144）","【禁服2·阳虚及脉缓者】舌质颜色淡、脉搏跳动缓慢、下肢发凉怕冷、尿清长的肾阳虚者严禁直接补阴，须先补阳再补阴或阴阳同补（应选用金匮肾气丸）（p.142, p.144）","【慎服3·脾胃功能弱者】主药熟地有滞腻之性，久服易致脾胃不振，慎服；若需服用须用1个砂仁捣碎泡开水冲服（p.144）","本方仅补充阴液物质基础，绝无“壮阳”作用，切勿误解滥用（p.143）"],"mechanism":"宋代钱乙创制肝脾肾“三补三泻”严密配伍：熟地、山萸肉、山药分补肾肝脾三经之阴，丹皮、茯苓、泽泻同步泻去肝火及脾肾水湿邪气，补而不留邪（p.141-142）。","fig_id":null,"page":141},{"id":"rem_jinkui_shenqi","name":"金匮肾气丸（温补肾阳方）","method_type":"patent_medicine","constitution_ids":["yang_deficiency"],"indications":["肾阳不足引起的畏风怕冷（尤以下肢、腹部怕冷）、面色发白或生黑斑、精神萎靡“但欲寐”（p.146, 149, 151-152）","阳虚尿频清长、老年人每晚起夜小便五六次，或肾阳无力蒸发水液所致水肿、口渴（p.151-152）","天冷涉海水/冷水受凉后出现的脚后跟疼痛（配合热水泡脚，p.152）"],"ingredients":[{"name":"熟地","amount":"中成药成方配伍（书中未列单味克数）","note":"补足肾精，作为化生肾阳的物质基础"},{"name":"附子","amount":"中成药成方配伍（书中未列单味克数）","note":"温煦生发阳气"},{"name":"肉桂","amount":"中成药成方配伍（书中未列单味克数）","note":"温煦生发肾阳"}],"preparation_and_usage":"选用张仲景《金匮要略》传世名方中成药“金匮肾气丸”，按说明书剂量口服；若因天冷涉冷水受凉导致脚后跟疼，先用热水泡脚，再吃金匮肾气丸温阳。","modifications":["涉冷水着凉引起脚后跟疼痛时，配合热水泡脚协同温通足下肝脾肾经络（p.152）"],"contraindications":["仅适用于舌淡苔白苍老、脉缓畏寒之肾阳虚证；舌红苔薄脉快之纯阴虚内热或舌苔黄厚腻之痰湿热盛者忌用，用药前须遵后记原则请医师确诊（p.144, 159, 191-192）"],"mechanism":"人体阳气以脾肾为纲，肾阳足则脾阳足；方以熟地滋补肾精使阳有所化，附子、肉桂鼓舞生发肾阳，恢复肾脏白天代谢滤水与蒸腾水液之职。","fig_id":null,"page":151},{"id":"rem_fuzi_lizhong","name":"附子理中丸 / 理中丸","method_type":"patent_medicine","constitution_ids":["yang_deficiency"],"indications":["脾阳不足，一吃或一沾凉东西马上胃疼、腹部冷痛（p.150, 152-153）","肠胃虚寒，一遇冷就腹泻，或中老年人晨起、上午腹泻（p.148, 153）","受寒后引起的急性上吐下泻（p.153）"],"ingredients":[{"name":"附子理中丸（或理中丸）","amount":"按中成药说明书剂量服用（书中未列单味克数）","note":"出自张仲景，原方名“理中丸”，北方药店所售多为“附子理中丸”"}],"preparation_and_usage":"选用中成药“附子理中丸”或“理中丸”按说明书口服，针对沾凉胃疼或受寒上吐下泻可迅速改善脾阳不足。","modifications":["北方售卖多为温阳散寒力更强的“附子理中丸”，平时肠胃遇冷易腹泻者亦可用原方“理中丸”调理（p.153）"],"contraindications":["药性温热，仅适用于舌质淡白、遇冷痛泻的脾胃虚寒证；湿热黄腻苔、实热便秘或阴虚火旺者忌用，须遵后记筛查原则辨证服用（p.153, 191-192）"],"mechanism":"直接温补中焦脾胃阳气、祛寒止痛止泻，解决肾阳虚累及脾阳或寒凉直伤脾阳所致的中焦失运。","fig_id":null,"page":152},{"id":"rem_wendan_footbath","name":"罗氏加减温胆汤泡脚方","method_type":"foot_bath","constitution_ids":["phlegm_dampness"],"indications":["体内湿气凝结成痰、吃得过好所致痰湿体质（舌面水液黏腻、白霜厚腻苔或后半部厚腻裂纹苔，p.157-161）","痰湿郁久化热（舌质发红、有红点、舌苔变黄、两腮发红）及伴“三高”倾向者（p.158-161）","脾胃功能受损、痰湿堵在体内导致口服中药不吸收者（泡脚效果优于吃药，p.161-162）"],"ingredients":[{"name":"茯苓","amount":"30克","note":""},{"name":"陈皮","amount":"6克","note":"偏温性（橘子本身有点温性）"},{"name":"法半夏","amount":"6克","note":"性燥、有燥痰功效，但又是温性的"},{"name":"竹茹","amount":"6克","note":"竹子里边白色的瓤，性凉，有化痰功效，一般6克即很大一团；若体内热很重配到9克"},{"name":"枳实","amount":"6克","note":"橘类药材，行气、有降气作用，将痰浊往外代谢出去"},{"name":"炙甘草","amount":"6克","note":""}],"preparation_and_usage":"将方中药材熬水，开锅30分钟，滤出药汁分成两份，早晚兑入温水泡脚，每次20分钟，水温不要太热，水淹过脚面即可；一般泡十副八副身体即感轻松，随后配合多锻炼、多吃蔬菜巩固。","modifications":["罗博士特去生姜：孙思邈《千金方》温胆汤原含温性的生姜，但现代痰湿人群体内的痰一般都已化热（舌质红、有红点、舌苔变黄），加生姜适得其反，故常规去掉生姜（p.160）","若体内热象很重，方中竹茹可由常规6克加量配至9克以增强清热化痰之力（p.160）","若舌质有红点、内热明显想改为口服（一般喝一两副见效），最好先请附近中医师分析体质并作具体加减（p.161）"],"contraindications":["现代人痰湿化热（舌红有红点、苔变黄）者忌按古方加生姜，否则助热适得其反（p.160）","本方专为湿聚成痰、饮食过盛而设，非痰湿证勿滥用；如需口服必须请当地医生辨证加减，泡脚水温勿过热（p.160-161）"],"mechanism":"方中陈皮、法半夏偏温燥以燥痰，配凉性竹茹清热化痰，枳实行气降气把痰浊往外代谢，去掉古方中温性的生姜以顺应现代人痰多化热之体质；因现代人脾胃受损、痰湿堵在里边难吸收口服药，泡脚反而比吃药效果更好（p.160-162）。","fig_id":null,"page":160},{"id":"rem_phlegm_diet_exercise","name":"痰湿“以清为补”饮食运动调养法","method_type":"diet_therapy","constitution_ids":["phlegm_dampness"],"indications":["肥甘厚味、缺乏运动引起的舌苔厚腻、黄腻、“营养过剩”及“三高”人群日常根本维护（p.157-159, 162）","痰湿困阻浑身乏力犯困、总想打听“吃什么补品”人群的纠偏调理（p.159, 162）"],"ingredients":[{"name":"萝卜白菜、粗茶淡饭（清淡素食）","amount":"日常饮食适量","note":"坚持清淡蔬食、素食，甚至适当断食"}],"preparation_and_usage":"摒弃每日肥甘厚味与夜宵，以萝卜白菜、粗茶淡饭为主食，可坚持素食甚至适当断食，同时把坚持规律运动作为最好的“药方”。","modifications":["痰湿较重阶段可先借温胆汤泡脚十副八副推身体一把脱离困局，之后完全依靠好心态、合理清淡饮食与适当运动长期维护（p.161-162）"],"contraindications":["严禁再进补或盲目服用补肾药物（舌苔厚腻舌红者进补必越补越热、引发严重失调，p.159, 162）；若体内痰湿极重、气血凝滞，宜先祛痰湿再逐步加强锻炼（p.84, 162）"],"mechanism":"痰湿本质是体内“营养”已经过剩，药方只是身体出问题时推一把的辅助工具；吃萝卜白菜、粗茶淡饭（坚持素食甚至适当断食）即“以清为补”，配合好心态与合理运动，把体内痰湿往下清泄排出（p.159, 162）。","fig_id":null,"page":162},{"id":"rem_shugan_huangqi_jianzhong","name":"舒肝和胃丸配黄芪建中汤（见肝之病当先实脾）","method_type":"tea","constitution_ids":["qi_stagnation","qi_deficiency"],"indications":["长期焦虑、恐惧、工作高压伴饥饱不均引起的胃痛、胃溃疡（快到吃饭或吃完饭上腹部疼痛，p.180-181）","肝气不舒横逆克脾合并脾胃虚寒（舌质淡白、身体怕凉），或男子虚损、阳气正气不足动辄自汗（p.180-181）"],"ingredients":[{"name":"黄芪","amount":"6克","note":"方中一般用炙黄芪，罗博士习惯用生黄芪，不会上火"},{"name":"桂枝","amount":"9克","note":""},{"name":"白芍","amount":"18克","note":""},{"name":"炙甘草","amount":"6克","note":""},{"name":"生姜","amount":"9克","note":""},{"name":"大枣","amount":"12个","note":"掰开"},{"name":"饴糖","amount":"30克","note":"前6味药加水5杯熬好去药渣后加入，用微火熬化"},{"name":"舒肝和胃丸（配合中成药）","amount":"按药品说明服用","note":"肝气不舒胃痛可先服或配合使用，见 p.180"}],"preparation_and_usage":"肝郁胃痛可按说明书服中成药“舒肝和胃丸”；兼脾胃虚寒、胃溃疡者用黄芪建中汤：取前6味药（生黄芪6克、桂枝9克、白芍18克、炙甘草6克、生姜9克、大枣12个掰开）加水5杯熬煮，熬好去药渣后加入饴糖30克用微火熬化，分成5杯，早晚各服用一杯（一般三五副即见明显效果）。","modifications":["罗博士经验加减：方中黄芪传统多用炙黄芪，改用生黄芪6克则不易上火（p.181）","若肝气不舒过于严重，须先服用疏肝理气药（如舒肝和胃丸）；若脾胃虚弱严重再遭肝木克伐者，直接用黄芪建中汤强壮脾胃本身以抗外敌（p.180-181）"],"contraindications":["服用前最好请当地中医根据个人体质对药物稍作加减（p.181）","黄芪建中汤偏温补，适用于舌质淡白、身体怕凉的脾胃虚寒证；舌红少苔之阴虚火旺或黄厚腻苔之湿热证忌盲目自服（p.181）"],"mechanism":"遵循医圣张仲景“见肝之病，知肝传脾，当先实脾”思路：舒肝和胃丸疏解肝郁；黄芪建中汤兼具柔肝、缓肝（阻止肝气不舒横逆克脾）与建中补脾之效，将脾胃强壮起来则免受肝木之克（p.180-181）。","fig_id":null,"page":180},{"id":"rem_chaihu_longgu_muli_insomnia","name":"柴胡加龙骨牡蛎汤加味（肝郁失眠泡脚方）","method_type":"foot_bath","constitution_ids":["qi_stagnation"],"indications":["肝气不舒、情绪不佳或精神压力引起的顽固失眠、多梦及各类情绪性身体失调（p.182-183）"],"ingredients":[{"name":"柴胡","amount":"6克","note":""},{"name":"黄芩","amount":"6克","note":""},{"name":"法半夏","amount":"6克","note":""},{"name":"党参","amount":"6克","note":""},{"name":"炙甘草","amount":"6克","note":""},{"name":"茯苓","amount":"30克","note":""},{"name":"煅龙骨","amount":"30克","note":""},{"name":"煅牡蛎","amount":"30克","note":""},{"name":"珍珠母","amount":"30克","note":""},{"name":"桂枝","amount":"6克","note":""},{"name":"郁金","amount":"6克","note":""},{"name":"远志","amount":"6克","note":""},{"name":"香附","amount":"6克","note":""},{"name":"生地","amount":"6克","note":""},{"name":"白芍","amount":"6克","note":""}],"preparation_and_usage":"将上述15味药物放入水中，熬开锅40分钟，滤出药汁分成两份，早晚兑入温水泡脚，每次20分钟，水温不要太热，水淹过脚面即可。一般泡一周为一个疗程，泡三周即不必再泡。","modifications":["身体失调严重者可将口服与泡脚结合：口服须在方中加入生姜3片、大枣12枚（掰开）同熬，且务必请当地中医根据个人体质稍作加减（p.182）"],"contraindications":["孕妇忌用（p.182, 202）","一般泡1周为1疗程，满3周即停，药物仅作一时纠偏，不可靠药物维持一辈子；口服必须请当地中医师辨证加减（p.182-183）"],"mechanism":"基础方为张仲景“柴胡加龙骨牡蛎汤”（历代医案常用于狂躁、抑郁等神志系统疾病），具有收敛心神、疏解不良情绪的作用，情绪与心神调理过来后失眠等相关失调随之痊愈（p.182-183）。","fig_id":null,"page":182},{"id":"rem_tap_lung_meridian","name":"敲揉胳膊内侧肺经痛点法（治凌晨早醒）","method_type":"acupoint_lifestyle","constitution_ids":["qi_stagnation"],"indications":["压力大、肝气不舒化火“木火刑金”（反侮肺金），导致近期突然在清晨3～5点（尤以三四点钟）肺经当令时段早醒（p.174-175, 183-184）"],"ingredients":[],"preparation_and_usage":"对照肺经循行路线图（贴着胳膊内侧的一条线），拿小木棒或用手指沿线敲打探查，专门找痛点（痛点不一定正好在标准穴位上），每天坚持揉或敲打该痛点，一直敲到不痛为止，早醒即可随之消失。","modifications":["在敲揉肺经痛点的同时，若肝郁明显可配合疏肝养肺中药与情绪调节（p.184）"],"contraindications":["敲击力度宜适度，避免猛烈敲打损伤皮肉；肺系疾病无轻症，若已伴随持续咳嗽、走路气喘、出虚汗等肺部病变征兆，须及时就医排查器质性疾病（p.174-175, 184, 191-192）"],"mechanism":"清晨3～5点为肺经当令工作之时，压力大、肝气不舒化火“木火刑金”令肺经受伤故致早醒；沿胳膊内侧肺经敲揉痛点至不痛即可疏通肺经、消除早醒（p.174-175, 184）。","fig_id":"fig_p185","page":184},{"id":"rem_liver_hypertension_footbath","name":"肝郁情绪波动型高血压泡脚方","method_type":"foot_bath","constitution_ids":["qi_stagnation"],"indications":["血压升高或波动明确与生气、焦虑操心、情绪不稳有关者，以及老年人春季血压易升高者（p.185-187）"],"ingredients":[{"name":"柴胡","amount":"6克","note":""},{"name":"黄芩","amount":"6克","note":""},{"name":"党参","amount":"6克","note":""},{"name":"法半夏","amount":"6克","note":""},{"name":"炙甘草","amount":"6克","note":""},{"name":"茯苓","amount":"30克","note":""},{"name":"煅龙骨","amount":"30克","note":""},{"name":"煅牡蛎","amount":"30克","note":""},{"name":"珍珠母","amount":"30克","note":""},{"name":"桂枝","amount":"3克","note":""},{"name":"郁金","amount":"9克","note":""},{"name":"香附","amount":"6克","note":""},{"name":"远志","amount":"6克","note":""},{"name":"丹皮","amount":"6克","note":""},{"name":"生地","amount":"9克","note":""},{"name":"白芍","amount":"9克","note":""},{"name":"丹参","amount":"9克","note":""},{"name":"地龙","amount":"9克","note":""},{"name":"怀牛膝","amount":"9克","note":""},{"name":"钩藤","amount":"9克","note":""}],"preparation_and_usage":"将上述20味药物放入水中，熬开锅40分钟，然后将药汁分成两份，早晚兑入温水泡脚，每次20分钟，水温不要太热，水淹过脚面即可；同时配合情绪开导，少操心、少生气。","modifications":["本方由罗博士在“柴胡加龙骨牡蛎汤”基础上总结加减而成（桂枝3克，郁金、生地、白芍各9克，并配丹皮6克及丹参、地龙、怀牛膝、钩藤各9克，p.185-186）"],"contraindications":["孕妇忌用（含怀牛膝、丹皮、丹参、地龙及柴胡加龙骨牡蛎汤底方，p.119, 182, 186）","泡脚水温切勿过热；仅作为情绪波动相关性高血压的辅助调理，不可擅自停服医院正规降压药，血压异常须遵医嘱监测（p.185-186, 191-192）"],"mechanism":"在“柴胡加龙骨牡蛎汤”基础上总结而出，专门针对因生气、过度操心或春季肝气波动引起的血压升高，通过泡脚把郁结的肝气疏开，配合心理情绪开导使血压平复下降（p.185-187）。","fig_id":null,"page":186},{"id":"rem_thyroid_breast_footbath","name":"甲状腺结节疏肝泡脚方与乳腺增生中成药方","method_type":"foot_bath","constitution_ids":["qi_stagnation"],"indications":["性格要强、经常生气或心里常有愁事引起的甲状腺结节辅助调理（p.187-189）","肝气郁结不通所致的女性乳腺增生（服中成药加味逍遥丸/丹栀逍遥丸，p.187, 189）"],"ingredients":[{"name":"柴胡","amount":"6克","note":""},{"name":"炒栀子","amount":"6克","note":"泻心火，清三焦之火"},{"name":"丹皮","amount":"6克","note":"疏肝气，泻肝火的力量很强"},{"name":"香附","amount":"6克","note":"理气"},{"name":"当归","amount":"6克","note":"养血"},{"name":"川芎","amount":"6克","note":""},{"name":"白芍","amount":"9克","note":"柔肝（即舒肝）"},{"name":"茯苓","amount":"20克","note":""},{"name":"郁金","amount":"6克","note":"疏肝安神"},{"name":"远志","amount":"6克","note":"疏肝安神"},{"name":"加味逍遥丸（丹栀逍遥丸，可选中成药）","amount":"按药品说明辨证服用","note":"用于乳腺增生疏肝泻肝火；上方10味为主治甲状腺结节的泡脚方，见 p.187-189"}],"preparation_and_usage":"甲状腺结节方：将上述10味药物放入水中熬开锅40分钟，药汁分成两份，早晚兑入温水泡脚，每次20分钟，水温不要太热，水淹过脚面即可。乳腺增生患者：一般按说明书服用中成药“加味逍遥丸”（也叫“丹栀逍遥丸”）疏肝气、泻肝火。","modifications":["甲状腺结节病情较重者也可稍微喝一点汤药，但口服前必须请当地中医根据个人体质稍作加减（p.189）","乳腺增生或乳腺结节者除服加味逍遥丸（丹栀逍遥丸）外，可在疏肝基础上酌加化瘀药并配合艾灸、刮痧等外治法（p.128, 189）"],"contraindications":["孕妇忌用（含丹皮、川芎、郁金、当归等活血行气药材，参照 p.119 孕妇禁化瘀原则）","口服前必须请当地中医辨证加减；甲状腺结节与乳腺增生患者（乳腺增生患乳腺癌比例较常人高4倍）必须赴医院定期检查排除恶性病变（p.187, 189, 191-192）"],"mechanism":"炒栀子泻心火、清三焦之火，丹皮疏肝气、强力泻肝火，香附理气，当归养血，白芍柔肝舒肝，郁金、远志疏肝安神，全方养血疏肝、通络（乳腺增生所用加味逍遥丸/丹栀逍遥丸亦为疏肝气、泻肝火），肝疏开、肝火泻掉则结节慢慢变小化掉（p.188-189）。","fig_id":null,"page":188}],"quiz":[{"id":"quiz_01","scenario":"一位在海外生活的女士每次都在清晨刚睡醒时对着镜子拍舌象照片传给医生，照片总是显示舌质颜色偏浅、舌苔偏厚且舌面干燥，导致前几次调理均未见效。","question":"根据书中第二章观舌规范，为什么清晨刚起床看舌象会得出假象？","options":["清晨寅卯时分肝肺阳气初升并聚于上焦，热气熏蒸舌面把正常津液迅速耗干，同时胃中宿食上泛形成白厚假苔，故须等到午饭后半小时内舌体气血充盈时再拍舌照","一夜睡眠后血液循环缓慢未充盈、湿气反映在舌面，若打鼾张口还会改变口腔微环境使舌干，应改在白天背阳间接日光下观察","夜间平卧时心脾营血大多回流贮藏于肝肾，舌黏膜暂时处于生理性缺血状态，唯有夜间入睡前在室内冷光灯稳定照射下拍舌照，才能排除白天活动与阳光干扰","空腹整夜未进水谷会导致胃酸与胆汁轻微反流浸泡舌体，使丝状乳头短暂膨胀变白变干，必须先喝一杯温牛奶或豆浆润泽口腔后再立即拍照才准确"],"correct_index":1,"explanation":"原书 p.37-39 指出：睡了一夜早上刚起时血液循环缓慢未充盈、躺卧湿气聚积，且夜间打鼾张口会使空气直接接触舌面改变微环境，导致晨起舌质偏浅、苔变厚且干燥，全属假象；最标准观舌条件是白天背着阳光的间接日光。","related_constitution_ids":[],"page":37},{"id":"quiz_02","scenario":"张先生近期并无感冒发烧，但经常手心脚心烦热、夜间盗汗、眼睛干涩，照镜子见舌质很红、舌苔极薄。他觉得自己“火大且舌头不够干净”，打算自购牛黄解毒丸清火并用刮舌板刮舌苔。","question":"对照第三章与第七章论述，张先生的计划错在哪里？","options":["无外感而见五心烦热属心肝实火郁闭于里，单吃牛黄解毒丸药力偏轻，应改用黄连、连翘配大剂量灯心竹叶汤苦寒直折，同时早晚轻刮舌面陈旧薄苔以助新苔生发","夜间盗汗与眼睛干涩实为脾肾阳虚、虚阳浮越于体表的真寒假热证，应停用牛黄解毒丸，改服金匮肾气丸引火归元，并用淡盐水每日刷洗舌面以保持口腔清爽","无外感的舌红少苔属津液不足之“虚热”（阴虚），应滋阴而非服牛黄解毒丸泻实火；且刮舌苔会破坏益生菌微环境、损害消化功能","舌红苔极薄提示大病或劳倦伤及胃气化源，当务之急是每天单泡60克生麦芽茶升发胃气待白苔重新铺满舌面，期间每周用刮舌板清理一次脱落上皮细胞即可"],"correct_index":2,"explanation":"原书 p.52 与 p.54-55 强调：阴虚所致内热是津液亏虚的“虚热”（虚则补之，当用生地、沙参、麦冬等滋阴），自作主张吃牛黄解毒丸清实热毫无效果反伤正气；同时舌面微环境参与食物消化第一阶段，刮舌苔会破坏益生菌，对健康不利。","related_constitution_ids":["yin_deficiency"],"page":52},{"id":"quiz_03","scenario":"初学舌诊的小林对比图 p.71 与图 p.72 时犯了难：两张舌头乍看都是白茫茫一片，很容易把水湿重的“舌苔满布”和血虚/体寒的“舌质淡白”搞混。","question":"书中教大家区分“舌苔满布”与“舌质淡白”最关键的一眼判据是什么？","options":["看舌苔颗粒是否把舌头边缘一圈也全部铺满覆盖：铺满不露边是舌苔满布，未被苔覆盖而舌肉本身发白是舌质淡白","重点观察舌体正中央纵沟深浅与舌面津液多少：凡舌中裂纹明显且表面唾液偏多水滑者必为舌苔满布，凡舌面干爽无裂纹且舌体偏瘦小者必为血虚舌质淡白","让被测者用力把舌头尽量往嘴唇外伸展到底：若刚伸出尖而再伸变胖圆属水湿舌苔满布，若舌系带牵拉导致舌头伸不长且舌根见大颗粒突起则属典型舌质淡白","对比舌下两条静脉粗细与两侧牙齿压痕轻重：只要舌两侧带有齿痕就一定是水湿铺满的舌苔满布，只要没有齿痕且舌下静脉颜色浅淡就一定是纯血虚舌质淡白"],"correct_index":0,"explanation":"原书 p.71-72（另见 p.53 轮廓乳头人人皆有、p.82 舌伸不出可能系天生舌系带短）明确指出：区分两者的核心在于观察舌苔颗粒是不是把舌边都铺上了——铺满不露舌质为舌苔满布（湿重），未被完全覆盖而舌体淡白为舌质淡白（血虚或寒/阳虚）。","related_constitution_ids":["qi_deficiency","blood_deficiency","yang_deficiency"],"page":71},{"id":"quiz_04","scenario":"一位常年天天喝大酒的男士，伸出舌头光光的没有舌苔、整个舌面发白，属于脾胃之气受损、胃气严重不足，老中医嘱咐他泡麦芽养胃茶直到新舌苔长出来。","question":"配制这道养胃茶时，在药材炮制品选择上有什么严格要求？","options":["必须选用焦麦芽30～60克配山楂同煮代茶，借焦香苦温之性消解长年饮酒积存的中焦湿热酒毒，同时每天多喝两升温白开水冲刷胃肠道以促使舌苔尽快恢复","生麦芽偏寒凉易伤脾阳，必须选用文火微炒至黄色的炒麦芽30～60克泡茶（或配炙黄芪6g、白术9g煮水），才能温运脾土、推动胃气向上生发新舌苔","应将生麦芽与炒麦芽各取30克等量合泡代茶，取其一升一降调畅中焦脾胃气机枢纽，待舌面稍见薄苔后立即改服六味地黄丸滋养胃阴以防无苔复发","必须用生麦芽（30～60克泡茶，或生黄芪3g、怀山药6g、生麦芽9g煮水），严禁误用把气往下降的炒麦芽"],"correct_index":3,"explanation":"原书 p.81-83 叮嘱：大病后或天天喝大酒致舌白光剥无苔属胃气不足，当务之急是生发胃气，必须选用“生麦芽”（主把气往上升）；千万不要用“炒麦芽”，因炒麦芽是把气往下降的。","related_constitution_ids":["qi_deficiency"],"page":83},{"id":"quiz_05","scenario":"办公室白领小陈坐姿总是塌靠歪斜，爬三楼就气喘自汗、大便不成形，舌胖大有明显齿痕、白苔满布。他习惯每天晨起空腹喝一杯凉白开，用三仁汤泡脚五副湿苔退去后便觉得大功告成。","question":"按照第四章气虚调养原则，为防止水湿很快复发并保护阳气，他必须立刻做哪两件事？","options":["继续将三仁汤由外用泡脚改为每日早晚口服连喝一个月彻底搜剔余湿，同时把晨起凉白开换成温热的浓绿茶全天频饮，借助茶多酚利尿通淋把深层水湿排净","改掉早起喝凉白开伤阳的习惯（早起必喝温水），并在祛湿后马上用怀山药90g、薏苡仁150g、芡实30g研粉配小米熬粥（或吃八珍糕）补脾","湿苔刚退说明体内阴分已被燥湿药耗伤，应马上停用一切健脾祛湿食材，改服六味地黄丸或生地沙参石斛猪龙骨汤连喝两周滋养肾阴，并每天高强度长跑发汗","保留晨起空腹喝一大杯凉白开润肠通便的习惯，同时趁舌苔变薄立刻服用附子理中丸配当归生姜羊肉汤温补命门真火，以免脾肺气虚进一步演变为重度阳虚"],"correct_index":1,"explanation":"原书 p.65 与 p.85-86 强调两点：一是“脾主统水”，祛湿之后必须马上补脾（如山药薏苡仁芡实小米粥坚持半月到一月，或八珍糕），否则三五天后水湿又会回来；二是早晨阳气如小火苗初生，早起喝凉白开及冰饮、过量喝茶均伤阳困脾，早起喝水一定要喝温水。","related_constitution_ids":["qi_deficiency"],"page":65},{"id":"quiz_06","scenario":"产后体虚的李女士蹲下1分钟站起来就眼前发黑头晕，记忆力减退、失眠多梦，舌质极浅带半透明感。她按王孟英古法蒸制了40小时“玉灵膏”（龙眼肉300克、西洋参粉30克），准备自己吃并分给5岁儿子和怀孕的闺蜜。","question":"根据第五章“罗博士特别提醒”，关于玉灵膏的分服对象哪项判断正确？","options":["王孟英原方记载玉灵膏“产后及妊娠临盆前尤益”，经40小时久蒸后龙眼肉热性已尽数化除，故李女士与怀孕闺蜜均可放心常服，唯5岁儿童须将剂量减半冲服","蒸满40小时味苦偏凉反而会克伐产妇脾胃阳气，李女士产后只宜服用小火蒸4小时的清甜版玉灵膏；5岁儿童与孕妇则可改用西洋参粉0.5克配三七粉冲服养血","李女士本人非常适合服用（蒸40小时味转苦且不上火、药效更佳）；但孩子尽量别吃西洋参等任何参类（可单吃龙眼肉），孕妇则忌食/慎食带热性的龙眼肉以防动胎","蹲下1分钟站起头晕纯属产后久卧常见的体位性低血压而非血虚指征，李女士无须服用玉灵膏，反倒是5岁小儿面色偏白最宜每日一羹匙玉灵膏补益先天心脾之气"],"correct_index":2,"explanation":"原书 p.94 与 p.99-102 明确指出：蹲下1分钟站起即头晕眼黑属血虚（蹲半小时才晕方为普通体位性低血压）；玉灵膏蒸40小时后甜味转苦、不上火而养血安神极佳，但儿童应尽量禁食西洋参等一切参类中药，孕妇食用热性龙眼肉易动胎故忌用/慎用。","related_constitution_ids":["blood_deficiency"],"page":102},{"id":"quiz_07","scenario":"68岁的王大爷既往伸舌一直端正，最近女儿偶然发现他伸舌时舌尖明显偏向左侧，但王大爷自述既不头疼也不肢体发麻，不肯去医院。","question":"排除天生生理性舌尖偏斜后，这一舌象具有什么高危预警意义？","options":["舌尖偏向哪侧往往提示同侧头部血管有瘀血堵塞隐患（脑梗前兆可比症状提前数年出现），老人脑血管极易突发堵塞，必须尽快就医检查并及时化瘀","老年人舌体两侧对应左肝右胆，舌尖突然偏向左侧说明右侧胆经气郁化火挤压舌肌，只要没有头晕手麻就无需就医检查，在家用柴胡加龙骨牡蛎汤泡脚三周即可复位","无头疼肢麻的新发舌尖左偏多属脾气亏虚、半侧舌肌失养松弛所致，并非血脉瘀阻，只需每天坚持服用补中益气丸配山药薏苡仁芡实小米粥健脾益气便能自行恢复端正","按照经络交叉映射规律，舌尖偏向左侧提示右侧下肢静脉或心脏冠状动脉刚出现轻度寒凝，可在家直接口服大剂量血府逐瘀汤半个月观察，待出现麻木症状再去医院拍片"],"correct_index":0,"explanation":"原书 p.114-116 记载罗博士提前三年从同学舌尖偏斜预判腔隙性脑梗塞的案例：排除天生舌尖偏后，舌尖往哪侧偏即提示哪侧头部血液有堵塞，此舌象常比临床发病提前很久出现；老人脑血管说堵就堵，一旦发现舌向改变必须立即带去医院检查。","related_constitution_ids":["blood_stasis"],"page":115},{"id":"quiz_08","scenario":"小赵刚学会识别舌尖瘀点与舌下粗黑静脉，见到怀孕5个月的表姐舌头上有明显血瘀指征，便催促表姐赶紧用三七10克煲鸡腿骨汤或吃益母丸“把瘀血化掉”。","question":"罗博士在第六章专门针对此类行为发出了什么安全警告？","options":["妊娠期脾胃运化负担较重，严禁口服三七鸡腿骨汤或益母丸等内服破血药，但可安全改用桃仁6克、红花6克、当归6克熬水每晚温水泡脚20分钟，经足底经络温和散瘀护胎","三七单味药性偏温易伤孕期阴血，只要把鸡腿骨汤和益母丸换成三七粉0.5克等量配伍凉润的西洋参粉0.5克白水送服，既能化散母体舌下血瘀，又能补益胎儿气阴而无动胎之虞","怀孕中期舌现瘀点说明胎盘微循环供血受阻，虽禁用猛烈的益母丸，但应抓紧炖服当归养血鸡汤配炒地龙粉每日5克温通血脉，直至舌下两条粗黑静脉完全消退变淡为止","千万不要给孕妇看舌象判血瘀！胎儿形成本身就是气血凝聚的过程，孕妇舌现血瘀指征属正常生理现象，妄用三七、地龙、益母丸等活血化瘀药极易酿成大祸"],"correct_index":3,"explanation":"原书 p.119“罗博士特别提醒”及 p.124-125 明确警告：胎儿形成即气血凝聚过程，孕妇舌象显示有瘀血属正常现象，严禁按血瘀给孕妇用活血化瘀药（书中三七骨折汤、地龙痔疮方、柴胡龙牡汤等均明确标注孕妇忌用）。","related_constitution_ids":["blood_stasis"],"page":119},{"id":"quiz_09","scenario":"甲先生近期大便频繁带血，想直接用椿根皮30克熬水加红糖或地龙粉治痔疮；乙女士43岁因气血虚弱合并瘀血闭经（已请医生排除生气气郁所致），分不清药店里的“八珍益母丸”和“益母丸”。","question":"针对甲、乙二人的用药与医疗安全，下列哪项处理完全正确？","options":["甲先生若便血颜色鲜红且不痛，可先在家吃地龙瘦肉蒸饺加椿根皮红糖水观察两周，无效再去医院；乙女士应平时常服“益母丸”活血通经，来月经期间改服“八珍益母丸”固摄防崩漏","甲先生便血必须先去医院检查排除直肠癌，确认是单纯痔疮后方可对证调理；乙女士平时服“八珍益母丸”补气血，经前3天停服改服“益母丸”至经净（经量大者忌用益母丸）","甲先生须先去医院做肠镜排除直肠癌，确诊痔疮后宜长期每天服用三七粉3克止血；乙女士气血双亏严禁用任何含益母草的成药，只能全程单服补中益气丸配玉灵膏直至月经自行恢复","甲先生可直接用椿根皮30克熬水止血并同步去医院查血常规；乙女士可将“八珍益母丸”与“益母丸”每天早晚交替同服，即便平时月经量特别大也可借经期活血机制彻底排净陈旧瘀血"],"correct_index":1,"explanation":"原书 p.125-128 强调：①直肠癌便血与痔疮极相似，便血必须先赴医院检查排除直肠癌，确诊痔疮后方可用地龙或椿根皮方（孕妇忌用）；②“八珍益母丸”（四物+四君子，偏补气血）与“益母丸”（偏活血化瘀，经量大忌用）切勿买混，气血虚闭经按人工周期交替服用，若属气郁致瘀则须先疏肝再化瘀。","related_constitution_ids":["blood_stasis","blood_deficiency","qi_deficiency"],"page":126},{"id":"quiz_10","scenario":"5岁半的男孩每天在幼儿园和家里顿顿大鱼大肉，嘴唇红得像涂了口红、下眼袋又肿又红，胃口极好但一吃就肚胀，好动坐不住、耐性差，风一吹就感冒且一感冒嗓子就肿，舌红苔薄。","question":"该男孩属于典型的什么问题，应当如何调理？","options":["属于典型小儿肾阴亏虚兼心肝实火，应按成人减半剂量连续服用六味地黄丸三个月填补肾精，同时每天用淡竹叶6克、灯心草6克加莲子心泡水代茶，清泻上焦咽喉实火以防扁桃体反复化脓","属于脾肺气虚无力“土生金”导致的卫表不固与食积内停，应立即停掉蔬菜水果，每天用怀山药90克、薏苡仁150克、芡实30克熬小米粥配党参八珍糕健脾益气，并加泡炒麦芽水消肉食积滞","吃肉过多伤脾导致的儿童“脾阴不足”（胃强脾弱、内热上返）；可用生地6g、薏苡仁9g、石斛6g、沙参6g、麦冬6g、山药6g、莲子肉6g熬水喝5～6天（或藕/荸荠/梨水），并坚持少吃肉多吃青菜半年以上","属于小儿肝气不舒横逆犯胃引起的胃热炽盛，因孩子天生阳常有余，应先用罗氏去生姜温胆汤每天早晚泡脚20分钟清化中焦痰热，待嘴唇与眼袋红肿消退后再炖当归鸡汤补养气血增强体质"],"correct_index":2,"explanation":"原书 p.135-136 与 p.140-141 详述：唇红、下眼袋肿红、胃强脾弱食胀、好动耐性差、易感冒且一感嗓子必肿是吃肉过多所致小儿脾阴不足的典型表现；可短期喝7味儿童滋阴甜水5～6天，治本之策是少吃肉、多吃青菜坚持半年以上。","related_constitution_ids":["yin_deficiency"],"page":136},{"id":"quiz_11","scenario":"三位男士都想吃“六味地黄丸”保健：老周舌苔黄厚腻、胃肠胀闷便溏（非吸烟染苔）；老吴舌淡苔白脉缓、下肢发凉尿清长；老郑舌红苔薄脉细数、熬夜腰膝酸软耳鸣，但脾胃稍弱怕熟地滞腻。","question":"对照第七章六味地黄丸使用规范，下列哪项决策正确？","options":["老周（湿热）和老吴（阳虚，应先用金匮肾气丸补阳）均禁服；老郑适合服用，可用1个砂仁捣碎泡开水冲服六味地黄丸以化熟地滞腻并引药归肾","方中本就自带茯苓、泽泻、丹皮“三泻”清利湿热，故老周黄腻苔与老郑阴虚均可直接服用；唯老吴阳虚下肢冷禁服，须改用附子理中丸温补脾阳待手脚转暖后再接服六味地黄丸","老吴夜尿清长属肾精不固、老郑耳鸣腰酸属肾阴亏虚，二人皆宜长期同服六味地黄丸培补肾本；老周胃胀便溏须先用温胆汤泡脚清退黄腻苔后，再配生麦芽茶送服六味地黄丸","三位男士均不宜直接服用：老周须用三仁汤祛湿，老吴须用金匮肾气丸温阳，而老郑既然脾胃虚弱就绝对禁用含熟地的一切成药，只能单靠生地沙参石斛煲猪龙骨汤替代调养"],"correct_index":0,"explanation":"原书 p.142-144 明确列出六味地黄丸不能壮阳及三类禁慎人群：①体内湿热（苔厚黄腻、胃胀便溏）禁服；②阳虚（舌淡脉缓、下肢冷尿清长）不要马上补阴，应先用金匮肾气丸补阳；③脾胃弱者慎服，可用砂仁1个捣碎泡开水冲服以振奋脾胃、化解熟地滞腻并引药归肾。","related_constitution_ids":["yin_deficiency","yang_deficiency","phlegm_dampness"],"page":144},{"id":"quiz_12","scenario":"72岁的刘大爷舌质很淡不红、白苔显得苍老，大夏天穿长袖仍怕风怕冷（下肢尤甚），每晚起夜小便五六次，却总觉得口中干燥；他老伴则是只要一吃凉东西马上胃疼、吹冷风就拉肚子。","question":"为什么刘大爷明明阳虚却会口干，老两口分别适合哪种中成药调理？","options":["频繁起夜排尿过多耗伤了体内津液导致“阳损及阴”、阴虚内热口干，故刘大爷应早服金匮肾气丸、晚服六味地黄丸阴阳双补；他老伴脾胃气虚无力固摄，应常服补中益气丸升阳止泻","老年人口干伴舌体苍老实为下焦瘀血阻滞津液上承（“但欲漱水不欲咽”），刘大爷宜用三七粉配西洋参粉化瘀生津；他老伴遇冷腹痛拉肚子属肝郁乘脾，宜服舒肝和胃丸配白扁豆八珍糕","刘大爷大夏天怕冷伴口干属外寒束表、里湿化热的少阳郁证，老两口均不宜直接吃温热成药，应先用加桂枝3克的祛湿三仁汤早晚泡脚疏通经络，再用怀山药薏苡仁芡实小米粥平补脾肾","重度阳虚火力衰微，津液无法蒸腾而上（如蒸饭火微则锅盖干燥）故反见口干；刘大爷肾阳虚夜尿多宜用“金匮肾气丸”，老伴脾阳虚沾凉胃疼腹泻宜用“附子理中丸”（或理中丸）"],"correct_index":3,"explanation":"原书 p.147 与 p.150-153 指出：夏天仍怕冷怕风、舌淡苔白苍老属阳虚（异于夏天手暖、舌淡嫩之血虚）；轻度阳虚舌苔水滑，重度阳虚火衰不能蒸腾津液上承故反口干，温阳后唾液自生；肾阳虚夜尿五六次用金匮肾气丸，脾阳虚一沾凉即胃疼腹泻用附子理中丸/理中丸。","related_constitution_ids":["yang_deficiency"],"page":151},{"id":"quiz_13","scenario":"经常应酬吃夜宵的孙总整天没力气、犯困，伸舌见舌面黏腻不爽、苔厚白如霜且渐转黄，底下舌质发红有红点。朋友劝他吃补肾保健品提神，并按《千金方》原方抓了带大量生姜的温胆汤喝。","question":"根据第九章痰湿篇论述，孙总目前面临什么健康风险，调理上应如何纠偏？","options":["整天犯困乏力确属应酬劳倦伤及脾肾真阳，虽不宜吃鹿茸等峻补保健品，但《千金方》原方重用生姜恰能温化寒痰、醒脾助运，只需将汤药改为早晚口服连喝十副即可迅速消退霜白厚苔","黏腻水液与白霜厚腻苔提示极可能已有“三高”，舌红苔厚属营养过剩严禁进补（补肾必越补越热）；应用罗氏去生姜温胆汤泡脚（热重竹茹配至9克），并以萝卜白菜粗茶淡饭和运动“以清为补”","舌质发红有红点伴白厚腻苔属典型“阴虚被水湿掩盖”，应停用温燥的法半夏与陈皮，改用薏苡仁赤小豆饮全天代茶利湿，同时用砂仁1个泡水冲服六味地黄丸，一边渗湿一边滋补肝肾之阴","白厚霜苔渐转黄说明外感暑湿疫毒已由表入里化热，不可外用泡脚延误病机，应先口服祛湿三仁汤加竹叶连发透汗三五天，待厚苔退净后立刻用当归养血鸡汤配八珍糕补足亏虚正气"],"correct_index":1,"explanation":"原书 p.157-162 强调：①舌上水液黏腻或苔白厚如霜者体检基本已有“三高”；②舌苔厚腻舌质红是营养过剩、痰湿化热，千万不能再补（误补肾必越补越热）；③现代人痰多化热，罗氏温胆汤（茯苓30g、陈皮6g、法半夏6g、竹茹6～9g、枳实6g、炙甘草6g）特地去掉生姜，且脾湿不吸药时泡脚比吃药更好，日常须以粗茶淡饭与运动“以清为补”。","related_constitution_ids":["phlegm_dampness"],"page":160},{"id":"quiz_14","scenario":"门诊同时来了两位“尖舌”患者：一位是刚上小学、妈妈对其考分要求极度严苛焦虑的孩子；另一位是在单位对谁都好、受了委屈全憋在心里的“老好人”，服了几副中药觉得睡眠好转但舌头依然尖红。","question":"结合第二章与第十章关于气郁尖舌的分析，下列哪项认识准确无误？","options":["小儿脏腑清灵绝无七情气郁之理，学龄儿童舌形变尖实为过食肉类积滞化热灼伤心脾所致；而成人服疏肝药后只要睡眠与胃口恢复正常，舌形尖红仅属天生解剖常态，即可彻底停药无需再调","脾气暴躁、遇事当场拍桌发火的“暴怒”对肝胆血脉冲击最猛，远比隐忍不发的“郁怒”更容易诱发恶性肿瘤；该老好人睡眠好转而舌尖仍红，只需连续喝一周灯心竹叶汤泻掉余火便能根除病根","家长焦虑气场会直接传染给孩子（数年高压塑造成器质性尖舌）；老好人长年隐忍“郁怒”得肿瘤比例最高；且睡眠虽好转但尖舌未变说明郁根仍在，必须持续调神养心","舌形与舌苔一样在三五天内即可随情绪快速改变，若老好人复诊时发现舌头刚伸出尖、继续伸展变胖圆，说明肝郁气滞正在顺利消散、脾胃气血渐充，是即将彻底康复的良性转归信号"],"correct_index":2,"explanation":"原书 p.43、p.168-171 及 p.177 阐明：①老好人苛求完美、把火憋在心里的“郁怒”比暴怒伤害更不可逆，在肿瘤患者中占比最高；②家庭压抑与父母焦虑会直接导致幼儿及小学生肝气不舒；③舌苔几天可改，但尖舌属长期器质性塑造，药后症状虽减而尖舌未改说明内里问题尚存，须继续养心调神（初尖后胖则是肝郁夹水湿重）。","related_constitution_ids":["qi_stagnation"],"page":169},{"id":"quiz_15","scenario":"高压行业的陈女士近三个月突然每天凌晨三四点钟准时早醒，白天胸闷；同部门的小吴长期精神紧张加吃饭饥饱无常查出胃溃疡，饭后上腹痛、舌淡白怕凉。","question":"按照第十章方案，陈女士的凌晨早醒与小吴的虚寒型胃溃疡应分别采用什么方法？","options":["陈女士属肝火过旺“木火刑金”伤及凌晨3～5点当令的肺经，应每日沿胳膊内侧肺经敲揉痛点至不痛；小吴按“见肝之病，知肝传脾，当先实脾”用黄芪建中汤（罗氏习惯用生黄芪6g防上火，配桂枝9g、白芍18g、炙甘草6g、生姜9g、大枣12个、饴糖30g）","凌晨3～5点属肝胆经气血交会之时，陈女士应每日敲打大腿外侧胆经并单喝灯心草6g、竹叶6g泻火安眠；小吴胃溃疡属肝郁化火灼伤胃络，忌用温热的桂枝生姜饴糖，应单服加味逍遥丸清肝泻火","陈女士早醒伴白天胸闷属典型心脾两虚失眠，应每晚冲服古法蒸40小时的玉灵膏养心安神；小吴舌淡白怕凉饭后腹痛属纯脾肾阳虚寒凝，应长期单服附子理中丸并配炒麦芽60克消食行滞","陈女士应直接口服15味柴胡加龙骨牡蛎汤（无需加生姜大枣）重镇潜阳以止早醒；小吴按“见肝之病当先实脾”应用蜜炙黄芪30克替代生黄芪配党参八珍糕峻补脾气，方能迅速愈合溃疡创面"],"correct_index":0,"explanation":"原书 p.174-175、p.180-181 与 p.183-185 指出：①清晨3～5点为肺经当令，突然在此刻早醒多为肝气不舒“木火刑金”，拿小木棒沿胳膊内侧肺经找痛点每天敲揉至不痛极效（并警惕肺系重症）；②压力焦虑伴虚寒胃溃疡遵循张仲景“见肝之病，知肝传脾，当先实脾”，用舒肝和胃丸或黄芪建中汤（生黄芪6g不易上火）柔肝建中。","related_constitution_ids":["qi_stagnation","qi_deficiency"],"page":184},{"id":"quiz_16","scenario":"62岁的赵阿姨爱操心儿孙琐事，不仅常年失眠多梦，一生气血压就往上升，体检还发现了甲状腺结节。家人准备参考第十章的泡脚方帮她辅助调理。","question":"关于第十章失眠方（15味）、情绪型高血压方（20味）与甲状腺结节方（10味）的用法及后记原则，哪项表述完全正确？","options":["三方药材均须先用大火猛煮15分钟趁滚烫熏洗双脚至大汗淋漓以宣泄郁火；只要坚持泡满三个疗程血压回落，赵阿姨便可自行停掉医院开具的常规降压西药，并把剩余药汁直接留作次日口服","既然同属肝气不舒所致，可将失眠15味、高血压20味与甲状腺结节10味合为一炉大剂每天口服两碗以求速效；且甲状腺结节与乳腺增生纯属良性气滞痰凝，居家疏肝泡脚后无需再赴医院复查排恶","失眠泡脚方因含煅龙骨、煅牡蛎与珍珠母重镇安神，必须终身每晚连续泡脚方能维持睡眠；而情绪波动型高血压与甲状腺结节只需每天用淡竹叶6克、灯心草6克煮水代茶即可替代外用泡脚方","三方均熬开锅40分钟分早晚兑温水泡脚20分钟（水温勿太热，淹过脚面）；失眠方1周1疗程泡3周即止且原书明标孕妇忌用（含行气活血药诸方妊娠亦须避忌，口服均须请当地中医加减），舌诊仅作筛查不替代医生确诊"],"correct_index":3,"explanation":"原书 p.182-189 与后记 p.191-192 反复叮嘱：柴胡加龙骨牡蛎汤加味治失眠（15味，泡1周为1疗程、3周即止，原书 p.182/202 明文单列“孕妇忌用”，口服加生姜3片大枣12枚须请当地中医加减）、高血压泡脚方（20味）及甲状腺结节泡脚方（10味，乳腺增生可用加味逍遥丸/丹栀逍遥丸）均熬40分钟早晚温水泡脚20分钟，凡含行气活血药材之方妊娠均须避忌（p.119）且口服必请当地中医辨证加减；舌诊只给健康筛查“怀疑的权利”而非诊断权，一切药方皆为暂时补救，良好情绪、合理饮食和积极锻炼才是健康大道。","related_constitution_ids":["qi_stagnation"],"page":182}],"decision_tree":{"steps":[{"id":"step_1_color","step_num":1,"title":"第一步：望舌质底色","prompt":"请在白天背阳的间接日光下自然伸舌（先排除染苔饮品、晨起、饭后半小时、有色灯光、经期及化妆口红假象；孕妇勿按血瘀判读），观察舌边一圈及舌体底色：","options":[{"id":"opt_color_normal","label":"淡红润泽（舌边一圈淡红柔和）","hint":"气血充盈度基本正常，继续核查舌苔与舌形是否有局部偏颇（p.35, 47）。","fig_id":"fig_p035","next_step_id":"step_2_coating","match_constitution_ids":[],"match_sign_ids":["sign_normal_pale_red"]},{"id":"opt_color_pale_tender","label":"淡白娇嫩或舌边浅淡带半透明感","hint":"舌黏膜与舌肌血液充盈不足，指向血虚或气血两虚（或阴虚久耗转血虚）（p.72, 96-97, 140）。","fig_id":"fig_p097","next_step_id":"step_2_coating","match_constitution_ids":["blood_deficiency","qi_deficiency"],"match_sign_ids":["sign_pale_white_base","sign_blood_pale_no_full_coat","sign_blood_mild_pale_edge","sign_blood_typical_transparent","sign_yin_red_to_pale_shift"]},{"id":"opt_color_pale_aged","label":"舌质很淡不红，质地看上去偏“苍老”","hint":"排除血虚淡嫩后，指向体内阳气不足或外寒侵袭（p.48-50, 150）。","fig_id":"fig_p150","next_step_id":"step_2_coating","match_constitution_ids":["yang_deficiency"],"match_sign_ids":["sign_pale_white_base","sign_yang_pale_aged"]},{"id":"opt_color_red_tip_edges","label":"舌尖或舌两侧边缘发红（或舌尖至舌中有红点芒刺）","hint":"舌尖应心与下焦、舌边应肝胆，提示肝郁心火或上中焦湿热（排除女性经期生理变红）（p.40, 75-76, 176, 179）。","fig_id":"fig_p176","next_step_id":"step_2_coating","match_constitution_ids":["qi_stagnation","qi_deficiency"],"match_sign_ids":["sign_stagnation_pointed_red","sign_stagnation_heart_fire_tip","sign_qi_fungiform_red_dots","sign_qi_damp_masks_heat"]},{"id":"opt_color_red_whole","label":"全舌明显偏红或深红（绛色）","hint":"体内热象增加：无外感而少苔为阴虚虚热，伴厚黄腻苔为营养过剩痰湿实热（p.48, 51-52, 137, 159）。","fig_id":"fig_p137","next_step_id":"step_2_coating","match_constitution_ids":["yin_deficiency","phlegm_dampness"],"match_sign_ids":["sign_red_crimson_purple","sign_yin_red_thin_coat","sign_phlegm_red_heat_excess","sign_yin_red_to_pale_shift"]},{"id":"opt_color_purple_dark","label":"舌质发青、偏紫或白苔下透出紫黑色","hint":"血液运行受阻，提示体内存在瘀血或湿气笼罩血瘀（孕妇除外）（p.48, 116-119）。","fig_id":"fig_p119","next_step_id":"step_2_coating","match_constitution_ids":["blood_stasis"],"match_sign_ids":["sign_red_crimson_purple","sign_stasis_with_damp","sign_stasis_damp_masked"]}]},{"id":"step_2_coating","step_num":2,"title":"第二步：察舌苔厚薄、润燥与颜色","prompt":"接着观察铺在舌面上的舌苔状态（切勿人为刮舌苔，注意排除橘汁、浓茶、咖啡、抗生素或牛奶豆浆造成的假苔）：","options":[{"id":"opt_coat_thin_white","label":"薄白清爽、边上露出舌质（或仅暂时虚浮似能刮掉）","hint":"薄白苔为正常胃气所生；若苔浮泛无根多为短时积食或喝牛奶所致，清淡饮食一天即退（p.53, 79-80）。","fig_id":"fig_p035","next_step_id":"step_3_shape_stasis","match_constitution_ids":[],"match_sign_ids":["sign_normal_pale_red","sign_qi_floating_coating"]},{"id":"opt_coat_full_white","label":"白苔铺满整个舌面不露舌边，或遮盖住底下的红/紫/尖舌","hint":"脾虚水湿偏重，且常掩盖体内的热象、阴虚、血瘀或肝郁（p.66, 71, 74, 118-119, 138, 178）。","fig_id":"fig_p071","next_step_id":"step_3_shape_stasis","match_constitution_ids":["qi_deficiency","qi_stagnation"],"match_sign_ids":["sign_qi_spleen_damp_full","sign_qi_full_coating","sign_qi_damp_masks_heat","sign_yin_masked_by_damp","sign_stasis_damp_masked","sign_stagnation_pointed_white_coat"]},{"id":"opt_coat_sticky_frost","label":"舌面水液黏腻不爽、白厚腻如霜（或灰黑而极端湿润）","hint":"湿气已凝炼成痰湿，白霜厚腻或黏腻水液均属“三高”高危预警（p.57, 157-158）。","fig_id":"fig_p158","next_step_id":"step_3_shape_stasis","match_constitution_ids":["phlegm_dampness"],"match_sign_ids":["sign_phlegm_sticky_fluid","sign_phlegm_frost_thick","sign_moist_greasy_black_coating"]},{"id":"opt_coat_yellow_greasy","label":"舌苔厚腻发黄（伴舌质红或红点），或高热干焦发黑","hint":"黄厚腻舌红属营养过剩痰湿化热（严禁进补，伴舌尖舌中红点为脾虚湿热）；干焦黑苔属外感热极急症，须立即就医，非痰湿（p.56, 76, 158-159）。","fig_id":"fig_p159","next_step_id":"step_3_shape_stasis","match_constitution_ids":["phlegm_dampness"],"match_sign_ids":["sign_phlegm_red_heat_excess","sign_qi_fungiform_red_dots","sign_charred_black_coating"]},{"id":"opt_coat_thin_peeled","label":"舌苔极薄、光剥无苔，或成块脱落呈“地图舌”","hint":"舌白无苔为大病或饮酒伤及脾胃正气；舌红少苔或地图舌多为阴虚津亏（p.40, 55, 81-82, 138-139）。","fig_id":"fig_p139","next_step_id":"step_3_shape_stasis","match_constitution_ids":["yin_deficiency","qi_deficiency"],"match_sign_ids":["sign_peeled_or_thin_stomach","sign_qi_no_coating_pale","sign_yin_red_thin_coat","sign_yin_geographic_tongue"]}]},{"id":"step_3_shape_stasis","step_num":3,"title":"第三步：审舌体形状、裂纹与舌下血络","prompt":"观察舌体轮廓胖瘦、伸舌姿态，再张口将舌尖翘起轻舔上唇（天生舌系带短者除外），检查舌面斑点与舌下两条静脉：","options":[{"id":"opt_shape_normal","label":"舌体椭圆适中、无齿痕瘀点，舌下静脉淡蓝直径不超2毫米","hint":"舌体形态与血络通畅度良好（p.35, 113, 176）。","fig_id":"fig_p035","next_step_id":"step_4_symptom_confirm","match_constitution_ids":[],"match_sign_ids":["sign_normal_pale_red"]},{"id":"opt_shape_swollen_teeth","label":"舌体胖大、两侧齿痕明显，或伴两条唾液线、舌中深纵裂","hint":"排除牙齿畸形后，齿痕胖大与舌中裂纹主脾气虚水湿重；圆胖伴唾液线多兼肝郁困脾（p.68-69, 78, 80-81）。","fig_id":"fig_p068","next_step_id":"step_4_symptom_confirm","match_constitution_ids":["qi_deficiency","qi_stagnation"],"match_sign_ids":["sign_qi_teeth_marks","sign_qi_swollen_tongue","sign_qi_saliva_lines","sign_qi_center_crack"]},{"id":"opt_shape_pointed","label":"舌头伸出呈尖尖的锥形，或初伸尖、再伸变胖圆","hint":"长期情绪焦虑抑郁塑造的器质性肝郁舌形；初尖后胖说明肝气不舒合并水湿停聚（p.170-171, 176-179）。","fig_id":"fig_p177","next_step_id":"step_4_symptom_confirm","match_constitution_ids":["qi_stagnation","qi_deficiency"],"match_sign_ids":["sign_stagnation_pointed_red","sign_stagnation_pointed_to_fat","sign_stagnation_pointed_white_coat","sign_stagnation_heart_fire_tip"]},{"id":"opt_shape_red_cracks","label":"舌质红而布满深裂纹（老人多见），吃辣即感舌痛不适","hint":"年龄增长或久耗津液导致的典型阴虚失濡表现（p.139）。","fig_id":null,"next_step_id":"step_4_symptom_confirm","match_constitution_ids":["yin_deficiency"],"match_sign_ids":["sign_yin_elderly_deep_cracks"]},{"id":"opt_shape_stasis_spots_veins","label":"舌尖舌边有青黑瘀点瘀斑，或舌下静脉又黑又粗向四周分叉","hint":"明确体内有瘀血；若女性同时嘴唇上汗毛很重，需排查子宫肌瘤、卵巢囊肿（p.112-114, 117-118）。","fig_id":"fig_p114","next_step_id":"step_4_symptom_confirm","match_constitution_ids":["blood_stasis"],"match_sign_ids":["sign_stasis_tip_spots","sign_stasis_severe_spots","sign_stasis_sublingual_veins","sign_stasis_female_lip_hair"]},{"id":"opt_shape_deviated_alert","label":"舌尖最近发生偏斜（排除天生生理性舌偏）","hint":"高危预警：舌尖偏向哪侧常提示哪侧脑血管存在堵塞隐患，老人尤须立即就医检查（p.114-116）。","fig_id":"fig_p115","next_step_id":"step_4_symptom_confirm","match_constitution_ids":["blood_stasis"],"match_sign_ids":["sign_stasis_deviated_tip"]}]},{"id":"step_4_symptom_confirm","step_num":4,"title":"第四步：合参日常身体表现锁定主导体质","prompt":"最后对照近期最突出的身体症状，确认主导体质与复合调理方向（舌诊仅作筛查，确诊请找当地执业医师）：","options":[{"id":"opt_sym_qi","label":"神疲乏力、少言懒语、坐姿易塌、爬楼气喘易感冒、食后腹胀便溏","hint":"锁定气虚体质：有湿先祛湿，湿退立即补脾（山药薏米芡实粥、八珍糕），戒早起喝凉白开与冰饮（p.63, 66-68, 83-88）。","fig_id":"fig_p063","next_step_id":null,"match_constitution_ids":["qi_deficiency"],"match_sign_ids":["sign_qi_teeth_marks","sign_qi_swollen_tongue","sign_qi_center_crack"]},{"id":"opt_sym_blood","label":"蹲下1分钟站起眼前发黑头晕、记忆力差不愿思考、失眠多梦、夏热冬凉","hint":"锁定血虚体质：可用当归养血鸡汤或玉灵膏养血安神（儿童禁参类、孕妇禁龙眼肉）（p.94-95, 97-102）。","fig_id":"fig_p096","next_step_id":null,"match_constitution_ids":["blood_deficiency"],"match_sign_ids":["sign_blood_mild_pale_edge","sign_blood_typical_transparent"]},{"id":"opt_sym_yang","label":"盛夏也怕冷怕风（腹部下肢尤冷）、沾凉胃痛晨泻、夜尿频多清长","hint":"锁定阳虚体质：肾阳虚夜尿多用金匮肾气丸，脾阳虚沾凉胃痛腹泻用附子理中丸/理中丸（p.147-153）。","fig_id":"fig_p150","next_step_id":null,"match_constitution_ids":["yang_deficiency"],"match_sign_ids":["sign_yang_pale_aged"]},{"id":"opt_sym_yin","label":"手足心烦热、盗汗、眼干便干脉快（或小儿唇红眼袋大易感冒嗓子肿）","hint":"锁定阴虚体质：无湿苔者可煲滋阴汤或服六味地黄丸（湿热与阳虚禁服，脾弱配砂仁冲服）；小儿须少吃肉多吃菜（p.133-136, 140-144）。","fig_id":"fig_p137","next_step_id":null,"match_constitution_ids":["yin_deficiency"],"match_sign_ids":["sign_yin_red_thin_coat","sign_yin_geographic_tongue"]},{"id":"opt_sym_phlegm","label":"应酬肥甘夜宵多、困倦沉重、体检提示血压/血脂/血糖偏高","hint":"锁定痰湿体质：严禁进补，用去生姜温胆汤泡脚，坚持萝卜白菜粗茶淡饭与规律运动“以清为补”（p.155-162）。","fig_id":"fig_p157","next_step_id":null,"match_constitution_ids":["phlegm_dampness"],"match_sign_ids":["sign_phlegm_sticky_fluid","sign_phlegm_frost_thick","sign_phlegm_red_heat_excess"]},{"id":"opt_sym_stagnation","label":"口苦咽干、胸闷肋胀、反酸胃痛、失眠、凌晨3-5点早醒或伴结节增生","hint":"锁定气郁体质：调神安神为先，按证选黄芪建中汤、柴胡加龙骨牡蛎汤加味泡脚（孕妇忌）或敲肺经痛点（p.171-175, 180-189）。","fig_id":"fig_p185","next_step_id":null,"match_constitution_ids":["qi_stagnation"],"match_sign_ids":["sign_stagnation_pointed_red","sign_stagnation_heart_fire_tip"]},{"id":"opt_sym_stasis","label":"善忘、点状黑眼圈、鼻翼钞票纹、肌肤甲错、漱水不欲咽、定处夜痛","hint":"锁定瘀血体质：重用泡脚通络或按部位辨证化瘀（心脏血瘀用三七西洋参粉；孕妇严禁化瘀，便血必先查直肠癌）（p.109-111, 119-128）。","fig_id":"fig_p112","next_step_id":null,"match_constitution_ids":["blood_stasis"],"match_sign_ids":["sign_stasis_tip_spots","sign_stasis_severe_spots","sign_stasis_sublingual_veins"]}]}],"compound_priority_rules":[{"order":1,"title":"先排假象、动态对比","rule":"观舌第一步必须先排除喝橘子汁/浓茶/咖啡/饮酒染苔、晨起气血未充与张口打鼾干燥、饭后半小时内咀嚼充血及食物磨苔/牛奶豆浆白腻、有色灯光或直射阳光偏色、抗生素或化学添加剂黑苔、女性经期舌尖红、化妆口红遮唇瘀、天生舌系带短及天生舌尖偏；孕妇舌现瘀象属正常气血凝聚，严禁化瘀。坚持对比自身舌象变化趋势（p.35-40, 79, 82, 114, 119）。","page":36},{"order":2,"title":"湿重遮蔽、必先祛湿（宜先泡脚）","rule":"当满布白苔或厚腻苔笼罩舌面时，往往将内部热象、阴虚、血瘀或肝郁尖舌遮蔽（湿掩热 p.74、湿罩瘀 p.118-119、湿掩阴虚 p.138、痰湿阻中 p.161）；此时盲目进补或直服六味地黄丸等滋腻药必加重失调（p.142, 159），须先祛湿化痰（脾胃弱不吸药者泡脚优于喝药 p.121, 161），待腻苔退后露出真实舌质再议下一步。","page":74},{"order":3,"title":"祛湿之后、随手补脾防复发","rule":"脾属土、土克水，“脾主统水”。若只祛水湿而不紧接着补脾，康复只是暂时的，三五天后水湿又会卷土重来，久之凝结成顽固痰湿；故湿气一退须马上用怀山药、薏苡仁、芡实粥或八珍糕等补脾养血，带动肾气与肺气恢复（p.64-65, 83, 85）。","page":65},{"order":4,"title":"脾胃为轴、情绪为根，必同步调神疏肝","rule":"复合体质交缠以脾胃失调为中轴，但撬动全局的总根源在情绪（p.132-133, 166-167）。若肝气不舒未解，单吃补脾药易化火，单用活血药难散气郁之瘀（p.128, 133）；调理必须一边疏肝调神求心安，一边同步祛湿、化瘀、滋阴或温阳。","page":133}]},"figures":[{"fig_id":"fig_p001","page":1,"width":888,"height":1233,"rel_path":"assets/figures/fig_p001.webp","book_caption":"图解舌诊：伸伸舌头百病消（封面）","src":"./assets/figures/fig_p001.webp"},{"fig_id":"fig_p029","page":29,"width":1200,"height":627,"rel_path":"assets/figures/fig_p029.webp","book_caption":"舌头的不同部位对应不同的脏腑","src":"./assets/figures/fig_p029.webp"},{"fig_id":"fig_p035","page":35,"width":836,"height":786,"rel_path":"assets/figures/fig_p035.webp","book_caption":"基本健康的舌象，淡红舌、薄白苔","src":"./assets/figures/fig_p035.webp"},{"fig_id":"fig_p047","page":47,"width":656,"height":531,"rel_path":"assets/figures/fig_p047.webp","book_caption":"舌质淡白","src":"./assets/figures/fig_p047.webp"},{"fig_id":"fig_p048","page":48,"width":577,"height":531,"rel_path":"assets/figures/fig_p048.webp","book_caption":"舌质发红","src":"./assets/figures/fig_p048.webp"},{"fig_id":"fig_p056","page":56,"width":658,"height":665,"rel_path":"assets/figures/fig_p056.webp","book_caption":"舌苔焦黑","src":"./assets/figures/fig_p056.webp"},{"fig_id":"fig_p062","page":62,"width":581,"height":833,"rel_path":"assets/figures/fig_p062.webp","book_caption":"气足的人“坐如松”","src":"./assets/figures/fig_p062.webp"},{"fig_id":"fig_p063","page":63,"width":651,"height":840,"rel_path":"assets/figures/fig_p063.webp","book_caption":"气虚的人坐姿歪歪扭扭","src":"./assets/figures/fig_p063.webp"},{"fig_id":"fig_p066","page":66,"width":780,"height":686,"rel_path":"assets/figures/fig_p066.webp","book_caption":"脾气虚，身体肯定湿重","src":"./assets/figures/fig_p066.webp"},{"fig_id":"fig_p068","page":68,"width":668,"height":653,"rel_path":"assets/figures/fig_p068.webp","book_caption":"舌两侧齿痕明显，说明气虚，体内湿气比较重","src":"./assets/figures/fig_p068.webp"},{"fig_id":"fig_p071","page":71,"width":1063,"height":621,"rel_path":"assets/figures/fig_p071.webp","book_caption":"舌苔满布","src":"./assets/figures/fig_p071.webp"},{"fig_id":"fig_p072","page":72,"width":1183,"height":670,"rel_path":"assets/figures/fig_p072.webp","book_caption":"舌质淡白","src":"./assets/figures/fig_p072.webp"},{"fig_id":"fig_p074","page":74,"width":803,"height":803,"rel_path":"assets/figures/fig_p074.webp","book_caption":"舌苔满布，湿气掩盖了舌尖的热像","src":"./assets/figures/fig_p074.webp"},{"fig_id":"fig_p076","page":76,"width":802,"height":727,"rel_path":"assets/figures/fig_p076.webp","book_caption":"舌头上的蕈状乳头偏大，舌尖到舌中部有红点，说明体内有湿热","src":"./assets/figures/fig_p076.webp"},{"fig_id":"fig_p078","page":78,"width":782,"height":743,"rel_path":"assets/figures/fig_p078.webp","book_caption":"舌头圆圆的，有唾液线，是肝气不舒导致体内湿气重","src":"./assets/figures/fig_p078.webp"},{"fig_id":"fig_p080","page":80,"width":671,"height":635,"rel_path":"assets/figures/fig_p080.webp","book_caption":"舌中间出现特别明显的裂纹，说明脾胃气不足","src":"./assets/figures/fig_p080.webp"},{"fig_id":"fig_p081","page":81,"width":690,"height":776,"rel_path":"assets/figures/fig_p081.webp","book_caption":"舌体胖大，是正气不足、脾气虚的表现","src":"./assets/figures/fig_p081.webp"},{"fig_id":"fig_p096","page":96,"width":802,"height":700,"rel_path":"assets/figures/fig_p096.webp","book_caption":"轻微血虚的舌象","src":"./assets/figures/fig_p096.webp"},{"fig_id":"fig_p097","page":97,"width":720,"height":568,"rel_path":"assets/figures/fig_p097.webp","book_caption":"典型的血虚舌象","src":"./assets/figures/fig_p097.webp"},{"fig_id":"fig_p112","page":112,"width":859,"height":640,"rel_path":"assets/figures/fig_p112.webp","book_caption":"舌上有明显瘀点，说明体内已有瘀血","src":"./assets/figures/fig_p112.webp"},{"fig_id":"fig_p113","page":113,"width":770,"height":682,"rel_path":"assets/figures/fig_p113.webp","book_caption":"舌尖和舌两侧出现黑色或青色瘀点，说明瘀血很严重","src":"./assets/figures/fig_p113.webp"},{"fig_id":"fig_p114","page":114,"width":671,"height":637,"rel_path":"assets/figures/fig_p114.webp","book_caption":"舌下条静脉又黑又粗，说明这个人体内的瘀血很严重","src":"./assets/figures/fig_p114.webp"},{"fig_id":"fig_p115","page":115,"width":548,"height":589,"rel_path":"assets/figures/fig_p115.webp","book_caption":"舌尖偏，需要注意瘀血情况","src":"./assets/figures/fig_p115.webp"},{"fig_id":"fig_p117","page":117,"width":1200,"height":536,"rel_path":"assets/figures/fig_p117.webp","book_caption":"湿气与瘀血在一起的舌象","src":"./assets/figures/fig_p117.webp"},{"fig_id":"fig_p118","page":118,"width":653,"height":604,"rel_path":"assets/figures/fig_p118.webp","book_caption":"女性舌象有瘀血的指征，而且嘴唇上汗毛重，内分泌可能有问题","src":"./assets/figures/fig_p118.webp"},{"fig_id":"fig_p119","page":119,"width":608,"height":648,"rel_path":"assets/figures/fig_p119.webp","book_caption":"舌头发紫、发黑，外面被一层白苔笼罩，是湿气把瘀血掩盖了","src":"./assets/figures/fig_p119.webp"},{"fig_id":"fig_p137","page":137,"width":652,"height":630,"rel_path":"assets/figures/fig_p137.webp","book_caption":"阴虚的人舌红苔薄","src":"./assets/figures/fig_p137.webp"},{"fig_id":"fig_p138","page":138,"width":766,"height":702,"rel_path":"assets/figures/fig_p138.webp","book_caption":"阴虚的人，舌苔有时候没有图中那么薄，因为它可能正在转化","src":"./assets/figures/fig_p138.webp"},{"fig_id":"fig_p139","page":139,"width":395,"height":405,"rel_path":"assets/figures/fig_p139.webp","book_caption":"舌头上掉了几块苔，露出红色舌质，这就是地图舌","src":"./assets/figures/fig_p139.webp"},{"fig_id":"fig_p150","page":150,"width":751,"height":722,"rel_path":"assets/figures/fig_p150.webp","book_caption":"阳虚的舌质很淡，舌苔是白的，看上去比较苍老","src":"./assets/figures/fig_p150.webp"},{"fig_id":"fig_p157","page":157,"width":708,"height":779,"rel_path":"assets/figures/fig_p157.webp","book_caption":"舌头上有水液，黏腻，可能已经有三高了","src":"./assets/figures/fig_p157.webp"},{"fig_id":"fig_p158","page":158,"width":632,"height":711,"rel_path":"assets/figures/fig_p158.webp","book_caption":"舌苔厚腻，而且白得像霜一样，已经有三高了","src":"./assets/figures/fig_p158.webp"},{"fig_id":"fig_p159","page":159,"width":802,"height":727,"rel_path":"assets/figures/fig_p159.webp","book_caption":"体内有热，湿气也很重，已经形成痰湿","src":"./assets/figures/fig_p159.webp"},{"fig_id":"fig_p176","page":176,"width":535,"height":676,"rel_path":"assets/figures/fig_p176.webp","book_caption":"肝气郁结的舌头伸出来是尖尖的，发红","src":"./assets/figures/fig_p176.webp"},{"fig_id":"fig_p177","page":177,"width":679,"height":708,"rel_path":"assets/figures/fig_p177.webp","book_caption":"肝气不舒、体内湿气很重的舌象","src":"./assets/figures/fig_p177.webp"},{"fig_id":"fig_p178","page":178,"width":815,"height":739,"rel_path":"assets/figures/fig_p178.webp","book_caption":"舌头尖尖的，边上、舌尖红，白苔","src":"./assets/figures/fig_p178.webp"},{"fig_id":"fig_p179","page":179,"width":604,"height":796,"rel_path":"assets/figures/fig_p179.webp","book_caption":"舌头变红说明有心火","src":"./assets/figures/fig_p179.webp"},{"fig_id":"fig_p185","page":185,"width":1200,"height":1051,"rel_path":"assets/figures/fig_p185.webp","book_caption":"肺经循行路线","src":"./assets/figures/fig_p185.webp"}]};
